	ld sp,0f200h		;4011   ; la pila
	call 00041h		;4014   ; DISSCR
	call 00138h		;4017   ; RSLREG: el slot de la pagina 1...
	rrca			;401a   ; el de la pagina 1 (bits 2-3)...
