	call 00024h		;4035   ; ENASLT
	jp arranque		;4038   ; al arranque
prota_cara:		; La marca del protagonista en el marcador de la derecha (el sprite 0xE170, dibujo 0x7C): su Y, 0x68 + la vista x 3 + la Y del protagonista / 64; su X, 0xD8 + su X / 16, pero no menos que la tabla de 0x4089; el color 15, que se apaga cada 16 cuadros
