	ld a,(0e308h)		;403f   ; la vista
	ld b,a			;4042   ; la vista...
	sla a		;4043   ; ...x 3...
	add a,b			;4045
	add a,068h		;4046   ; ...+ 0x68
	ld b,a			;4048
	ld a,(0e100h)		;4049   ; la Y del protagonista...
	and 0c0h		;404c   ; ...entre 64
	rlca			;404e
	rlca			;404f
	add a,b			;4050   ; sumadas
	ld (ix+000h),a		;4051   ; la Y de la marca
	ld e,0c0h		;4054   ; 0xC0: sin limite
	cp 086h		;4056   ; fuera de la tabla?
	jr nc,prota_cara_x		;4058
	sub 068h		;405a   ; la fila de la tabla
	ld e,a			;405c
	ld d,000h		;405d
	ld hl,04089h		;405f   ; la tabla de 0x4089
	add hl,de			;4062
	ld e,(hl)			;4063   ; la X minima
prota_cara_x:
	ld a,(0e101h)		;4064   ; la X del protagonista...
	and 0f0h		;4067   ; ...entre 16...
	rrca			;4069
	rrca			;406a
	rrca			;406b
	rrca			;406c
	add a,0d8h		;406d   ; ...+ 0xD8
	cp e			;406f   ; menos que la minima?
	jr nc,prota_cara_pon		;4070
	ld a,e			;4072   ; la minima
prota_cara_pon:
	ld (ix+001h),a		;4073   ; la X de la marca
	ld (ix+002h),07ch		;4076   ; el dibujo 0x7C
	ld a,(0e016h)		;407a   ; cada 16 cuadros...
	and 010h		;407d   ; ...el bit 4...
	rlca			;407f   ; ...pasa al 0...
	rlca			;4080
	rlca			;4081
	rlca			;4082
	add a,00fh		;4083   ; ...+ 15: 15, o 0 (transparente)
	ld (ix+003h),a		;4085   ; el color
	ret			;4088

