; ======================================================================
; CODIGO 0x5178..0x51be  (70 bytes)
; ======================================================================


premio_pantalla:		; La pantalla del premio: sus propias casillas (0xE04A = 0xFF: las de 0x6980 y 0x7980), y un dibujo de 22 filas (0x51BE) desde la fila 2, con repeticiones (0xFn x: n veces x; 0xFF, la fila siguiente)
	ld a,0ffh		;5178   ; 0xE04A = 0xFF...
	ld (0e04ah),a		;517a   ; ...para las casillas
	call pantalla_prepara		;517d   ; la pantalla
	xor a			;5180
	ld (0e04ah),a		;5181   ; 0xE04A a 0
	ld hl,01840h		;5184   ; la fila 2
	ld de,051beh		;5187   ; el dibujo
	ld b,016h		;518a   ; 22 filas
	jr premio_fila		;518c   ; (al siguiente)
premio_fila:
	push bc			;518e   ; guardados
	push hl			;518f
premio_byte:
	ld a,(de)			;5190   ; el byte
	and 0f0h		;5191   ; 0xFn?
	cp 0f0h		;5193
	jr z,premio_orden		;5195   ; si
	ld a,(de)			;5197   ; una casilla
	call 0004dh		;5198   ; WRTVRM
	inc hl			;519b   ; la siguiente
	inc de			;519c
	jr premio_byte		;519d   ; otra
premio_orden:
	ld a,(de)			;519f   ; 0xFF?
	cp 0ffh		;51a0
	jr z,premio_fila_fin		;51a2   ; la fila siguiente
	and 00fh		;51a4   ; n veces...
	ld b,a			;51a6
	inc de			;51a7
	ld a,(de)			;51a8   ; ...la casilla siguiente
premio_repite:
	call 0004dh		;51a9   ; WRTVRM
	inc hl			;51ac   ; la siguiente
	djnz premio_repite		;51ad   ; B veces
	inc de			;51af   ; el byte siguiente
	jr premio_byte		;51b0   ; otro
premio_fila_fin:
	inc de			;51b2   ; tras el 0xFF
	pop hl			;51b3   ; el principio de la fila
	push de			;51b4
	ld de,00020h		;51b5   ; una fila abajo
	add hl,de			;51b8
	pop de			;51b9
	pop bc			;51ba   ; recuperado
	djnz premio_fila		;51bb   ; B veces
	ret			;51bd

