pide_efecto_a:		; Pide un efecto del canal A (A, el numero) guardando BC, DE y HL
	push bc			;5401
	push de			;5402
	push hl			;5403
	call salto_efecto_a		;5404   ; al motor (0xB300)
	pop hl			;5407
	pop de			;5408
	pop bc			;5409
	ret			;540a
pide_efecto_bc:		; Pide un efecto de los canales B y C (A, el numero) guardando BC, DE y HL
	push bc			;540b
	push de			;540c
	push hl			;540d
	call salto_efecto_bc		;540e   ; al motor (0xB303)
	pop hl			;5411
