	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7e70  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7e80  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7e90  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7ea0  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7eb0  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7ec0  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7ed0  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7ee0  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7ef0  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7f00  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7f10  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7f20  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7f30  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7f40  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7f50  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7f60  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7f70  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,090h,0b0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,090h,0b0h	; 7f80  ................
	defb 0d0h,070h,0e0h,0e0h,0f0h,0f0h,0f0h,0f0h,0d0h,070h,0e0h,0e0h,0f0h,0f0h,0f0h,0f0h	; 7f90  .p.......p......
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7fa0  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7fb0  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7fc0  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7fd0  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h	; 7fe0  ................
	defb 0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0f0h,0d0h,0d0h,0efh	; 7ff0  ................

; ----------------------------------------------------------------------
; DATOS ceros_8000: Ceros: INIT salta a 0x8010
;   0x8000..0x8010  (16 bytes)
DATA_ceros_8000:
	defb 000h,000h,000h,000h,000h,000h,000h,000h,000h,000h,000h,000h,000h,000h,000h,000h	; 8000  ................

; ======================================================================
; CODIGO 0x8010..0x81a4  (404 bytes)
; ======================================================================


arranque:		; El arranque: la RAM de 0xE000 a cero (0x1100 bytes), la interrupcion en H.TIMI (0xAE9A), SCREEN 2 en negro, las letras (0x6680), la pantalla y los sprites
	call 00041h		;8010   ; DISSCR
	ld hl,0e000h		;8013   ; la RAM...
	ld de,0e001h		;8016
	ld (hl),000h		;8019   ; ...a cero...
	ld bc,01100h		;801b   ; ...0x1100 bytes
	ldir		;801e   ; copiados
	ld sp,0f200h		;8020   ; la pila
	ld hl,0ae9ah		;8023   ; la interrupcion...
	ld (0fda0h),hl		;8026   ; ...en H.TIMI...
	ld a,0c3h		;8029   ; ...con su "jp"
	ld (0fd9fh),a		;802b   ; ...0xFD9F
	call 0007eh		;802e   ; SETGRP: SCREEN 2
	xor a			;8031   ; fondo y borde negros...
	ld (0f3eah),a		;8032   ; BAKCLR = 0
	ld (0f3ebh),a		;8035   ; BDRCLR = 0
	dec a			;8038   ; ...letras blancas (0xFF)
	ld (0f3e9h),a		;8039   ; FORCLR = 0xFF
	call 00062h		;803c   ; CHGCLR
	ld de,00000h		;803f   ; las letras del cartucho (0x6680) en los tres tercios
	ld b,003h		;8042   ; tres tercios
init_letras:
	call letras_pon		;8044   ; las letras
	djnz init_letras		;8047   ; B veces
	xor a			;8049   ; los colores de 0x80 casillas a 0...
	ld hl,00080h		;804a
	ld b,003h		;804d   ; ...en los tres tercios
init_colores:
	call colores_tercio		;804f
	djnz init_colores		;8052   ; B veces
	ld hl,02000h		;8054   ; los colores de las casillas 0x400-0x1BFF...
	ld bc,01800h		;8057
	ld a,0f0h		;805a   ; ...blanco sobre negro
	call 00056h		;805c   ; FILVRM
	call sprites_dibujos		;805f   ; los dibujos de los sprites
	ld hl,0fbf0h		;8062   ; el buffer del teclado vacio
	ld (0f3f8h),hl		;8065   ; GETPNT = PUTPNT: nada en el buffer
	ld (0f3fah),hl		;8068   ; PUTPNT
	ld a,0a2h		;806b   ; el registro 1 a 0xA2: la pantalla apagada, sprites de 16 x 16
	ld b,a			;806d   ; el valor
	ld c,001h		;806e   ; el registro 1
	call 00047h		;8070   ; WRTVDP
	ld a,001h		;8073   ; 0xE030 = 1
	ld (0e030h),a		;8075   ; 0xE030 = 1
	ld a,010h		;8078   ; 0xE035 = 0x10
	ld (0e035h),a		;807a
titulo:		; El titulo: la pantalla, la presentacion de CASIO; las teclas SELECT (0xE023 = 1) y ESC (0xE039 = 2, 0xE032 = 0x50); el titulo (0xE700) con el nombre, los textos y los creditos (0x81A4) debajo; tras 0x80 cuadros, los creditos suben (0xE364, cada 16 cuadros) y despues la demostracion; con el boton, la partida
	call sprites_borra		;807d   ; a cero
	call silencio		;8080
	call pantalla_prepara		;8083
	call cuentas_borra		;8086
	ld hl,0e100h		;8089   ; 0xE100-0xE180 a cero
	ld de,0e101h		;808c
	ld bc,00080h		;808f
	ld (hl),000h		;8092
	ldir		;8094   ; copiados
	xor a			;8096
	ld (0e024h),a		;8097
	ld (0e325h),a		;809a
	ld (0e361h),a		;809d   ; en el paso del titulo
	call pantalla_casillas		;80a0   ; la pantalla
	call 00044h		;80a3   ; ENASCR
	call presentacion		;80a6   ; la presentacion de CASIO
	ld a,007h		;80a9   ; la fila 7...
	call 00141h		;80ab   ; SNSMAT
	bit 6,a		;80ae   ; SELECT (bit 6)?
	jr nz,titulo_tecla_esc		;80b0
	ld a,001h		;80b2   ; pulsada: 0xE023 = 1
	ld (0e023h),a		;80b4   ; en SELECT
titulo_tecla_esc:
	ld a,007h		;80b7   ; la fila 7 otra vez
	call 00141h		;80b9   ; SNSMAT
	bit 2,a		;80bc   ; ESC (bit 2)?
	jp nz,titulo_pon		;80be
	ld a,002h		;80c1   ; pulsada: 0xE039 = 2...
	ld (0e039h),a		;80c3   ; en ESC
	ld a,050h		;80c6   ; ...y 0xE032 = 0x50
	ld (0e032h),a		;80c8
titulo_pon:
	ld hl,0e100h		;80cb   ; 0xE100-0xE180 a cero
	ld de,0e101h		;80ce
	ld bc,00080h		;80d1
	ld (hl),000h		;80d4
	ldir		;80d6   ; copiados
	call titulo_ram		;80d8   ; el titulo en la RAM
	xor a			;80db   ; la cuenta a 0
	ld (0e014h),a		;80dc   ; en la cuenta de cuadros
	ld (0e100h),a		;80df
titulo_espera:
	ld a,(0e014h)		;80e2   ; 16 cuadros
	cp 010h		;80e5
	jr c,titulo_espera		;80e7
	call cuentas_borra		;80e9   ; a cero
	ld (0e021h),a		;80ec   ; en el boton
	xor a			;80ef
	ld (0e014h),a		;80f0   ; en la cuenta de cuadros
titulo_bucle:
	ld a,(0e021h)		;80f3   ; el boton?
	and a			;80f6
	jr nz,titulo_boton		;80f7
	ld a,(0e026h)		;80f9   ; o la barra?
	and a			;80fc
	jr nz,titulo_boton		;80fd
	jr titulo_suelto		;80ff
titulo_boton:
	ld a,(0e107h)		;8101   ; ya soltada?
	and a			;8104
	jp z,partida_empieza		;8105   ; si: la partida
	ld a,008h		;8108   ; la barra, aun pulsada?
	call 00141h		;810a   ; SNSMAT
	rrca			;810d
	jr c,titulo_paso		;810e
	xor a			;8110
	ld (0e026h),a		;8111   ; en el boton de empezar
	jr titulo_paso		;8114
titulo_suelto:
	xor a			;8116   ; soltado
	ld (0e107h),a		;8117
titulo_paso:
	ld a,(0e361h)		;811a   ; el paso del titulo (0xE361)
	and a			;811d
	jr z,titulo_paso0		;811e
	rrca			;8120
	jr c,titulo_sube		;8121
	rrca			;8123
	jr c,titulo_vuelve		;8124
	jr titulo_espera_demo		;8126
titulo_paso0:
	ld a,(0e014h)		;8128   ; 0x80 cuadros
	cp 080h		;812b
	jr c,titulo_bucle		;812d
	call titulo_paso_mas		;812f   ; el paso siguiente
	ld a,003h		;8132   ; el efecto 3
	call pide_efecto_bc		;8134
	ld hl,0e6e0h		;8137   ; los creditos, desde 0xE6E0
	ld (0e364h),hl		;813a
	jr titulo_bucle		;813d
titulo_sube:
	ld a,(0e014h)		;813f   ; cada 16 cuadros...
	cp 010h		;8142
	jr c,titulo_bucle		;8144
	xor a			;8146
	ld (0e014h),a		;8147   ; en la cuenta de cuadros
	ld hl,(0e364h)		;814a   ; ...una fila mas
	ld de,00020h		;814d
	add hl,de			;8150
	ld (0e364h),hl		;8151
	ld a,h			;8154   ; el final (0xED00)?
	cp 0edh		;8155
	jr nc,titulo_sube_fin		;8157
	ld bc,00300h		;8159   ; la pantalla
	ld de,01800h		;815c
	call 0005ch		;815f   ; LDIRVM
	jr titulo_bucle		;8162
titulo_sube_fin:
	call titulo_paso_mas		;8164
	jp titulo_bucle		;8167
titulo_vuelve:
	ld a,(0e014h)		;816a   ; 0x20 cuadros
	cp 020h		;816d
	jr c,titulo_bucle		;816f
	call titulo_paso_mas		;8171
	call titulo_vram		;8174   ; el titulo otra vez
	xor a			;8177
	ld (0e014h),a		;8178   ; en la cuenta de cuadros
	ld (0e10ch),a		;817b
	jp titulo_bucle		;817e
titulo_espera_demo:
	ld a,(0e014h)		;8181   ; cada 0x1F cuadros...
	cp 01fh		;8184
	jp c,titulo_bucle		;8186
	xor a			;8189
	ld (0e014h),a		;818a   ; en la cuenta de cuadros
	ld a,(0e10ch)		;818d   ; ...una cuenta mas...
	inc a			;8190
	ld (0e10ch),a		;8191
	cp 00fh		;8194   ; ...0x0F: la demostracion
	jp c,titulo_bucle		;8196
	jp demo_empieza		;8199
titulo_paso_mas:
	ld a,(0e361h)		;819c   ; el paso del titulo
	inc a			;819f
	ld (0e361h),a		;81a0   ; en el paso del titulo
	ret			;81a3

; ----------------------------------------------------------------------
; DATOS creditos: STAFF, K;ARISAWA, K;ASAHINA, K;SATOH, K;OKUYAMA, A;HASEGAWA,
;   K;OHSAWA, J;ARCHER, PRODUCER y T;MORIYAMA (0xFF: la fila siguiente; 0x7F:
;   el final)
;   0x81a4..0x8206  (98 bytes)
DATA_creditos:
	defb 010h,010h,023h,024h,011h,016h,016h,0ffh,01bh,00bh,011h,022h,019h,023h,011h,027h	; 81a4  ..#$.......".#.'
	defb 011h,0ffh,01bh,00bh,011h,023h,011h,018h,019h,01eh,011h,0ffh,01bh,00bh,023h,011h	; 81b4  .....#........#.
	defb 024h,01fh,018h,0ffh,01bh,00bh,01fh,01bh,025h,029h,011h,01dh,011h,0ffh,011h,00bh	; 81c4  $.......%)......
	defb 018h,011h,023h,015h,017h,011h,027h,011h,0ffh,01bh,00bh,01fh,018h,023h,011h,027h	; 81d4  ..#...'......#.'
	defb 011h,0ffh,01ah,00bh,011h,022h,013h,018h,015h,022h,0ffh,0ffh,010h,020h,022h,01fh	; 81e4  ....."..."... ".
	defb 014h,025h,013h,015h,022h,0ffh,0ffh,024h,00bh,01dh,01fh,022h,019h,029h,011h,01dh	; 81f4  .%.."..$...".)..
	defb 011h,07fh	; 8204

; ======================================================================
; CODIGO 0x8206..0x83b9  (435 bytes)
; ======================================================================


demo_empieza:		; La demostracion: sin vidas, la fase 0, 0xE027 = 1
	xor a			;8206
	ld (0e00bh),a		;8207   ; en las vidas
	ld (0e00ah),a		;820a   ; en la fase
	inc a			;820d
	ld (0e027h),a		;820e   ; en la demostracion
	jp fase_empieza		;8211
partida_empieza:		; Una partida: jugando, la ronda 1, cinco vidas (0xE00B), el record a cero
	ld a,001h		;8214   ; 0xE009 = 1...
	ld (0e009h),a		;8216
	ld (0e000h),a		;8219   ; ...y jugando
	ld a,005h		;821c   ; 5 vidas
	ld (0e00bh),a		;821e   ; en las vidas
	call cuentas_borra		;8221
	xor a			;8224   ; 0xE034-0xE036 a cero
	ld (0e036h),a		;8225
	ld (0e035h),a		;8228
	ld (0e034h),a		;822b
	jp fase_empieza		;822e
cuentas_borra:		; Las cuentas y los botones a cero; 0xE107 = 1
	xor a			;8231
	ld (0e183h),a		;8232   ; en tocado
	ld (0e104h),a		;8235
	ld (0e1b3h),a		;8238   ; en F1
	ld (0e30fh),a		;823b   ; en 0xE30F (lo que protege)
	ld (0e30ch),a		;823e   ; en 0xE30C
	ld (0e30eh),a		;8241
	ld (0e30dh),a		;8244
	ld (0e330h),a		;8247
	ld (0e326h),a		;824a   ; en mirando
	ld (0e021h),a		;824d   ; en el boton
	ld (0e02dh),a		;8250
	ld (0e02bh),a		;8253
	ld (0e19dh),a		;8256
	ld (0e104h),a		;8259
	ld (0e325h),a		;825c
	ld (0e026h),a		;825f   ; en el boton de empezar
	inc a			;8262
	ld (0e107h),a		;8263
	ret			;8266
titulo_ram:		; El titulo en la pantalla de la RAM (0xE700, 0x900 bytes a 0x10): el nombre (0x543D, cuatro filas de 16), CASIO (0x419B), PUSH TRIG1 OR SPACE (0x41A1), COPYRIGHT (0x41B6), GAME START (0x41CC) y los creditos (0x81A4) mas abajo
	ld hl,0e700h		;8267   ; la pantalla de la RAM...
	ld de,0e701h		;826a
	ld bc,00900h		;826d
	ld (hl),010h		;8270   ; ...a 0x10
	ldir		;8272   ; copiados
	ld de,0e7c8h		;8274   ; el nombre: cuatro filas de 16
	ld hl,0543dh		;8277
	ld b,004h		;827a
titulo_ram_fila:
	push bc			;827c   ; guardados
	push de			;827d
	push hl			;827e
	ld bc,00010h		;827f   ; 16 bytes
	ldir		;8282   ; copiados
	pop hl			;8284
	push de			;8285
	ld de,00010h		;8286   ; los 16 siguientes...
	add hl,de			;8289
	pop de			;828a
	pop de			;828b   ; ...de la ROM
	push hl			;828c
	ld hl,00020h		;828d   ; una fila mas abajo...
	add hl,de			;8290
	ex de,hl			;8291   ; ...en la RAM
	pop hl			;8292
	pop bc			;8293   ; recuperado
	djnz titulo_ram_fila		;8294   ; B veces
	ld hl,0419bh		;8296   ; CASIO
	ld de,0e78dh		;8299   ; en la fila 12, columna 13
	ld bc,00006h		;829c   ; 6 letras
	ldir		;829f   ; copiados
	ld hl,041a1h		;82a1   ; PUSH TRIG1 OR SPACE
	ld de,0e966h		;82a4   ; en la fila 19, columna 6
	ld bc,00014h		;82a7   ; 20 letras
	ldir		;82aa   ; copiados
	ld hl,041b6h		;82ac   ; COPYRIGHT 1986 (c) CASIO
	ld de,0e8c5h		;82af   ; en la fila 14, columna 5
	ld bc,00016h		;82b2   ; 22 letras
	ldir		;82b5   ; copiados
	ld hl,041cch		;82b7   ; GAME START
	ld de,0e90ah		;82ba   ; en la fila 16, columna 10
	ld bc,0000ah		;82bd   ; 10 letras
	ldir		;82c0   ; copiados
	ld hl,0ea13h		;82c2   ; en la fila 24 (fuera de la pantalla), columna 19
	ld de,081a4h		;82c5   ; de 0x81A4
creditos_fila:
	push hl			;82c8
	ld a,(de)			;82c9   ; una letra
	cp 0ffh		;82ca   ; 0xFF al principio?
	jr nz,creditos_letra		;82cc   ; no
	push de			;82ce
	ld de,00020h		;82cf   ; una fila mas abajo
	add hl,de			;82d2
	pop de			;82d3
	inc de			;82d4   ; la siguiente
creditos_letra:
	ld a,(de)			;82d5   ; 0xFF: la fila siguiente
	cp 0ffh		;82d6
	jr z,creditos_fila_siguiente		;82d8
	cp 07fh		;82da   ; 0x7F: el final
	jr z,creditos_fin		;82dc
	ld (hl),a			;82de   ; en la RAM
	inc hl			;82df   ; la siguiente
	inc de			;82e0
	jr creditos_letra		;82e1   ; otra
creditos_fila_siguiente:
	pop hl			;82e3   ; el principio de la fila
	push de			;82e4
	ld de,00040h		;82e5   ; dos filas mas abajo
	add hl,de			;82e8
	pop de			;82e9   ; recuperado
	inc de			;82ea   ; la letra siguiente
	jr creditos_fila		;82eb   ; otra fila
creditos_fin:
	pop hl			;82ed   ; recuperado
titulo_vram:		; La pantalla de la RAM (0xE700) a la VRAM y ENASCR
	ld hl,0e700h		;82ee   ; la pantalla de la RAM...
	ld de,01800h		;82f1   ; ...en la tabla de nombres
	ld bc,00300h		;82f4   ; 0x300 casillas
	call 0005ch		;82f7   ; LDIRVM
	jp 00044h		;82fa   ; ENASCR
fase_empieza:		; La fase: la lista de mandos de la demostracion (0x5700), las cuentas, la pantalla; en partida, el selector de fase: con dos teclas pulsadas, la fase de salida (A o B con 0 o 5: las fases 0, 5, 12 y 18; Z, Y, X, W o V con C-R: la tabla de 0x83B9)
	ld hl,05700h		;82fd   ; la lista de mandos de la demostracion
	ld (0e037h),hl		;8300
	call cuentas_borra		;8303
	call silencio		;8306
	call pantalla_prepara		;8309
	call sprites_borra		;830c
	ld a,(0e000h)		;830f   ; jugando?
	and a			;8312
	jp z,fase_colores		;8313
	ld bc,00000h		;8316
	ld a,002h		;8319   ; la fila 2
	call 00141h		;831b   ; SNSMAT
	ld c,00ch		;831e   ; la B (bit 7)?
	rlca			;8320
	jr nc,selector_ab		;8321
	ld c,0ffh		;8323   ; la A (bit 6)?
	rlca			;8325
	jr nc,selector_ab		;8326
	ld a,005h		;8328   ; la fila 5
	call 00141h		;832a   ; SNSMAT
	ld e,a			;832d
	ld a,003h		;832e   ; la Z (bit 7): con la fila 3...
	ld c,000h		;8330
	rlc e		;8332
	jr nc,selector_par		;8334
	inc a			;8336   ; ...la Y: con la 4...
	ld c,004h		;8337
	rlc e		;8339
	jr nc,selector_par		;833b
	inc a			;833d   ; ...la X: con la 5...
	ld c,008h		;833e
	rlc e		;8340
	jr nc,selector_par		;8342
	ld a,003h		;8344   ; ...la W: con la 3 (los bits impares)...
	ld c,00ch		;8346
	rlc e		;8348
	jr nc,selector_impar		;834a
	inc a			;834c   ; ...la V: con la 4
	ld c,010h		;834d
	rlc e		;834f
	jr nc,selector_impar		;8351
	jp fase_colores		;8353
selector_ab:
	push bc			;8356
	xor a			;8357   ; la fila 0
	call 00141h		;8358   ; SNSMAT
	pop bc			;835b
	ld b,000h		;835c
	bit 0,a		;835e   ; el 0?
	jr z,selector_ab_fase		;8360
	ld b,006h		;8362   ; el 5?
	bit 5,a		;8364
	jr nz,$+104		;8366
selector_ab_fase:
	ld a,b			;8368   ; la fase
	add a,c			;8369
	cp 0ffh		;836a
	jp nz,selector_pon		;836c
	inc a			;836f
	jp selector_pon		;8370
selector_impar:
	push bc			;8373
	call 00141h		;8374   ; SNSMAT
	rrca			;8377
	jr selector_letra		;8378
selector_par:
	push bc			;837a
	call 00141h		;837b   ; SNSMAT
selector_letra:
	pop bc			;837e
	rrca			;837f   ; la primera letra de la fila?
	jr nc,selector_tabla		;8380
	inc c			;8382   ; la siguiente...
	rrca			;8383
	rrca			;8384
	jr nc,selector_tabla		;8385
	inc c			;8387
	rrca			;8388
	rrca			;8389
	jr nc,selector_tabla		;838a
	inc c			;838c
	rrca			;838d
	rrca			;838e
	jr nc,selector_tabla		;838f
	ld a,c			;8391   ; ninguna: la X?
	cp 004h		;8392
	ld a,005h		;8394
	call 00141h		;8396   ; SNSMAT
	bit 5,a		;8399
	jp nz,fase_colores		;839b
	ld c,00bh		;839e   ; la 11
selector_tabla:
	ld a,c			;83a0
	cp 018h		;83a1   ; dentro de la tabla?
	jr c,selector_tabla_lee		;83a3
	jr $+41		;83a5
selector_tabla_lee:
	ld e,a			;83a7
	ld d,000h		;83a8
	ld hl,083b9h		;83aa   ; la tabla de 0x83B9
	add hl,de			;83ad
	ld a,(hl)			;83ae
	cp 0ffh		;83af   ; 0xFF: nada
	jp z,fase_colores		;83b1
selector_pon:
	ld (0e00ah),a		;83b4   ; la fase de salida
	jr $+23		;83b7

; ----------------------------------------------------------------------
; DATOS selector_fases: Las fases del selector (21; 0xFF al final)
;   0x83b9..0x83ce  (21 bytes)
DATA_selector_fases:
	defb 001h,004h,00dh,011h,002h,01eh,018h,016h,009h,008h,00ah,019h,015h,014h,00eh,006h	; 83b9  ................
	defb 010h,01dh,01ch,01ah,0ffh	; 83c9

; ======================================================================
; CODIGO 0x83ce..0x847b  (173 bytes)
; ======================================================================


fase_colores:		; Los colores de la fase: segun 0xE00A (cada cuatro, 0x864E)
	ld a,(0e00ah)		;83ce   ; la fase
	and 003h		;83d1   ; de cuatro en cuatro
	cp 003h		;83d3   ; cada cuarta (la 3, 7...): el BONUS
	jr z,fase_colores_bonus		;83d5
	ld a,(0e00ah)		;83d7   ; de cuatro en cuatro...
	and 01ch		;83da   ; las fases de cuatro en cuatro...
	rrca			;83dc   ; ...entre 4 (0-7)
	rrca			;83dd
	ld e,a			;83de
	ld d,000h		;83df   ; D = 0
	ld hl,0864eh		;83e1   ; ...su color (0x864E)
	add hl,de			;83e4   ; + la vuelta
	ld a,(hl)			;83e5   ; el color
	ld hl,02180h		;83e6   ; las casillas 0x30-0x37 de los tres tercios...
	ld b,040h		;83e9   ; 0x40 bytes: 8 casillas
	call colores_llena		;83eb   ; llenos
	ld hl,02980h		;83ee   ; en el segundo tercio
	ld b,040h		;83f1
	call colores_llena		;83f3
	ld hl,03180h		;83f6   ; en el tercero
	ld b,040h		;83f9
	call colores_llena		;83fb
	ld hl,021e0h		;83fe   ; ...y las 0x3C-0x3D
	ld b,010h		;8401   ; 0x10 bytes: 2 casillas
	call colores_llena		;8403
	ld hl,029e0h		;8406   ; en el segundo tercio
	ld b,010h		;8409
	call colores_llena		;840b
	ld hl,031e0h		;840e   ; en el tercero
	ld b,010h		;8411
	call colores_llena		;8413
	jr fase_bonus_cartel		;8416   ; al cartel
colores_llena:		; B bytes del color A desde HL (WRTVRM)
	call 0004dh		;8418   ; WRTVRM
	inc hl			;841b   ; la siguiente
	djnz colores_llena		;841c   ; B veces
	ret			;841e
fase_colores_bonus:		; En el BONUS, los colores de las casillas en franjas (0x40 y 0x80, mas 0x40 cada vez)
	ld hl,02180h		;841f   ; las casillas 0x30-0x37...
	ld b,008h		;8422   ; 8 franjas
	call colores_franja		;8424
	ld hl,02980h		;8427   ; en el segundo tercio
	ld b,008h		;842a
	call colores_franja		;842c
	ld hl,03180h		;842f   ; en el tercero
	ld b,008h		;8432
	call colores_franja		;8434
	ld hl,021e0h		;8437   ; las 0x3C-0x3D
	ld b,001h		;843a   ; una franja
	call colores_franja		;843c
	ld hl,029e0h		;843f   ; en el segundo tercio
	ld b,001h		;8442
	call colores_franja		;8444
	ld hl,031e0h		;8447   ; en el tercero
	ld b,001h		;844a
	call colores_franja		;844c
	jr fase_bonus_cartel		;844f   ; al cartel
colores_franja:		; B franjas de 8 bytes de color: 4 de 0x40 y 4 de 0x80 (que suben de 0x40 en 0x40 cada vez)
	ld c,004h		;8451   ; 4 bytes...
	ld a,040h		;8453   ; ...del color 0x40
colores_franja_1:
	call 0004dh		;8455   ; WRTVRM
	inc hl			;8458
	dec c			;8459   ; 4?
	jr nz,colores_franja_1		;845a
	ld c,004h		;845c   ; otros 4...
	ld a,080h		;845e   ; ...del color 0x80
colores_franja_2:
	call 0004dh		;8460   ; WRTVRM
	inc hl			;8463
	dec c			;8464
	jr nz,colores_franja_2		;8465
	ld c,004h		;8467
	add a,020h		;8469
	add a,020h		;846b
	djnz colores_franja		;846d   ; B veces
	ret			;846f
fase_bonus_cartel:		; En el BONUS, BONUS GAME (0x847B) en la fila 8 y 0x40 cuadros de espera
	ld a,(0e00ah)		;8470   ; el BONUS?
	and 003h		;8473
	cp 003h		;8475
	jr nz,$+38		;8477
	jr $+13		;8479

; ----------------------------------------------------------------------
; DATOS bonus_texto: BONUS GAME y 0xFF
;   0x847b..0x8486  (11 bytes)
DATA_bonus_texto:
	defb 012h,01fh,01eh,025h,023h,010h,017h,011h,01dh,015h,0ffh	; 847b  ...%#......

; ======================================================================
; CODIGO 0x8486..0x8517  (145 bytes)
; ======================================================================


fase_bonus_va:
	ld hl,0190ah		;8486   ; la fila 8, columna 10
	ld de,0847bh		;8489
	call texto_vram		;848c   ; escrito
	call 00044h		;848f   ; ENASCR
	xor a			;8492
	ld (0e01ah),a		;8493
fase_bonus_espera:
	ld a,(0e01ah)		;8496   ; 0x40 cuadros
	cp 040h		;8499
	jr c,fase_bonus_espera		;849b
fase_monta:		; La fase: la RAM del mapa (0xE800, 0x790 bytes) y los objetos (0xE600) a cero; los datos de la fase (0x5078, 8 bytes: dos punteros, la altura de salida y otro puntero, en 0xE313-0xE31A); la pantalla
	ld hl,0e800h		;849d   ; 0xE800-0xEF8F a cero
	ld de,0e801h		;84a0   ; el siguiente
	ld (hl),000h		;84a3   ; a cero
	ld bc,00790h		;84a5   ; 0x790 bytes
	ldir		;84a8   ; copiados
	ld hl,0e600h		;84aa   ; 0xE600-0xE66F a cero
	ld de,0e601h		;84ad   ; el siguiente
	ld (hl),000h		;84b0   ; a cero
	ld bc,00070h		;84b2   ; 0x70 bytes
	ldir		;84b5   ; copiados
	call sprites_borra		;84b7   ; los sprites fuera
	ld a,(0e00ah)		;84ba   ; la fase...
	ld e,a			;84bd
	xor a			;84be   ; A = 0
	sla e		;84bf   ; ...x 8
	adc a,000h		;84c1   ; (lo que sale, a A)
	sla a		;84c3
	sla e		;84c5
	adc a,000h		;84c7
	sla a		;84c9
	sla e		;84cb
	adc a,000h		;84cd
	ld d,a			;84cf   ; DE: la fase x 8
	ld hl,05078h		;84d0   ; su entrada (0x5078)
	add hl,de			;84d3
	ld e,(hl)			;84d4
	inc hl			;84d5   ; (el byte alto)
	ld d,(hl)			;84d6
	ld (0e313h),de		;84d7   ; el primer puntero
	inc hl			;84db
	ld e,(hl)			;84dc
	inc hl			;84dd
	ld d,(hl)			;84de
	ld (0e315h),de		;84df   ; el segundo
	inc hl			;84e3
	ld a,(hl)			;84e4   ; la altura de salida
	ld (0e317h),a		;84e5
	inc hl			;84e8
	inc hl			;84e9   ; (el byte 5 no se lee)
	ld e,(hl)			;84ea   ; el tercero
	inc hl			;84eb
	ld d,(hl)			;84ec
	ld (0e319h),de		;84ed
	call 00041h		;84f1   ; DISSCR
	call nada_911e		;84f4   ; nada (un "ret")
	call fase_pantalla		;84f7   ; las casillas de la fase
	call mapa_ram		;84fa   ; el mapa en la RAM
	call mapa_pinta		;84fd   ; el mapa en la VRAM
	call fase_cosas		;8500   ; lo que hay en el mapa
	call mapa_objetos		;8503   ; los objetos
	call marcador_dibujo		;8506   ; el marcador
	call 00044h		;8509   ; ENASCR
	ld a,(0e317h)		;850c   ; la altura...
	ld (0e308h),a		;850f   ; ...de la vista
	call nada_911f		;8512   ; nada (un "ret")
	jr $+84		;8515   ; al numero de la fase

; ----------------------------------------------------------------------
; DATOS bonus_marcador: BONUS y 0xFF
;   0x8517..0x851e  (7 bytes)
DATA_bonus_marcador:
	defb 012h,01fh,01eh,025h,023h,010h,0ffh	; 8517

; ----------------------------------------------------------------------
; DATOS fases_numeros: Las dos cifras de cada fase en el marcador (0, 1, 2, 3
;   cada cuatro: el BONUS sin numero)
;   0x851e..0x855e  (64 bytes)
fase_numero:		; El numero de la fase en el marcador (dos cifras, la tabla de 0x851E); en el BONUS, BONUS
	defb 001h,010h,002h,010h,003h,010h,000h,000h,004h,010h,005h,010h,006h,010h,000h,000h	; 851e  ................
	defb 007h,010h,008h,010h,009h,010h,000h,000h,000h,001h,001h,001h,002h,001h,000h,000h	; 852e  ................
	defb 003h,001h,004h,001h,005h,001h,000h,000h,006h,001h,007h,001h,008h,001h,000h,000h	; 853e  ................
	defb 009h,001h,000h,002h,001h,002h,000h,000h,002h,002h,003h,002h,004h,002h,000h,000h	; 854e  ................

; ======================================================================
; CODIGO 0x855e..0x85b5  (87 bytes)
; ======================================================================


fase_numero_bonus:
	ld hl,018bah		;855e   ; BONUS en la fila 5, columna 26
	ld de,08517h		;8561
	call texto_vram		;8564
	jr fase_tiempo_pon		;8567
fase_numero_pon:
	ld a,(0e00ah)		;8569   ; la fase
	ld e,a			;856c
	and 003h		;856d
	cp 003h		;856f   ; el BONUS?
	jr z,fase_numero_bonus		;8571
	rlc e		;8573   ; x 2
	ld d,000h		;8575
	ld hl,0851eh		;8577   ; la tabla
	add hl,de			;857a
	ld a,(hl)			;857b
	push hl			;857c
	ld hl,018bdh		;857d   ; la cifra de abajo
	call 0004dh		;8580   ; WRTVRM
	pop hl			;8583
	inc hl			;8584
	ld a,(hl)			;8585
	ld hl,018bch		;8586   ; la de arriba
	call 0004dh		;8589   ; WRTVRM
fase_tiempo_pon:		; El tiempo de la fase (0x85B5): con el bit 7, los segundos (0xE320); si no, los minutos (0xE31F); 0xE113 = 8
	ld a,008h		;858c
	ld (0e113h),a		;858e
	ld a,(0e00ah)		;8591   ; la fase
	ld e,a			;8594
	ld d,000h		;8595
	ld hl,085b5h		;8597   ; la tabla de 0x85B5
	add hl,de			;859a
	ld a,(hl)			;859b
	bit 7,a		;859c   ; el bit 7: segundos?
	jr nz,fase_tiempo_segundos		;859e
	ld (0e31fh),a		;85a0   ; en los minutos
	ld a,000h		;85a3
	ld (0e320h),a		;85a5   ; en los segundos
	jr $+66		;85a8
fase_tiempo_segundos:
	res 7,a		;85aa
	ld (0e320h),a		;85ac   ; en los segundos
	xor a			;85af
	ld (0e31fh),a		;85b0   ; en los minutos
	jr $+55		;85b3

; ----------------------------------------------------------------------
; DATOS fases_tiempos: El tiempo de cada fase (32): los minutos en BCD (de 1 a
;   15) o, con el bit 7, los segundos (los BONUS: 20, 25, 30 y 35)
;   0x85b5..0x85d5  (32 bytes)
DATA_fases_tiempos:
	defb 001h,004h,005h,0a0h,006h,007h,007h,0a0h,006h,006h,008h,0a5h,008h,008h,008h,0a5h	; 85b5  ................
	defb 010h,010h,011h,0b0h,012h,013h,015h,0b0h,015h,015h,015h,0b5h,015h,015h,015h,0b5h	; 85c5  ................

; ======================================================================
; CODIGO 0x85d5..0x8616  (65 bytes)
; ======================================================================


puntos_pinta:		; Los puntos (0xE033) en la fila 1 y el record (0xE036) en la fila 1, columna 26
	ld iy,0e033h		;85d5   ; el record...
	ld hl,0183ah		;85d9   ; ...en la fila 1, columna 26
	call cifras_pinta		;85dc   ; pintado
	ld iy,0e036h		;85df   ; los puntos...
	ld hl,0187ah		;85e3   ; ...en la fila 3, columna 26
	call cifras_pinta		;85e6   ; pintados
	ret			;85e9
fase_salida:		; P= con las vidas y PUSH TR1 TO START (0x8616) en el marcador; el efecto 2; espera; las cuentas; y el bucle
	call puntos_pinta		;85ea
	ld de,08616h		;85ed
	ld hl,0191bh		;85f0   ; la fila 8, columna 27
	call texto_vram		;85f3
	ld a,(0e00bh)		;85f6   ; las vidas
	inc hl			;85f9
	call 0004dh		;85fa   ; WRTVRM
	call tiempo_pinta		;85fd
	ld a,002h		;8600   ; la musica 2
	call pide_musica		;8602
	call espera_musica		;8605
	call cuentas_borra		;8608
	xor a			;860b
	ld (0e104h),a		;860c
	inc a			;860f
	ld (0e021h),a		;8610   ; en el boton
	jp fase_bucle		;8613

; ----------------------------------------------------------------------
; DATOS salida_texto: P=, 0xFF, PUSH TR1 TO START, 0xFF
;   0x8616..0x862b  (21 bytes)
DATA_salida_texto:
	defb 020h,00dh,0ffh,020h,025h,023h,018h,010h,024h,022h,001h,010h,024h,01fh,010h,023h	; 8616   .. %#..$"..$..#
	defb 024h,011h,022h,024h,0ffh	; 8626

; ======================================================================
; CODIGO 0x862b..0x864e  (35 bytes)
; ======================================================================


objeto_quieto:		; +0xE del objeto IY a 0
	ld a,000h		;862b
	ld (iy+00eh),a		;862d
	ret			;8630
sprites_borra:		; 0xE100-0xE180 a cero y la tabla de atributos a 0
	ld hl,0e100h		;8631
	ld de,0e101h		;8634
	ld (hl),000h		;8637
	ld bc,00080h		;8639
	ldir		;863c   ; copiados
	ld hl,01b00h		;863e   ; la tabla de atributos...
	ld b,0c8h		;8641   ; ...0xC8 bytes...
	ld a,000h		;8643   ; ...a 0
sprites_borra_byte:
	call 0004dh		;8645   ; WRTVRM
	inc hl			;8648
	djnz sprites_borra_byte		;8649   ; B veces
	jp sprites_vram		;864b

; ----------------------------------------------------------------------
; DATOS fases_colores: El color de cada grupo de cuatro fases
;   0x864e..0x8656  (8 bytes)
DATA_fases_colores:
	defb 080h,0c0h,030h,0e0h,0b0h,020h,0d0h,0a0h	; 864e  ..0.. ..

; ======================================================================
; CODIGO 0x8656..0x8707  (177 bytes)
; ======================================================================


fase_bucle:		; El bucle de la fase: cada cuadro, si no esta mirando (0xE326), todo: el protagonista, los objetos, la cara, la vista, el tiempo...; tocado (0xE183); con STOP (0xE1B5), mirar la fase: la palanca arriba y abajo mueve la vista hasta sus limites (0xE36B, 0xE36C) y al soltarlo vuelve donde estaba
	ld iy,0e100h		;8656   ; el protagonista
	ld a,(iy+000h)		;865a   ; su sitio de antes
	ld (iy+010h),a		;865d
	ld a,(iy+001h)		;8660
	ld (iy+011h),a		;8663
	ld a,(0e326h)		;8666   ; mirando?
	and a			;8669
	jr nz,fase_bucle_mira		;866a
	call prota_mueve_va		;866c
	call caen		;866f
	call rotos		;8672
	call prota_cara		;8675
	call tiempo		;8678
	call tiempo_pinta		;867b
	call objetos		;867e
	call mapa_cosas		;8681
	call colores_gira		;8684
	call record_mira		;8687
	call puntos_pinta		;868a
	ld iy,0e100h		;868d
	call aplastado		;8691   ; algo lo toca?
	and a			;8694
	jr z,fase_bucle_mira		;8695
	ld (0e183h),a		;8697   ; tocado
fase_bucle_mira:
	ld a,(0e326h)		;869a   ; volviendo?
	cp 003h		;869d
	jp z,mirar_vuelve		;869f
	cp 004h		;86a2   ; vuelto?
	jp z,mirar_fin		;86a4
	ld a,(0e1b5h)		;86a7   ; STOP?
	and a			;86aa
	jp z,fase_bucle_fin		;86ab
	call tiempo		;86ae
	call tiempo_pinta		;86b1
	call mirar_empieza		;86b4
	ld a,0ffh		;86b7   ; mirando
	ld (0e330h),a		;86b9
	ld a,(0e308h)		;86bc   ; la vista, guardada
	ld (0e327h),a		;86bf
	ld ix,0e100h		;86c2   ; los colores de los 8 sprites, guardados...
	ld de,00010h		;86c6
	ld hl,0e328h		;86c9
	ld b,008h		;86cc
mirar_colores:
	ld a,(ix+003h)		;86ce   ; ...y a 0
	ld (ix+003h),000h		;86d1
	ld (hl),a			;86d5
	add ix,de		;86d6
	inc hl			;86d8
	djnz mirar_colores		;86d9   ; B veces
	ld a,(0e100h)		;86db   ; su altura, guardada
	ld (0e366h),a		;86de   ; en la altura
	ld a,000h		;86e1
	ld (0e367h),a		;86e3
	call sprites_vram		;86e6
mirar_espera:
	ld ix,0e600h		;86e9   ; algun objeto en marcha?
	ld b,014h		;86ed
	ld de,00008h		;86ef
mirar_espera_uno:
	ld a,(ix+006h)		;86f2
	and a			;86f5
	jr nz,mirar_espera_mueve		;86f6
	add ix,de		;86f8
	djnz mirar_espera_uno		;86fa   ; B veces
	jp mirar		;86fc   ; nada se mueve: a mirar
mirar_espera_mueve:
	call rotos		;86ff   ; los que se rompen
	call caen		;8702   ; los que caen
	jr mirar_espera		;8705   ; otra vez

; ----------------------------------------------------------------------
; DATOS mirar_flechas: Siete sprites (6 bytes: Y, X, dibujo, color, alto y
;   color de vuelta) del marco que se ve al mirar
;   0x8707..0x8731  (42 bytes)
DATA_mirar_flechas:
	defb 010h,010h,090h,00fh,000h,00fh,010h,010h,094h,008h,000h,008h,000h,000h,060h,002h	; 8707  ..............`.
	defb 000h,002h,000h,000h,074h,00bh,000h,00bh,000h,010h,064h,002h,000h,002h,010h,000h	; 8717  ....t.....d.....
	defb 06ch,002h,000h,002h,010h,010h,070h,002h,000h,002h	; 8727  l.....p...

; ======================================================================
; CODIGO 0x8731..0x8a87  (854 bytes)
; ======================================================================


marco_sube:		; El marco 16 puntos arriba...
	ld hl,0fff0h		;8731   ; -16
	jr marco_mueve		;8734
marco_baja:		; ...o abajo
	ld hl,00010h		;8736   ; +16
marco_mueve:
	ld ix,0e331h		;8739   ; los 7 sprites del marco
	ld (0e35ch),hl		;873d   ; lo que se mueve
	ld b,007h		;8740   ; siete
	ld de,00006h		;8742   ; de 6 en 6 bytes
marco_uno:
	push bc			;8745   ; guardados
	push de			;8746
	ld l,(ix+000h)		;8747   ; la Y, en 16 bits
	ld h,(ix+004h)		;874a
	ld de,(0e35ch)		;874d   ; + lo que se mueve
	add hl,de			;8751
	ld (ix+000h),l		;8752   ; guardada
	ld (ix+004h),h		;8755
	ld a,h			;8758   ; por encima o por debajo de 256?
	and a			;8759
	jr nz,marco_fuera		;875a   ; fuera
	ld a,l			;875c   ; la Y...
	cp 008h		;875d   ; ...antes de 8?
	jr c,marco_fuera		;875f   ; fuera
	cp 0b8h		;8761   ; desde 0xB8?
	jr nc,marco_fuera		;8763   ; fuera
	ld a,(ix+005h)		;8765   ; dentro: su color
	ld (ix+003h),a		;8768   ; se ve
	jr marco_sigue		;876b
marco_fuera:
	ld (ix+003h),000h		;876d   ; fuera: transparente
marco_sigue:
	pop de			;8771   ; recuperados
	pop bc			;8772
	add ix,de		;8773   ; el siguiente
	djnz marco_uno		;8775   ; B veces
	ret			;8777
mirar:		; Mirar: los limites de la fase (0x40D6), el marco alrededor del protagonista (0x8707), y mientras STOP siga, la palanca arriba (1) sube la vista y abajo (5) la baja
	call fase_tiempo		;8778   ; los limites
	ld a,(0e100h)		;877b   ; la Y del protagonista...
	cp 020h		;877e
	jr nc,mirar_y		;8780
	ld a,020h		;8782
mirar_y:
	sub 010h		;8784
	ld (0e35fh),a		;8786
	ld a,(0e101h)		;8789   ; ...y su X
	cp 020h		;878c
	jr nc,mirar_x		;878e
	ld a,020h		;8790
mirar_x:
	cp 098h		;8792
	jr c,mirar_x2		;8794
	ld a,090h		;8796
mirar_x2:
	sub 010h		;8798
	ld (0e35eh),a		;879a
	ld hl,08707h		;879d   ; el marco
	ld de,0e331h		;87a0
	ld bc,0002ah		;87a3
	ldir		;87a6   ; copiados
	ld ix,0e331h		;87a8   ; a su sitio
	ld de,00006h		;87ac
	ld b,007h		;87af
mirar_marco:
	ld a,(0e35fh)		;87b1
	add a,(ix+000h)		;87b4
	ld (ix+000h),a		;87b7
	ld a,(0e35eh)		;87ba
	add a,(ix+001h)		;87bd
	ld (ix+001h),a		;87c0
	add ix,de		;87c3
	djnz mirar_marco		;87c5   ; B veces
	call sprites_vram_marco		;87c7
	ld a,0ffh		;87ca
	ld (0e35bh),a		;87cc   ; en el marco
mirar_bucle:
	ld a,003h		;87cf   ; el efecto 3
	call pide_efecto_bc		;87d1
	call sprites_vram_marco		;87d4
	call mirar_empieza		;87d7
	ld a,(0e180h)		;87da   ; la palanca
	cp 001h		;87dd
	jr z,mirar_arriba		;87df
	cp 005h		;87e1
	jr z,mirar_abajo		;87e3
	jr mirar_sigue		;87e5
mirar_arriba:
	ld a,(0e36bh)		;87e7   ; el limite de arriba
	ld b,a			;87ea
	ld a,(0e308h)		;87eb   ; la vista
	cp b			;87ee
	jr c,mirar_sigue		;87ef
	call vista_baja5		;87f1   ; la vista sube
	jr mirar_sigue		;87f4
mirar_abajo:
	ld a,(0e36ch)		;87f6   ; el de abajo
	ld b,a			;87f9
	ld a,(0e308h)		;87fa   ; la vista
	cp b			;87fd
	jr nc,mirar_sigue		;87fe
	cp 016h		;8800
	jr nc,mirar_sigue		;8802
	call vista_sube5		;8804   ; la vista baja
mirar_sigue:
	ld a,(0e1b3h)		;8807   ; F1?
	and a			;880a
	jr nz,mirar_acaba		;880b
	ld a,(0e1b5h)		;880d   ; STOP?
	and a			;8810
	jr z,mirar_bucle		;8811
mirar_acaba:
	ld a,(0e326h)		;8813   ; mirando
	cp 001h		;8816
	jr nz,mirar_bucle		;8818
	ld a,003h		;881a   ; a volver
	ld (0e326h),a		;881c   ; en mirando
	jp fase_bucle_fin		;881f
mirar_empieza:		; Sin STOP, 0xE326 = 1
	ld a,(0e1b5h)		;8822   ; STOP
	and a			;8825
	ret nz			;8826
	ld a,001h		;8827
	ld (0e326h),a		;8829   ; en mirando
	ret			;882c
mirar_vuelve:		; La vista vuelve a donde estaba (0xE327), el marco se cierra y los colores de los sprites vuelven
	ld a,(0e35bh)		;882d   ; el marco
	push af			;8830
	ld a,0ffh		;8831
	ld (0e35bh),a		;8833   ; en el marco
mirar_vuelve_paso:
	ld a,(0e308h)		;8836   ; la vista
	ld b,a			;8839
	ld a,(0e327h)		;883a
	cp b			;883d
	jr z,mirar_cierra		;883e
	jr nc,mirar_vuelve_baja		;8840
	jr mirar_vuelve_sube		;8842
mirar_vuelve_baja:
	call vista_sube5		;8844
	jr mirar_vuelve_paso		;8847
mirar_vuelve_sube:
	call vista_baja5		;8849
	jr mirar_vuelve_paso		;884c
mirar_cierra:
	pop af			;884e
	ld (0e35bh),a		;884f   ; en el marco
	ld ix,0e33dh		;8852
	ld a,(0e35fh)		;8856
	ld (ix+000h),a		;8859
	ld (ix+006h),a		;885c
	ld a,(0e35eh)		;885f
	ld (ix+001h),a		;8862
	ld (ix+007h),a		;8865
	ld (ix+002h),074h		;8868
	ld (ix+003h),00bh		;886c
	ld (ix+008h),068h		;8870
	ld (ix+009h),002h		;8874
	call sprites_vram_marco		;8878
	xor a			;887b
	ld (0e014h),a		;887c   ; en la cuenta de cuadros
mirar_cierra_espera:
	ld a,(0e014h)		;887f   ; la cuenta de cuadros
	cp 008h		;8882
	jr c,mirar_cierra_espera		;8884
	ld ix,0e331h		;8886
	ld (ix+004h),000h		;888a
mirar_cierra_paso:
	ld a,(0e014h)		;888e   ; la cuenta de cuadros
	cp 003h		;8891
	jr c,mirar_cierra_paso		;8893
	xor a			;8895
	ld (0e014h),a		;8896   ; en la cuenta de cuadros
	call sprites_vram_marco		;8899
	ld (ix+002h),0d4h		;889c
	ld (ix+008h),0d8h		;88a0
	ld a,(ix+004h)		;88a4
	inc (ix+004h)		;88a7
	ld a,(ix+001h)		;88aa
	add a,004h		;88ad
	ld (ix+001h),a		;88af
	ld (ix+007h),a		;88b2
	ld b,a			;88b5
	ld a,(0e35eh)		;88b6
	add a,020h		;88b9
	cp b			;88bb
	jr c,mirar_cierra_fin		;88bc
	jr mirar_cierra_paso		;88be
mirar_cierra_fin:
	ld a,(0e014h)		;88c0   ; la cuenta de cuadros
	cp 020h		;88c3
	jr c,mirar_cierra_fin		;88c5
	ld hl,0e331h		;88c7
	ld b,030h		;88ca
mirar_cierra_borra:
	ld (hl),000h		;88cc
	inc hl			;88ce
	djnz mirar_cierra_borra		;88cf   ; B veces
	call sprites_vram_marco		;88d1
	xor a			;88d4
	ld (0e330h),a		;88d5
	ld ix,0e100h		;88d8
	ld hl,0e328h		;88dc
	ld de,00010h		;88df
	ld b,008h		;88e2
mirar_colores_vuelven:
	ld a,(hl)			;88e4
	ld (ix+003h),a		;88e5
	add ix,de		;88e8
	inc hl			;88ea
	djnz mirar_colores_vuelven		;88eb   ; B veces
	ld a,004h		;88ed
	ld (0e326h),a		;88ef   ; en mirando
mirar_fin:		; Al soltar STOP, otra vez el bucle
	ld a,(0e1b5h)		;88f2   ; STOP
	and a			;88f5
	jr nz,fase_bucle_fin		;88f6
	xor a			;88f8
	ld (0e326h),a		;88f9   ; en mirando
	jp fase_bucle		;88fc
fase_bucle_fin:		; El sonido de fondo (el 2 en el BONUS, el 3 si no); tocado, F1, la fase acabada (0xE03A); sin partida, con el boton, el titulo
	xor a			;88ff
	ld (0e35bh),a		;8900   ; en el marco
	call sprites_vram		;8903
	ld a,(0e00ah)		;8906   ; el BONUS?
	and 003h		;8909
	cp 003h		;890b
	jr nz,fase_bucle_normal		;890d
	ld a,002h		;890f   ; el efecto 2
	call pide_efecto_bc		;8911
	ld a,(0e183h)		;8914   ; tocado?
	and a			;8917
	jp nz,fase_acabada		;8918
	ld a,(0e1b3h)		;891b   ; F1?
	and a			;891e
	jp nz,fase_acabada		;891f
	jr fase_bucle_otro		;8922
fase_bucle_normal:
	ld a,003h		;8924   ; el efecto 3
	call pide_efecto_bc		;8926
	ld a,(0e1b3h)		;8929   ; F1?
	and a			;892c
	jp nz,muere		;892d
	ld a,(0e183h)		;8930   ; tocado?
	and a			;8933
	jp nz,tocado		;8934
	ld a,(0e03ah)		;8937   ; la fase acabada?
	and a			;893a
	jp nz,fase_siguiente		;893b
fase_bucle_otro:
	ld a,(0e000h)		;893e   ; jugando?
	and a			;8941
	jp nz,fase_bucle		;8942
	ld a,(0e325h)		;8945   ; 0xE325?
	and a			;8948
	jp nz,titulo		;8949
	ld a,(0e026h)		;894c   ; el boton?
	and a			;894f
	jp nz,titulo		;8950
	jp fase_bucle		;8953
vista_sube:		; La vista 16 puntos arriba (el protagonista con ella; fuera de la pantalla, sin color)
	ld a,(0e35bh)		;8956   ; con el marco?
	and a			;8959
	call nz,marco_sube		;895a
	ld de,0fff0h		;895d   ; -16
	jr vista_mueve		;8960
vista_baja:		; La vista 16 puntos abajo
	ld a,(0e35bh)		;8962   ; con el marco?
	and a			;8965
	call nz,marco_baja		;8966
	ld de,00010h		;8969   ; +16
vista_mueve:
	push ix		;896c
	ld ix,0e100h		;896e
	ld hl,(0e366h)		;8972   ; la altura guardada...
	add hl,de			;8975   ; ...+ el paso
	ld (0e366h),hl		;8976
	ld a,l			;8979
	ld (ix+000h),l		;897a   ; la Y del protagonista
	ld (ix+010h),l		;897d
	cp 0b8h		;8980   ; fuera de la pantalla?
	jr nc,vista_fuera		;8982
	ld a,h			;8984
	and a			;8985
	jr nz,vista_fuera		;8986
	ld (ix+003h),00bh		;8988   ; colores 11 y 8
	ld (ix+013h),008h		;898c
	pop ix		;8990
	ret			;8992
vista_fuera:
	ld (ix+003h),000h		;8993   ; sin color
	ld (ix+013h),000h		;8997
	pop ix		;899b
	ret			;899d
tocado:		; Tocado (0xE183): con SELECT en el titulo, nada, salvo el 0x80, que nadie escribe (solo 0xFF, 1 y 0); si no, el efecto 1, el record, y la caida: los dibujos de la tabla de 0x8A91 cada 8 cuadros; una vida menos y la fase otra vez; sin vidas, GAME OVER
	ld a,(0e023h)		;899e   ; SELECT en el titulo?
	and a			;89a1
	jr z,muere		;89a2
	ld a,(0e183h)		;89a4   ; 0x80: aunque haya SELECT (nadie lo escribe)
	cp 080h		;89a7
	jr z,muere		;89a9
	xor a			;89ab   ; nada
	ld (0e183h),a		;89ac   ; en tocado
	jp fase_bucle		;89af   ; al bucle
muere:
	ld a,(0e326h)		;89b2   ; mirando: nada
	and a			;89b5
	jp nz,fase_bucle		;89b6
	call sprites_vram		;89b9
	ld a,001h		;89bc   ; el efecto 1
	call pide_efecto_bc		;89be
	xor a			;89c1   ; 0
	ld (0e183h),a		;89c2   ; en tocado
	call record_mira		;89c5   ; el record
	ld ix,0e100h		;89c8   ; el protagonista
	xor a			;89cc
	ld (ix+005h),a		;89cd   ; los pasos a 0
	ld (ix+006h),a		;89d0
	ld (0e013h),a		;89d3   ; en la cuenta de cuadros
	ld (0e183h),a		;89d6   ; en tocado
	ld (0e1b3h),a		;89d9   ; en F1
muere_paso:
	call sprites_vram		;89dc
	ld a,(0e013h)		;89df   ; 8 cuadros
	cp 008h		;89e2
	jr c,muere_paso		;89e4
	xor a			;89e6   ; la cuenta a 0
	ld (0e013h),a		;89e7   ; en la cuenta de cuadros
	ld a,(ix+006h)		;89ea   ; el paso
	inc (ix+006h)		;89ed
	ld e,a			;89f0
	ld d,000h		;89f1
	ld hl,08a91h		;89f3   ; su dibujo (0x8A91)
	add hl,de			;89f6
	ld a,(hl)			;89f7
	cp 0ffh		;89f8   ; 0xFF: acabado
	jr z,muere_vida		;89fa
	ld (ix+002h),a		;89fc   ; el dibujo
	add a,004h		;89ff   ; el segundo sprite, 4 mas
	ld (ix+012h),a		;8a01
	jr muere_paso		;8a04
muere_vida:
	ld a,(0e00bh)		;8a06   ; una vida menos
	dec a			;8a09
	ld (0e00bh),a		;8a0a   ; en las vidas
	cp 0ffh		;8a0d   ; ninguna?
	jr z,game_over		;8a0f
	jp fase_empieza		;8a11   ; la fase otra vez
record_mira:		; Si los puntos (0xE034-0xE036) pasan del record (0xE031-0xE033), el record nuevo
	ld a,(0e034h)		;8a14   ; el byte alto...
	ld b,a			;8a17
	ld a,(0e031h)		;8a18   ; ...contra el del record
	cp b			;8a1b
	jr z,record_mira2		;8a1c
	ret nc			;8a1e
	jr record_nuevo		;8a1f
record_mira2:
	ld a,(0e035h)		;8a21   ; el de en medio
	ld b,a			;8a24
	ld a,(0e032h)		;8a25
	cp b			;8a28
	jr z,record_mira3		;8a29
	ret nc			;8a2b
	jr record_nuevo		;8a2c
record_mira3:
	ld a,(0e036h)		;8a2e   ; el bajo
	ld b,a			;8a31
	ld a,(0e033h)		;8a32
	cp b			;8a35
	jr z,record_nuevo		;8a36
	ret nc			;8a38
record_nuevo:
	ld a,(0e036h)		;8a39   ; los tres bytes al record
	ld (0e033h),a		;8a3c
	ld a,(0e035h)		;8a3f
	ld (0e032h),a		;8a42
	ld a,(0e034h)		;8a45
	ld (0e031h),a		;8a48
	ret			;8a4b
game_over:		; GAME OVER (0x8A87) en la fila 8, 16 x 16 cuadros de espera, sin partida, la musica 1 y el titulo
	xor a			;8a4c
	ld hl,0e100h		;8a4d   ; el protagonista a cero
	ld (hl),a			;8a50
	inc hl			;8a51
	ld (hl),a			;8a52
	inc hl			;8a53
	ld (hl),a			;8a54
	inc hl			;8a55
	ld (hl),a			;8a56
	ld hl,01907h		;8a57   ; la fila 8, columna 7
	ld de,08a87h		;8a5a
	call texto_vram		;8a5d   ; escrito
game_over_espera:
	ld a,(0e013h)		;8a60   ; 16 cuadros
	cp 010h		;8a63
	jr c,game_over_espera		;8a65
	xor a			;8a67   ; la fase 0
	ld (0e00ah),a		;8a68   ; en la fase
	ld (0e013h),a		;8a6b   ; en la cuenta de cuadros
	ld a,(ix+006h)		;8a6e   ; 16 veces
	inc (ix+006h)		;8a71
	cp 010h		;8a74
	jr c,game_over_espera		;8a76
	xor a			;8a78   ; sin partida
	ld (0e000h),a		;8a79   ; en jugando
	ld a,001h		;8a7c   ; la musica 1
	call pide_musica		;8a7e
	call espera_musica		;8a81   ; entera
	jp titulo		;8a84   ; el titulo

; ----------------------------------------------------------------------
; DATOS game_over_datos: GAME OVER y 0xFF (0x8A87); los dibujos del
;   protagonista al morir (0x8A91, hasta 0xFF)
;   0x8a87..0x8a9b  (20 bytes)
DATA_game_over_datos:
	defb 017h,011h,01dh,015h,010h,01fh,026h,015h,022h,0ffh,000h,040h,040h,040h,048h,048h	; 8a87  ......&."..@@@HH
	defb 048h,048h,048h,0ffh	; 8a97

; ======================================================================
; CODIGO 0x8a9b..0x8b21  (134 bytes)
; ======================================================================


colores_gira:		; Cada vez, el color + 0x10 (0xE360) en las casillas 0x8C-0x8D y 0x90-0x91 de los tres tercios
	ld a,(0e360h)		;8a9b   ; el color siguiente
	add a,010h		;8a9e
	and 0f0h		;8aa0
	ld (0e360h),a		;8aa2
	ld hl,02460h		;8aa5   ; en el primer tercio
	call colores_dos		;8aa8
	ld hl,02c60h		;8aab   ; el segundo
	call colores_dos		;8aae
	ld hl,03460h		;8ab1   ; el tercero
	call colores_dos		;8ab4
	ret			;8ab7
colores_gira2:		; Lo mismo en las casillas 0xF0-0xF1 y 0xF4-0xF5
	ld a,(0e360h)		;8ab8   ; el color...
	add a,010h		;8abb   ; ...el siguiente (de 16 en 16)
	and 0f0h		;8abd
	ld (0e360h),a		;8abf   ; guardado
	ld hl,02780h		;8ac2   ; en el primer tercio
	call colores_dos		;8ac5
	ld hl,02f80h		;8ac8   ; en el segundo
	call colores_dos		;8acb
	ld hl,03780h		;8ace   ; en el tercero
	call colores_dos		;8ad1
	ret			;8ad4
colores_dos:		; 6 + 6 bytes de color A desde HL, saltando 2
	ld b,006h		;8ad5   ; 6 bytes
colores_dos_1:
	call 0004dh		;8ad7   ; WRTVRM
	inc hl			;8ada
	djnz colores_dos_1		;8adb   ; B veces
	ld de,00002h		;8add
	add hl,de			;8ae0
	ld b,006h		;8ae1
colores_dos_2:
	call 0004dh		;8ae3   ; WRTVRM
	inc hl			;8ae6
	djnz colores_dos_2		;8ae7   ; B veces
	ret			;8ae9
aplastado:		; ¿Hay una roca (las casillas 0x30-0x37, leidas de la VRAM con RDVRM) en la fila de arriba del sprite IY, la de su cabeza? A = 0xFF si; 0 si no: una roca que cae encima aplasta
	call sitio_vram		;8aea   ; su sitio en la tabla de nombres
	ld de,00020h		;8aed   ; la fila de abajo
	add hl,de			;8af0
	ld a,(iy+001h)		;8af1   ; en una columna exacta?
	and 007h		;8af4
	and a			;8af6
	jr nz,aplastado_2		;8af7
	call 0004ah		;8af9   ; RDVRM
	cp 030h		;8afc   ; 0x30-0x37?
	jr c,aplastado_2		;8afe
	cp 038h		;8b00
	jr c,aplastado_si		;8b02
aplastado_2:
	inc hl			;8b04   ; la de al lado
	call 0004ah		;8b05   ; RDVRM
	cp 030h		;8b08
	jr c,aplastado_no		;8b0a
	cp 038h		;8b0c
	jr nc,aplastado_no		;8b0e
aplastado_si:
	ld a,0ffh		;8b10
	ret			;8b12
aplastado_no:
	xor a			;8b13
	ret			;8b14
espera_20:		; Espera 0x20 cuadros
	xor a			;8b15
	ld (0e014h),a		;8b16   ; en la cuenta de cuadros
espera_20_bucle:
	ld a,(0e014h)		;8b19   ; la cuenta de cuadros
	cp 020h		;8b1c
	jr c,espera_20_bucle		;8b1e
	ret			;8b20

; ----------------------------------------------------------------------
; DATOS bonus_cuenta_texto: Lo que se escribe en el BONUS: el dibujo y "=" con
;   lo cogido
;   0x8b21..0x8b2c  (11 bytes)
DATA_bonus_cuenta_texto:
	defb 00ch,010h,010h,010h,010h,00dh,010h,010h,010h,000h,000h	; 8b21  ...........

; ======================================================================
; CODIGO 0x8b2c..0x8d3c  (528 bytes)
; ======================================================================


fase_acabada:		; Una fase acabada: en el BONUS, lo cogido (0xE30D) y sus puntos; si no, la fase siguiente, su premio en 0xE034 (la tabla de 0x40B5) y YOU GET BONUS ... PTS; la musica 3 y el protagonista cruza la pantalla de izquierda a derecha; despues de la 31, el final
	ld a,(0e00ah)		;8b2c   ; la fase
	cp 01fh		;8b2f   ; la 31: el final
	jp nc,final		;8b31
	call espera_20		;8b34   ; 0x20 cuadros
	ld a,(0e30dh)		;8b37   ; lo cogido en el BONUS
	ld (0e322h),a		;8b3a   ; en los puntos que se suman
	call puntos_suma		;8b3d
	call pantalla_prepara		;8b40
	call sprites_borra		;8b43   ; los sprites fuera
	ld de,08d44h		;8b46   ; YOU GET BONUS en la fila 5
	ld hl,018aah		;8b49
	call texto_vram		;8b4c
	ld hl,08b21h		;8b4f   ; el dibujo y "=" en la fila 8
	ld de,0190ch		;8b52
	ld bc,0000bh		;8b55
	call 0005ch		;8b58   ; LDIRVM
	ld a,01ch		;8b5b   ; la casilla 0x1C
	ld hl,018e9h		;8b5d
	call bloque_pinta		;8b60
	ld a,(0e30dh)		;8b63   ; cuantos: la cifra alta...
	ld b,a			;8b66
	and 0f0h		;8b67
	rrca			;8b69
	rrca			;8b6a
	rrca			;8b6b
	rrca			;8b6c
	cp 000h		;8b6d   ; 0: sin ella
	jr z,premio_cifra_baja		;8b6f
	ld hl,0190eh		;8b71
	call 0004dh		;8b74   ; WRTVRM
	ld hl,01913h		;8b77
	call 0004dh		;8b7a   ; WRTVRM
premio_cifra_baja:
	ld a,b			;8b7d   ; la baja
	and 00fh		;8b7e
	ld hl,0190fh		;8b80
	call 0004dh		;8b83   ; WRTVRM
	ld hl,01914h		;8b86
	call 0004dh		;8b89   ; WRTVRM
	ld a,(0e00ah)		;8b8c   ; la fase siguiente
	inc a			;8b8f
	ld (0e00ah),a		;8b90   ; en la fase
	call record_mira		;8b93   ; el record
	call 00044h		;8b96   ; ENASCR
	ld a,001h		;8b99   ; con los colores girando
	jp fase_cruza		;8b9b
fase_siguiente:
	call espera_20		;8b9e   ; 0x20 cuadros
	ld a,(0e00ah)		;8ba1   ; la fase siguiente
	inc a			;8ba4
	ld (0e00ah),a		;8ba5   ; en la fase
	call fase_dato		;8ba8   ; su dato
	and 00fh		;8bab   ; la cifra baja...
	rlca			;8bad   ; ...x 16...
	rlca			;8bae
	rlca			;8baf
	rlca			;8bb0
	ld (0e322h),a		;8bb1   ; ...millares del premio
	call puntos_suma		;8bb4   ; la pantalla
	call fase_dato		;8bb7   ; el premio (la mitad alta)...
	and 0f0h		;8bba
	rrca			;8bbc
	rrca			;8bbd
	rrca			;8bbe
	rrca			;8bbf
	ld b,a			;8bc0   ; en B
	ld a,(0e034h)		;8bc1   ; ...a 0xE034
	add a,b			;8bc4
	daa			;8bc5   ; en BCD
	ld (0e034h),a		;8bc6
	call record_mira		;8bc9   ; el record
	call sprites_borra		;8bcc
	xor a			;8bcf   ; 0xE03A...
	ld (0e03ah),a		;8bd0   ; 0xE03A a 0
	call sprites_borra		;8bd3   ; los sprites fuera
	ld a,(0e00ah)		;8bd6   ; la 32?
	cp 020h		;8bd9
	jr nc,final		;8bdb   ; la 32: el final
	call premio_pantalla		;8bdd   ; la pantalla
	call 00044h		;8be0   ; ENASCR
	ld de,08d44h		;8be3   ; YOU GET BONUS en la fila 1
	ld hl,0182dh		;8be6
	call texto_vram		;8be9
	ld de,08d52h		;8bec   ; 1000... PTS en la fila 4
	ld hl,0188ch		;8bef
	call texto_vram		;8bf2
	call fase_dato		;8bf5   ; las cifras del premio
	and 00fh		;8bf8   ; la cifra baja
	ld hl,01892h		;8bfa   ; en la fila 4, columna 18
	call 0004dh		;8bfd   ; WRTVRM
	ld hl,01895h		;8c00   ; y en la columna 21
	call 0004dh		;8c03   ; WRTVRM
	call fase_dato		;8c06
	and 0f0h		;8c09   ; la cifra alta
	rrca			;8c0b
	rrca			;8c0c
	rrca			;8c0d
	rrca			;8c0e
	jr nz,fase_siguiente_decena		;8c0f   ; sin decenas: espacio
	ld a,010h		;8c11
fase_siguiente_decena:
	ld hl,01891h		;8c13
	call 0004dh		;8c16   ; WRTVRM
	ld hl,01894h		;8c19
	call 0004dh		;8c1c   ; WRTVRM
	xor a			;8c1f   ; sin colores girando
fase_cruza:		; El protagonista cruza la pantalla (0x8CF3, 0x8D18) con la musica 3; despues, la fase
	ld (0e10ch),a		;8c20   ; los colores girando?
	ld a,003h		;8c23   ; la musica 3
	call pide_musica		;8c25
	call cruza_empieza		;8c28   ; el protagonista a la izquierda
fase_cruza_cuadro:
	ld a,(0e10ch)		;8c2b   ; girando?
	and a			;8c2e
	jr z,fase_cruza_espera		;8c2f
	call colores_gira		;8c31
fase_cruza_espera:
	ld a,(0e014h)		;8c34   ; un cuadro
	cp 001h		;8c37
	jr c,fase_cruza_cuadro		;8c39
	xor a			;8c3b
	ld (0e014h),a		;8c3c   ; en la cuenta de cuadros
	call cruza_paso		;8c3f   ; un paso
	ld a,(iy+001h)		;8c42   ; al otro lado?
	cp 0f0h		;8c45
	jr c,fase_cruza_cuadro		;8c47
	push iy		;8c49   ; los 0x40 bytes del protagonista a cero
	pop hl			;8c4b
	ld b,040h		;8c4c
	xor a			;8c4e
fase_cruza_borra:
	ld (hl),a			;8c4f
	inc hl			;8c50
	djnz fase_cruza_borra		;8c51   ; B veces
	call espera_musica		;8c53   ; la musica entera
	jp fase_empieza		;8c56   ; la fase siguiente
final:		; El final: la musica 5; el protagonista cruza la pantalla y, en las X 0x30, 0x85 y 0xCC, el moai que hay en ese sitio se cambia por un monton de joyas (0x412B, 8 x 14 casillas); PJM1622 (0x8D3C) en la fila 1; los colores giran con la musica 5 una y otra vez hasta el boton; y el titulo
	call premio_pantalla		;8c59   ; la pantalla
	call 00044h		;8c5c   ; ENASCR
	ld a,005h		;8c5f   ; la musica 5
	call pide_musica		;8c61
	call cruza_empieza		;8c64   ; el protagonista a la izquierda
final_cuadro:
	ld a,(0e014h)		;8c67   ; un cuadro
	cp 001h		;8c6a
	jr c,final_cuadro		;8c6c
	xor a			;8c6e
	ld (0e014h),a		;8c6f   ; en la cuenta de cuadros
	call cruza_paso		;8c72   ; un paso
	ld a,(iy+001h)		;8c75
	push af			;8c78
	cp 030h		;8c79   ; la X 0x30: el primer monton
	call z,joyas1		;8c7b
	pop af			;8c7e
	push af			;8c7f
	cp 085h		;8c80   ; 0x85: el segundo
	call z,joyas2		;8c82
	pop af			;8c85
	cp 0cch		;8c86   ; 0xCC: el tercero
	call z,joyas3		;8c88
	cp 0f0h		;8c8b   ; al otro lado?
	jr c,final_cuadro		;8c8d
	ld hl,01822h		;8c8f   ; PJM1622 en la fila 1, columna 2
	ld de,08d3ch		;8c92
	call texto_vram		;8c95
	call cuentas_borra		;8c98   ; las cuentas
	call sprites_borra		;8c9b   ; los sprites
final_espera:
	ld a,(0e014h)		;8c9e   ; 4 cuadros
	cp 004h		;8ca1
	jr c,final_espera		;8ca3
	xor a			;8ca5
	ld (0e014h),a		;8ca6   ; en la cuenta de cuadros
	ld a,005h		;8ca9   ; la musica 5 otra vez
	call pide_musica		;8cab
	call colores_gira2		;8cae   ; los colores giran
	ld a,(0e021h)		;8cb1   ; el boton?
	ld b,a			;8cb4
	ld a,(0e19dh)		;8cb5
	or b			;8cb8
	and a			;8cb9
	jr z,final_espera		;8cba
	xor a			;8cbc   ; la fase 0...
	ld (0e00ah),a		;8cbd   ; en la fase
	ld (0e000h),a		;8cc0   ; ...sin partida
	call cuentas_borra		;8cc3
	jp titulo		;8cc6   ; el titulo
joyas1:		; Un monton de joyas (0x412B, 14 filas de 8) en la fila 2, columna 3...
	ld hl,01843h		;8cc9
	jr joyas_pinta		;8ccc
joyas2:		; ...en la fila 4, columna 13...
	ld hl,0188dh		;8cce
	jr joyas_pinta		;8cd1
joyas3:		; ...o en la fila 3, columna 22
	ld hl,01876h		;8cd3
joyas_pinta:
	ld de,0412bh		;8cd6
	ld b,00eh		;8cd9
	push hl			;8cdb
joyas_fila:
	ld c,008h		;8cdc
joyas_casilla:
	ld a,(de)			;8cde
	call 0004dh		;8cdf   ; WRTVRM
	inc hl			;8ce2
	inc de			;8ce3
	dec c			;8ce4
	jr nz,joyas_casilla		;8ce5
	pop hl			;8ce7
	push de			;8ce8
	ld de,00020h		;8ce9
	add hl,de			;8cec
	pop de			;8ced
	push hl			;8cee
	djnz joyas_fila		;8cef   ; B veces
	pop hl			;8cf1
	ret			;8cf2
cruza_empieza:		; El protagonista en la X 8, la Y 0x98 (colores 15 y 9) y su sombra (0xE120, dibujo 0x78)
	ld iy,0e100h		;8cf3   ; el protagonista
	ld (iy+001h),008h		;8cf7   ; la X 8
	ld (iy+000h),098h		;8cfb   ; la Y 0x98
	ld (iy+003h),00fh		;8cff   ; el color 15
	ld (iy+011h),008h		;8d03   ; su segundo sprite
	ld (iy+010h),098h		;8d07
	ld (iy+013h),009h		;8d0b   ; el color 9
	ld ix,0e120h		;8d0f   ; los objetos
	ld (ix+002h),078h		;8d13
	ret			;8d17
cruza_paso:		; Un punto a la derecha, con la sombra 10 por encima, cambiando de color
	inc (iy+001h)		;8d18   ; un punto
	inc (iy+011h)		;8d1b
	ld a,(iy+001h)		;8d1e
	ld (ix+001h),a		;8d21
	ld a,(iy+000h)		;8d24   ; la sombra, 10 por encima
	sub 00ah		;8d27
	ld (ix+000h),a		;8d29
	ld a,(ix+003h)		;8d2c   ; su color, el siguiente
	inc a			;8d2f
	and 00fh		;8d30
	ld (ix+003h),a		;8d32
	call sprites_vram		;8d35   ; los sprites
	call prota_paso		;8d38
	ret			;8d3b

