mapa_pinta:		; La pantalla de la fase desde su mapa (0xE319, en 0xE704 y 0xE369): 11 filas de 16 bloques de 2 x 2 casillas, desde la fila 1, columna 1; los bloques 0 se saltan
	ld hl,01821h		;8d7b   ; la fila 1, columna 1
	ld de,(0e319h)		;8d7e   ; el mapa
	ld (0e704h),de		;8d82
	ld (0e369h),de		;8d86
	ld b,00bh		;8d8a   ; 11 filas
	ld c,010h		;8d8c   ; de 16
mapa_pinta_bloque:
	ld a,(de)			;8d8e   ; un bloque
	cp 000h		;8d8f   ; vacio?
	call nz,bloque_pinta		;8d91
	inc hl			;8d94   ; dos columnas mas
	inc hl			;8d95
	inc de			;8d96
	dec c			;8d97   ; uno menos
	jr nz,mapa_pinta_bloque		;8d98
	ld c,010h		;8d9a
	push de			;8d9c
	ld de,00020h		;8d9d   ; dos filas mas (con las dos de antes)
	add hl,de			;8da0
	pop de			;8da1
	djnz mapa_pinta_bloque		;8da2   ; 11 filas
	ret			;8da4
mapa_objetos:		; Los objetos del mapa (+0xC, cada 16 bytes, 12): su sprite (0xE120 + el numero x 16) con su dibujo (+0xD) y su X (+0xE), a la altura de su fila (8, 0x18...)
	ld iy,(0e704h)		;8da5   ; el mapa
	ld b,00ch		;8da9   ; 12 filas
	ld c,008h		;8dab   ; la primera, Y 8
mapa_objetos_fila:
	ld a,(iy+00ch)		;8dad   ; hay objeto?
	and a			;8db0
	jr z,mapa_objetos_sigue		;8db1
	bit 7,(iy+00dh)		;8db3   ; el bit 7: ya no
	jr nz,mapa_objetos_sigue		;8db7
	ld ix,0e120h		;8db9   ; su sprite...
	rlc a		;8dbd
	rlc a		;8dbf
	rlc a		;8dc1
	rlc a		;8dc3
	ld e,a			;8dc5
	ld d,000h		;8dc6
	add ix,de		;8dc8
	ld a,(iy+00dh)		;8dca   ; ...su dibujo
	ld (ix+004h),a		;8dcd
	ld a,(iy+00eh)		;8dd0   ; ...su X
	ld (ix+001h),a		;8dd3
	ld (ix+000h),c		;8dd6   ; ...su Y
mapa_objetos_sigue:
	ld a,010h		;8dd9   ; 16 mas abajo
	add a,c			;8ddb
	ld c,a			;8ddc
	ld de,00010h		;8ddd   ; la fila siguiente
	add iy,de		;8de0
	djnz mapa_objetos_fila		;8de2   ; B veces
	ret			;8de4
bloque_pinta:		; El bloque A (2 x 2 casillas de la tabla de 0x8E82) en HL, dentro de la zona de juego
	push hl			;8de5
	push de			;8de6   ; guardados
	push af			;8de7
	call bloque_casillas		;8de8   ; sus cuatro casillas
	ld a,(de)			;8deb   ; arriba a la izquierda
	call casilla_dentro		;8dec   ; WRTVRM dentro
	inc hl			;8def   ; la columna siguiente
	inc de			;8df0
	ld a,(de)			;8df1   ; arriba a la derecha
	call casilla_dentro		;8df2   ; WRTVRM dentro
	push de			;8df5
	ld de,0001fh		;8df6   ; la fila de abajo
	add hl,de			;8df9
	pop de			;8dfa
	inc de			;8dfb
	ld a,(de)			;8dfc   ; abajo a la izquierda
	call casilla_dentro		;8dfd   ; WRTVRM dentro
	inc de			;8e00
	inc hl			;8e01
	ld a,(de)			;8e02   ; abajo a la derecha
	call casilla_dentro		;8e03   ; WRTVRM dentro
	pop af			;8e06   ; recuperados
	pop de			;8e07
	pop hl			;8e08
	ret			;8e09
casilla_dentro:		; WRTVRM solo dentro de la zona de juego (0x1821-0x1ADF)
	push af			;8e0a   ; guardada
	ld a,h			;8e0b   ; la fila...
	cp 018h		;8e0c   ; ...antes de 0x1800: nada
	jr c,casilla_dentro_no		;8e0e
	jr z,casilla_dentro_18		;8e10   ; 0x18: mirar la columna
	cp 01ah		;8e12   ; 0x1A: mirar la columna
	jr z,casilla_dentro_1a		;8e14
	jr c,casilla_dentro_pon		;8e16   ; 0x19: dentro
	jr casilla_dentro_no		;8e18   ; desde 0x1B: fuera
casilla_dentro_1a:
	ld a,l			;8e1a   ; desde 0x1AE0...
	cp 0e0h		;8e1b
	jr nc,casilla_dentro_no		;8e1d   ; ...fuera
casilla_dentro_pon:
	pop af			;8e1f   ; la casilla
	call 0004dh		;8e20   ; WRTVRM
	ret			;8e23
casilla_dentro_18:
	ld a,l			;8e24   ; desde 0x1821...
	cp 021h		;8e25
	jr nc,casilla_dentro_pon		;8e27   ; ...dentro
casilla_dentro_no:
	pop af			;8e29   ; fuera: nada
	ret			;8e2a
bloque_casillas:		; DE = las cuatro casillas del bloque A (0x8E82 + A x 4); los bloques desde 0x80 son cosas: 0x84 el 15, 0xD8 el 9, 0xD4 el 13, desde 0xD9 el (A and 0x7C) / 4, y los demas segun sus dos bits bajos (3, 5, 10 o 12)
	push hl			;8e2b   ; guardado
	ld hl,08e82h		;8e2c   ; la tabla
	bit 7,a		;8e2f   ; una cosa?
	jr nz,bloque_cosa		;8e31
	and 03fh		;8e33   ; el bloque 0-63
bloque_casillas_va:
	rlc a		;8e35   ; x 4
	rlc a		;8e37   ; x 4
	ld e,a			;8e39   ; en DE
	ld d,000h		;8e3a
	add hl,de			;8e3c   ; + la tabla
	ex de,hl			;8e3d   ; DE: sus casillas
	pop hl			;8e3e
	ret			;8e3f
bloque_cosa:
	res 7,a		;8e40   ; sin el bit 7
	cp 004h		;8e42   ; 0x84?
	jr z,bloque_cosa84		;8e44
	cp 058h		;8e46   ; 0xD8?
	jr z,bloque_cosa58		;8e48
	cp 054h		;8e4a   ; 0xD4?
	jr z,bloque_cosa54		;8e4c
	cp 058h		;8e4e   ; desde 0xD9?
	jr nc,bloque_cosa_d8		;8e50
	and 003h		;8e52   ; los demas: los dos bits bajos
	cp 000h		;8e54   ; 0?
	jr z,bloque_cosa0		;8e56
	cp 001h		;8e58   ; 1?
	jr z,bloque_cosa1		;8e5a
	cp 002h		;8e5c   ; 2?
	jr z,bloque_cosa2		;8e5e
	ld a,00ch		;8e60   ; 3: el bloque 12
	jr bloque_casillas_va		;8e62
bloque_cosa0:
	ld a,003h		;8e64   ; el 3
	jr bloque_casillas_va		;8e66
bloque_cosa1:
	ld a,005h		;8e68   ; el 5
	jr bloque_casillas_va		;8e6a
bloque_cosa2:
	ld a,00ah		;8e6c   ; el 10
	jr bloque_casillas_va		;8e6e
bloque_cosa84:
	ld a,00fh		;8e70   ; el 15
	jr bloque_casillas_va		;8e72
bloque_cosa_d8:
	and 07ch		;8e74   ; (A and 0x7C)...
	rrca			;8e76   ; ...entre 4
	rrca			;8e77
	jr bloque_casillas_va		;8e78
bloque_cosa58:
	ld a,009h		;8e7a   ; el 9
	jr bloque_casillas_va		;8e7c
bloque_cosa54:
	ld a,00dh		;8e7e   ; el 13
	jr bloque_casillas_va		;8e80

