fase_cosas:		; Las cosas de la fase en el mapa de la RAM: la lista de la fase (0x4E1B, la fase x 2): hasta 0xFF, el sitio (x 16 desde 0xE80C) y tres bytes
	ld a,(0e00ah)		;90cf   ; la fase...
	rlca			;90d2   ; ...x 2
	ld e,a			;90d3
	ld d,000h		;90d4
	ld hl,04e1bh		;90d6   ; su lista (0x4E1B)
	add hl,de			;90d9
	ld e,(hl)			;90da
	inc hl			;90db
	ld d,(hl)			;90dc
	ld hl,0e80ch		;90dd   ; desde 0xE80C
	push de			;90e0
	pop ix		;90e1
fase_cosa:
	ld a,(ix+000h)		;90e3   ; 0xFF: el final
	cp 0ffh		;90e6
	jr z,fase_cosas_fin		;90e8
	ld e,a			;90ea   ; el sitio...
	xor a			;90eb   ; A = 0
	sla e		;90ec   ; ...x 16
	adc a,000h		;90ee   ; (lo que sale, a A)
	sla a		;90f0
	sla e		;90f2
	adc a,000h		;90f4
	sla a		;90f6
	sla e		;90f8
	adc a,000h		;90fa
	sla a		;90fc
	sla e		;90fe
	adc a,000h		;9100
	ld d,a			;9102   ; DE: el sitio x 16
	add hl,de			;9103   ; + el principio
	ld a,(ix+001h)		;9104   ; tres bytes
	ld (hl),a			;9107   ; el primero
	ld a,(ix+002h)		;9108   ; el segundo
	inc hl			;910b
	ld (hl),a			;910c   ; en su sitio
	inc hl			;910d
	ld a,(ix+003h)		;910e   ; el tercero
	ld (hl),a			;9111
	dec hl			;9112
	dec hl			;9113
	push de			;9114
	ld de,00004h		;9115   ; la siguiente (4 bytes)
	add ix,de		;9118
	pop de			;911a
	jr fase_cosa		;911b
fase_cosas_fin:
	ret			;911d
nada_911e:		; Un "ret": nada
	ret			;911e
nada_911f:		; Otro "ret": nada
	ret			;911f

