DATA_codigo_suelto_9120:
	defb 006h,000h,03ah,008h,0e3h,0d6h,00ah,038h,00ah,006h,010h,0d6h,00ah,038h,004h,006h	; 9120  ..:....8.....8..
	defb 020h,018h,002h,0c6h,00ah,04fh,0afh,079h,080h,027h,047h,0e6h,00fh,021h,05dh,019h	; 9130   ....O.y.'G..!].
	defb 0cdh,04dh,000h,078h,0e6h,0f0h,00fh,00fh,00fh,00fh,021h,05ch,019h,0cdh,04dh,000h	; 9140  .M.x......!\..M.
	defb 0c9h	; 9150

; ======================================================================
; CODIGO 0x9151..0x92ce  (381 bytes)
; ======================================================================


tiempo:		; TIME baja un segundo cada 0x40 cuadros (0xE015): los segundos (0xE320, BCD, de 59 a 0) y los minutos (0xE31F); al pasar de 0:00, el protagonista tocado (0xE183 = 1)
	ld a,(0e015h)		;9151   ; 0x40 cuadros?
	cp 040h		;9154
	ret c			;9156
	xor a			;9157   ; la cuenta a 0
	ld (0e015h),a		;9158   ; en la cuenta del tiempo
	ld a,(0e320h)		;915b   ; los segundos...
	dec a			;915e
	cp 0ffh		;915f   ; ...a 0?
	jr z,tiempo_minuto		;9161
	xor a			;9163
	ld a,(0e320h)		;9164   ; un segundo menos
	dec a			;9167
	daa			;9168   ; en BCD
	ld (0e320h),a		;9169   ; en los segundos
	ret			;916c
tiempo_minuto:
	ld a,059h		;916d   ; 59 segundos...
	ld (0e320h),a		;916f   ; en los segundos
	ld a,(0e31fh)		;9172   ; ...y un minuto menos
	dec a			;9175
	daa			;9176
	ld (0e31fh),a		;9177   ; en los minutos
	cp 099h		;917a   ; pasado de 0?
	ret nz			;917c
	xor a			;917d   ; tocado
	ld (0e320h),a		;917e   ; en los segundos
	ld a,001h		;9181
	ld (0e183h),a		;9183   ; en tocado
	ret			;9186
tiempo_pinta:		; El tiempo (minutos y segundos) en la fila 7, columnas 26-30 (con el bonus, los minutos a 9: nada)
	ld a,(0e31fh)		;9187   ; los minutos...
	and 0f0h		;918a
	rrca			;918c
	rrca			;918d
	rrca			;918e
	rrca			;918f
	cp 009h		;9190   ; ...9: nada
	ret z			;9192
	ld hl,018fah		;9193   ; la fila 7, columna 26
	call 0004dh		;9196   ; WRTVRM
	ld a,(0e31fh)		;9199   ; la cifra baja
	and 00fh		;919c
	ld hl,018fbh		;919e
	call 0004dh		;91a1   ; WRTVRM
	ld a,(0e320h)		;91a4   ; los segundos
	and 0f0h		;91a7
	rrca			;91a9
	rrca			;91aa
	rrca			;91ab
	rrca			;91ac
	ld hl,018fdh		;91ad   ; la columna 29
	call 0004dh		;91b0   ; WRTVRM
	ld a,(0e320h)		;91b3   ; la cifra baja
	and 00fh		;91b6
	ld hl,018feh		;91b8
	call 0004dh		;91bb   ; WRTVRM
	ret			;91be
fase_pantalla:		; El marco, el marcador y el protagonista en su sitio de salida (Y 0x98, X 8; dibujos 0 y 4, colores 15 y 10)
	call pantalla_blanco		;91bf   ; la pantalla
	call marco		;91c2   ; el marco
	call marcador_pon		;91c5   ; el marcador
	ld iy,0e100h		;91c8   ; el protagonista
	ld (iy+000h),098h		;91cc
	ld (iy+001h),008h		;91d0
	ld (iy+002h),000h		;91d4
	ld (iy+003h),00fh		;91d8
	ld (iy+010h),098h		;91dc
	ld (iy+011h),008h		;91e0
	ld (iy+012h),004h		;91e4
	ld (iy+013h),00ah		;91e8
	ret			;91ec
mapa_ram:		; El mapa de la fase en la RAM (0xE800): la lista de la fase (0xE313): hasta 0xFF, un salto y una pieza (la tabla de 0x8F02)
	ld hl,0e800h		;91ed   ; el mapa de la RAM
	ld ix,(0e313h)		;91f0   ; la lista de la fase
mapa_ram_pieza:
	ld a,(ix+000h)		;91f4   ; 0xFF: el final
	cp 0ffh		;91f7
	ret z			;91f9
	ld e,a			;91fa   ; el salto
	ld d,000h		;91fb
	add hl,de			;91fd
	inc ix		;91fe
	ld a,(ix+000h)		;9200   ; la pieza
	push hl			;9203
	call pieza_pon		;9204
	pop hl			;9207
	inc ix		;9208
	jr mapa_ram_pieza		;920a
pieza_pon:		; La pieza A (0x8F02): bloque, salto, bloque, salto... hasta 0x7F
	push hl			;920c
	rl a		;920d   ; x 2
	ld e,a			;920f
	ld d,000h		;9210
	ld hl,08f02h		;9212   ; la tabla
	add hl,de			;9215
	ld e,(hl)			;9216
	inc hl			;9217
	ld d,(hl)			;9218
	pop hl			;9219
pieza_bloque:
	ld a,(de)			;921a   ; 0x7F: el final
	cp 07fh		;921b
	ret z			;921d
	ld (hl),a			;921e   ; el bloque
	inc de			;921f
	ld a,(de)			;9220   ; el salto
	cp 07fh		;9221
	ret z			;9223
	push de			;9224
	ld d,000h		;9225
	bit 7,a		;9227   ; hacia atras?
	jr z,pieza_salta		;9229
	ld d,0ffh		;922b
pieza_salta:
	ld e,a			;922d
	add hl,de			;922e
	pop de			;922f
	inc de			;9230
	jr pieza_bloque		;9231
marco:		; El marco de la zona de juego: las casillas 0xA0-0xA7 alrededor (24 filas)
	ld hl,01800h		;9233   ; la columna 0
	ld b,018h		;9236
	ld a,0a7h		;9238
	call marco_columna		;923a
	ld hl,01819h		;923d   ; la columna 25
	ld b,018h		;9240
	ld a,0a3h		;9242
	call marco_columna		;9244
	ld hl,01801h		;9247   ; la fila 0
	ld b,018h		;924a
	ld a,0a1h		;924c
	call marco_fila		;924e
	ld hl,01ae1h		;9251   ; la fila 23
	ld b,018h		;9254
	ld a,0a5h		;9256
	call marco_fila		;9258
	ld a,0a0h		;925b   ; las esquinas
	ld hl,01800h		;925d
	call 0004dh		;9260   ; WRTVRM
	ld a,0a2h		;9263
	ld hl,01819h		;9265
	call 0004dh		;9268   ; WRTVRM
	ld a,0a6h		;926b
	ld hl,01ae0h		;926d
	call 0004dh		;9270   ; WRTVRM
	ld a,0a4h		;9273
	ld hl,01af9h		;9275
	call 0004dh		;9278   ; WRTVRM
	ret			;927b
marco_columna:		; B casillas A en columna desde HL
	ld de,00020h		;927c
marco_columna_1:
	call 0004dh		;927f   ; WRTVRM
	add hl,de			;9282
	djnz marco_columna_1		;9283   ; B veces
	ret			;9285
marco_fila:		; B casillas A en fila desde HL
	call 0004dh		;9286   ; WRTVRM
	inc hl			;9289
	djnz marco_fila		;928a   ; B veces
	ret			;928c
marcador_pon:		; El marcador de la derecha: HIGH (fila 0), SCORE (fila 2), STAGE (fila 4), TIME (fila 6) y ":"; el "     0" que iba en la fila 3 no sale: la instruccion de 0x92AB carga HL en vez de DE
	ld de,092ech		;928d   ; HIGH
	ld hl,0181ah		;9290
	call texto_vram		;9293
	ld de,092d3h		;9296   ; SCORE
	ld hl,0185ah		;9299
	call texto_vram		;929c
	ld hl,0189ah		;929f   ; STAGE
	ld de,092d9h		;92a2
	call texto_vram		;92a5
	ld hl,0187ah		;92a8   ; la fila 3...
	ld hl,092dfh		;92ab   ; ...y aqui HL otra vez: DE sigue en el 0xFF de STAGE y no escribe nada
	call texto_vram		;92ae
	ld hl,018dah		;92b1   ; TIME
	ld de,092ceh		;92b4
	call texto_vram		;92b7
	ld hl,018fch		;92ba   ; ":" en la fila 7
	ld a,00ah		;92bd
	call 0004dh		;92bf   ; WRTVRM
	ret			;92c2
texto_vram:		; Un texto (hasta 0xFF) de DE en HL
	ld a,(de)			;92c3
	cp 0ffh		;92c4   ; 0xFF: el final
	ret z			;92c6
	call 0004dh		;92c7   ; WRTVRM
	inc hl			;92ca
	inc de			;92cb
	jr texto_vram		;92cc

; ----------------------------------------------------------------------
; DATOS marcador_textos: TIME (0x92CE), SCORE (0x92D3), STAGE (0x92D9), "
;   0" (0x92DF, no sale), FLOOR (0x92E6) y HIGH (0x92EC)
;   0x92ce..0x92f1  (35 bytes)
DATA_marcador_textos:
	defb 024h,019h,01dh,015h,0ffh,023h,013h,01fh,022h,015h,0ffh,023h,024h,011h,017h,015h	; 92ce  $....#.."..#$...
	defb 0ffh,010h,010h,010h,010h,010h,000h,0ffh,016h,01ch,01fh,01fh,022h,0ffh,018h,019h	; 92de  ............"...
	defb 017h,018h,0ffh	; 92ee

; ======================================================================
; CODIGO 0x92f1..0x931e  (45 bytes)
; ======================================================================


objetos:		; Los cinco objetos de 0xE120 (16 bytes; +4 el tipo, el bit 7 en marcha): cada uno a su rutina por la tabla de 0x931E
	ld iy,0e120h		;92f1   ; los objetos
	ld ix,0e100h		;92f5   ; el protagonista
	ld de,00010h		;92f9
	ld b,005h		;92fc   ; cinco
objetos_uno:
	push de			;92fe
	push bc			;92ff
	call objeto_salta		;9300   ; su rutina
	pop bc			;9303
	pop de			;9304
	add iy,de		;9305   ; el siguiente
	djnz objetos_uno		;9307   ; B veces
	ret			;9309
objeto_salta:		; Salta a la rutina del tipo (+4, sin el bit 7)
	ld a,(iy+004h)		;930a   ; el tipo
	and a			;930d   ; ninguno
	ret z			;930e
	ld hl,0931eh		;930f   ; la tabla
	and 07fh		;9312   ; sin el bit 7
	rlca			;9314   ; x 2
	ld e,a			;9315
	ld d,000h		;9316
	add hl,de			;9318
	ld e,(hl)			;9319   ; la direccion
	inc hl			;931a
	ld d,(hl)			;931b
	ex de,hl			;931c
	jp (hl)			;931d   ; salta

; ----------------------------------------------------------------------
; DATOS tabla_931e: Las rutinas de los 11 tipos de 0x930A (la 0, 0x0000, sin
;   uso)
;   0x931e..0x9334  (22 bytes)
DATA_tabla_931e:
	defb 000h,000h,034h,093h,005h,095h,072h,095h,0bfh,095h,06ah,096h,08eh,097h,0abh,098h	; 931e  ..4...r...j.....
	defb 0dbh,097h,01ah,098h,057h,098h	; 932e

; ======================================================================
; CODIGO 0x9334..0x9465  (305 bytes)
; ======================================================================


andarin:		; El tipo 1: anda por el mapa mirando las casillas de alrededor (0x93FA): sigue, da la vuelta, salta (la tabla de 0x9465) o cae; al salir, color 7, dibujo 0x80
	bit 7,(iy+004h)		;9334   ; en marcha?
	jr nz,andarin_va		;9338
	ld (iy+005h),080h		;933a   ; al salir: +5 = 0x80...
	ld (iy+003h),007h		;933e   ; ...color 7...
	ld (iy+002h),080h		;9342   ; ...dibujo 0x80
	set 7,(iy+004h)		;9346   ; en marcha
andarin_va:
	call dibujo_lado		;934a   ; toca al protagonista?
	ld a,(iy+00eh)		;934d   ; saltando o cayendo?
	and 038h		;9350
	jp nz,andarin_paso		;9352
	ld a,(iy+001h)		;9355   ; en una columna exacta?
	and 00fh		;9358
	cp 008h		;935a
	jp nz,andarin_paso		;935c
	call sitio_vram		;935f   ; su sitio en la pantalla
	call pantalla_a_mapa		;9362
	ld de,00020h		;9365   ; la fila de abajo
	add hl,de			;9368
	bit 0,(iy+00eh)		;9369   ; hacia la derecha?
	jr nz,andarin_der		;936d
	jr andarin_izq		;936f
andarin_der:
	ld c,000h		;9371   ; lo que hay alrededor, en C
	ld a,(iy+001h)		;9373   ; en el borde derecho?
	cp 0b0h		;9376
	jr c,andarin_der_mira		;9378
	ld a,00eh		;937a
	or c			;937c
	ld c,a			;937d
andarin_der_mira:
	ld a,(hl)			;937e   ; suelo?
	and a			;937f
	jr z,andarin_der_casillas		;9380
	set 0,c		;9382
	rrc c		;9384
andarin_der_casillas:
	inc hl			;9386
	call alrededor		;9387   ; las de delante
	bit 0,c		;938a   ; sin suelo: cae
	jp z,andarin_cae		;938c
	ld a,c			;938f
	and 00ch		;9390   ; pared delante y arriba?
	cp 00ch		;9392
	jp z,andarin_vuelta		;9394
	cp 004h		;9397   ; un escalon?
	jp z,andarin_salta_der		;9399
	ld a,c			;939c
	and 07eh		;939d
	cp 040h		;939f
	jp z,andarin_salta_der		;93a1
	cp 020h		;93a4
	jp z,andarin_salta_der		;93a6
	cp 060h		;93a9
	jp z,andarin_salta_der		;93ab
	ld a,001h		;93ae   ; sigue a la derecha
	ld (iy+00eh),a		;93b0
	jp andarin_paso		;93b3
andarin_izq:
	ld c,000h		;93b6
	ld a,(iy+001h)		;93b8   ; en el borde izquierdo?
	cp 008h		;93bb
	jr nc,andarin_izq_mira		;93bd
	ld a,070h		;93bf
	or c			;93c1
	ld c,a			;93c2
andarin_izq_mira:
	ld a,(hl)			;93c3   ; algo debajo?
	and a			;93c4
	jr z,andarin_der_casillas		;93c5   ; no: a mirar las casillas
	set 0,c		;93c7   ; algo: el bit
	rrc c		;93c9   ; al siguiente
	dec hl			;93cb   ; las de delante
	dec hl			;93cc
	call alrededor		;93cd   ; las seis de alrededor
	bit 0,c		;93d0   ; nada debajo?
	jr z,andarin_cae		;93d2   ; cae
	ld a,c			;93d4   ; las de delante...
	and 030h		;93d5
	cp 030h		;93d7   ; ...las dos ocupadas?
	jp z,andarin_vuelta		;93d9   ; media vuelta
	cp 020h		;93dc   ; solo la de arriba?
	jr z,andarin_salta_izq		;93de   ; salta
	ld a,c			;93e0   ; las demas
	and 07eh		;93e1
	cp 006h		;93e3   ; un escalon?
	jp z,andarin_salta_izq		;93e5
	cp 004h		;93e8   ; un escalon?
	jp z,andarin_salta_izq		;93ea
	cp 002h		;93ed   ; un escalon?
	jp z,andarin_salta_izq		;93ef
	ld a,002h		;93f2   ; sigue a la izquierda
	ld (iy+00eh),a		;93f4
	jp andarin_paso		;93f7
alrededor:		; Las seis casillas alrededor de HL (dos arriba, una al lado, dos abajo...), un bit cada una, en C
	ld de,0fff0h		;93fa   ; una fila arriba
	ld a,(hl)			;93fd   ; algo?
	and a			;93fe
	jr z,alrededor_1		;93ff
	set 0,c		;9401   ; el bit
alrededor_1:
	rrc c		;9403   ; al siguiente
	add hl,de			;9405   ; la de arriba
	ld a,(hl)			;9406   ; algo?
	and a			;9407
	jr z,alrededor_2		;9408
	set 0,c		;940a   ; el bit
alrededor_2:
	rrc c		;940c   ; al siguiente
	add hl,de			;940e   ; dos arriba
	ld a,(hl)			;940f   ; algo?
	and a			;9410
	jr z,alrededor_3		;9411
	set 0,c		;9413   ; el bit
alrededor_3:
	rrc c		;9415   ; al siguiente
	inc hl			;9417   ; al lado
	ld a,(hl)			;9418   ; algo?
	and a			;9419
	jr z,alrededor_4		;941a
	set 0,c		;941c   ; el bit
alrededor_4:
	rrc c		;941e   ; al siguiente
	ld de,00010h		;9420   ; una fila abajo
	add hl,de			;9423
	ld a,(hl)			;9424   ; algo?
	and a			;9425
	jr z,alrededor_5		;9426
	set 0,c		;9428   ; el bit
alrededor_5:
	rrc c		;942a   ; al siguiente
	add hl,de			;942c   ; otra abajo
	ld a,(hl)			;942d   ; algo?
	and a			;942e
	jr z,alrededor_fin		;942f
	set 0,c		;9431   ; el bit
alrededor_fin:
	rrc c		;9433   ; al siguiente
	rrc c		;9435   ; los seis bits en su sitio
	ret			;9437
andarin_cae:
	ld a,(iy+00eh)		;9438   ; cae (+0xE con el bit 3)
	and 003h		;943b
	ld b,a			;943d
	ld a,008h		;943e
	or b			;9440
	ld (iy+00eh),a		;9441
	jp andarin_paso		;9444
andarin_salta_izq:
	ld a,022h		;9447   ; salta a la izquierda
	jr andarin_salta		;9449
andarin_salta_der:
	ld a,011h		;944b   ; salta a la derecha
andarin_salta:
	ld (iy+00eh),a		;944d
	ld (iy+006h),000h		;9450   ; el paso del salto a 0
	jr $+50		;9454
salto_paso:		; El paso siguiente del salto (+6) de la tabla de 0x9465
	ld a,(iy+006h)		;9456   ; el paso
	inc (iy+006h)		;9459   ; uno mas
	ld e,a			;945c
	ld d,000h		;945d
	ld hl,09465h		;945f   ; la tabla
	add hl,de			;9462
	ld a,(hl)			;9463
	ret			;9464

; ----------------------------------------------------------------------
; DATOS salto_tabla: Cuanto sube (negativo) o baja en cada paso del salto;
;   0x80 el final
;   0x9465..0x9479  (20 bytes)
DATA_salto_tabla:
	defb 004h,004h,004h,004h,002h,002h,001h,001h,000h,000h,0ffh,0ffh,0feh,0feh,0fch,0fch	; 9465  ................
	defb 0fch,0fch,080h,080h	; 9475

; ======================================================================
; CODIGO 0x9479..0x9662  (489 bytes)
; ======================================================================


andarin_vuelta:
	ld a,(iy+00eh)		;9479   ; da la vuelta
	and 003h		;947c
	cpl			;947e
	and 003h		;947f
	ld (iy+00eh),a		;9481
	jr andarin_paso		;9484
andarin_paso:		; Cada 6 cuadros un paso: cayendo, saltando o andando
	call aplastado_objeto		;9486   ; su dibujo
	inc (iy+00fh)		;9489   ; la cuenta
	ld a,(iy+00fh)		;948c   ; 6?
	cp 006h		;948f
	jp c,andarin_fin		;9491
	ld (iy+00fh),000h		;9494   ; a cero
	ld a,(iy+00eh)		;9498   ; lo que hace
	bit 3,a		;949b   ; cayendo?
	jp nz,objeto_abajo		;949d
	bit 4,a		;94a0   ; saltando a la derecha?
	jp nz,andarin_salto_der		;94a2
	bit 5,a		;94a5   ; saltando a la izquierda?
	jp nz,andarin_salto_izq		;94a7
	bit 0,a		;94aa   ; a la derecha?
	jp nz,objeto_der		;94ac
	bit 1,a		;94af   ; a la izquierda?
	jp nz,objeto_izq		;94b1
	bit 2,a		;94b4   ; parado?
	jp nz,objeto_arriba		;94b6
	set 0,a		;94b9
	ld (iy+00eh),a		;94bb
	jr andarin_fin		;94be
andarin_salto_izq:
	call izq_paso		;94c0   ; un paso a la izquierda
	jr andarin_salto_paso		;94c3
andarin_salto_der:
	call der_paso		;94c5   ; un paso a la derecha
andarin_salto_paso:
	call salto_paso		;94c8   ; cuanto
	and a			;94cb   ; 0: nada
	jr z,andarin_fin		;94cc
	cp 080h		;94ce   ; 0x80: acabado
	jr z,andarin_salto_fin		;94d0
	jr c,andarin_sube		;94d2
	neg		;94d4   ; negativo: hacia abajo
	ld b,a			;94d6
andarin_baja:
	push bc			;94d7
	call abajo_paso		;94d8   ; un punto abajo
	pop bc			;94db
	cp 010h		;94dc   ; en el suelo?
	jr nz,andarin_fin		;94de
	djnz andarin_baja		;94e0   ; B veces
	jr andarin_fin		;94e2
andarin_sube:
	ld b,a			;94e4
andarin_sube_punto:
	push bc			;94e5
	call arriba_paso		;94e6   ; un punto arriba
	pop bc			;94e9
	cp 010h		;94ea   ; chocado?
	jr nz,andarin_fin		;94ec
	djnz andarin_sube_punto		;94ee   ; B veces
	jr andarin_fin		;94f0
andarin_salto_fin:
	ld a,(iy+00eh)		;94f2   ; de pie
	and 003h		;94f5
	jr nz,andarin_salto_pon		;94f7
	ld a,008h		;94f9
andarin_salto_pon:
	ld (iy+00eh),a		;94fb
andarin_fin:
	call toca_prota		;94fe   ; su sitio en la pantalla
	call objeto_dentro		;9501   ; los sprites
	ret			;9504
rodador:		; El tipo 2: dibujo 0x98, color 15; cada 8 cuadros un paso: cae si no hay suelo; si no, sigue hacia donde va
	bit 7,(iy+004h)		;9505   ; en marcha?
	jr nz,rodador_va		;9509
	ld (iy+005h),098h		;950b   ; +5 = 0x98
	ld (iy+003h),00fh		;950f   ; color 15
	ld (iy+002h),098h		;9513   ; dibujo 0x98
	set 7,(iy+004h)		;9517   ; en marcha
rodador_va:
	inc (iy+00fh)		;951b   ; la cuenta
	ld a,(iy+00fh)		;951e
	cp 008h		;9521   ; 8?
	jr c,rodador_fin		;9523
	ld (iy+00fh),000h		;9525   ; a cero
	call dibujo_lado		;9529   ; toca al protagonista?
	ld a,(iy+001h)		;952c   ; su X
	and 00fh		;952f   ; en una columna exacta?
	cp 008h		;9531
	jr nz,rodador_paso		;9533
	call sitio_vram		;9535   ; su sitio
	call pantalla_a_mapa		;9538   ; en el mapa
	ld de,00020h		;953b   ; la fila de abajo
	add hl,de			;953e
	ld a,(hl)			;953f   ; hay suelo?
	and a			;9540
	jr nz,rodador_paso		;9541
	ld a,008h		;9543   ; cae
	ld (iy+00eh),a		;9545   ; apuntado
rodador_paso:
	call aplastado_objeto		;9548   ; su dibujo
	ld (iy+00fh),000h		;954b   ; a cero
	ld a,(iy+00eh)		;954f   ; lo que hace
	bit 0,a		;9552   ; a la derecha?
	jp nz,objeto_der		;9554
	bit 1,a		;9557   ; a la izquierda?
	jp nz,objeto_izq		;9559
	bit 2,a		;955c   ; parado?
	jp nz,objeto_arriba		;955e
	bit 3,a		;9561   ; cayendo?
	jp nz,objeto_abajo		;9563
	set 0,a		;9566   ; a la derecha
	ld (iy+00eh),a		;9568   ; apuntado
rodador_fin:
	call toca_prota		;956b   ; su sitio en la pantalla
	call objeto_dentro		;956e   ; los sprites
	ret			;9571
volador:		; El tipo 3: dibujo 0xA8, color 15; cada 16 cuadros un paso hacia donde va, sin caer
	bit 7,(iy+004h)		;9572   ; en marcha?
	jr nz,volador_va		;9576
	ld (iy+005h),0a8h		;9578   ; +5 = 0xA8
	ld (iy+003h),00fh		;957c   ; color 15
	ld (iy+002h),0a8h		;9580   ; dibujo 0xA8
	set 7,(iy+004h)		;9584   ; en marcha
volador_va:
	call aplastado_objeto		;9588   ; su dibujo
	call dibujo_anima		;958b   ; toca al protagonista?
	inc (iy+00fh)		;958e   ; la cuenta
	ld a,(iy+00fh)		;9591
	cp 010h		;9594   ; 16?
	jr c,volador_fin		;9596
	ld (iy+00fh),000h		;9598   ; a cero
	ld a,(iy+00eh)		;959c   ; lo que hace
	bit 0,a		;959f
	jp nz,objeto_der		;95a1
	bit 1,a		;95a4
	jp nz,objeto_izq		;95a6
	bit 2,a		;95a9
	jp nz,objeto_arriba		;95ab
	bit 3,a		;95ae
	jp nz,objeto_abajo		;95b0
	set 0,a		;95b3   ; a la derecha
	ld (iy+00eh),a		;95b5   ; apuntado
volador_fin:
	call toca_prota		;95b8
	call objeto_dentro		;95bb
	ret			;95be
andador_bichos:		; El tipo 4: dibujo 0xC8, color 8; cada 12 cuadros cambia de dibujo (0x9662 o 0x9666, segun el lado; en la fase 5, no); cada 8, un paso; cae si no hay suelo
	bit 7,(iy+004h)		;95bf   ; en marcha?
	jr nz,andador_bichos_va		;95c3
	ld (iy+005h),0c8h		;95c5   ; +5 = 0xC8
	ld (iy+002h),0c8h		;95c9   ; dibujo 0xC8
	ld (iy+003h),008h		;95cd   ; color 8
	set 7,(iy+004h)		;95d1   ; en marcha
andador_bichos_va:
	inc (iy+00ch)		;95d5   ; la cuenta del dibujo
	ld a,(iy+00ch)		;95d8
	cp 00ch		;95db   ; 12?
	jr c,andador_bichos_paso		;95dd
	ld (iy+00ch),000h		;95df
	ld hl,09662h		;95e3   ; los dibujos a la derecha...
	bit 0,(iy+00eh)		;95e6
	jr z,andador_bichos_dibujo		;95ea
	ld hl,09666h		;95ec   ; ...o a la izquierda
andador_bichos_dibujo:
	ld a,(iy+00dh)		;95ef   ; el siguiente de tres
	inc (iy+00dh)		;95f2
	cp 003h		;95f5
	jr c,andador_bichos_pon		;95f7
	ld (iy+00dh),000h		;95f9
	jr andador_bichos_dibujo		;95fd
andador_bichos_pon:
	push af			;95ff
	ld a,(0e00ah)		;9600   ; la fase 5?
	cp 005h		;9603
	jr z,andador_bichos_fin_dibujo		;9605
	pop af			;9607
	push af			;9608
	ld e,a			;9609
	ld d,000h		;960a
	add hl,de			;960c
	ld a,(hl)			;960d   ; su dibujo
	ld (iy+002h),a		;960e
andador_bichos_fin_dibujo:
	pop af			;9611
andador_bichos_paso:
	call aplastado_objeto		;9612   ; su dibujo
	ld a,(iy+001h)		;9615   ; su X
	and 00fh		;9618   ; en una columna exacta?
	cp 008h		;961a
	jr nz,andador_bichos_cuenta		;961c
	call sitio_vram		;961e
	call pantalla_a_mapa		;9621
	ld de,00020h		;9624   ; la fila de abajo
	add hl,de			;9627
	ld a,(hl)			;9628   ; hay suelo?
	and a			;9629
	jr nz,andador_bichos_cuenta		;962a
	ld a,008h		;962c   ; cae
	ld (iy+00eh),a		;962e   ; apuntado
andador_bichos_cuenta:
	inc (iy+00fh)		;9631   ; la cuenta
	ld a,(iy+00fh)		;9634
	cp 008h		;9637
	jr c,andador_bichos_fin		;9639
	ld (iy+00fh),000h		;963b   ; a cero
	ld a,(iy+00eh)		;963f   ; lo que hace
	bit 0,a		;9642
	jp nz,objeto_der		;9644
	bit 1,a		;9647
	jp nz,objeto_izq		;9649
	bit 2,a		;964c
	jp nz,objeto_arriba		;964e
	bit 3,a		;9651
	jp nz,objeto_abajo		;9653
	set 0,a		;9656   ; a la derecha
	ld (iy+00eh),a		;9658   ; apuntado
andador_bichos_fin:
	call toca_prota		;965b
	call objeto_dentro		;965e
	ret			;9661

; ----------------------------------------------------------------------
; DATOS andador_dibujos: Los tres dibujos del tipo 4 a la derecha (0x9662) y a
;   la izquierda (0x9666)
;   0x9662..0x966a  (8 bytes)
DATA_andador_dibujos:
	defb 0c8h,0cch,0d0h,0ffh,0d0h,0cch,0c8h,0ffh	; 9662  ........

; ======================================================================
; CODIGO 0x966a..0x98f2  (648 bytes)
; ======================================================================


laberinto:		; El tipo 5: dibujo 0xE0, color 8; cada 16 cuadros, en el cruce de una casilla, mira las cuatro de alrededor y el borde, y sigue la pared: gira a la derecha, sigue o da la vuelta; si se queda sin salida, desaparece
	bit 7,(iy+004h)		;966a   ; ya empezado?
	jr nz,laberinto_va		;966e
	ld (iy+005h),0e0h		;9670   ; el primer dibujo 0xE0
	ld (iy+003h),008h		;9674   ; el color 8
	ld (iy+002h),0e0h		;9678   ; el dibujo 0xE0
	set 7,(iy+004h)		;967c   ; empezado
laberinto_va:
	call color_parpadea		;9680   ; el color parpadea
	call aplastado_objeto		;9683   ; aplastado?
	call dibujo_anima		;9686   ; cambia de dibujo
	inc (iy+00fh)		;9689
	ld a,(iy+00fh)		;968c
	cp 010h		;968f   ; 16?
	jp c,laberinto_fin		;9691
	ld (iy+00fh),000h		;9694
	ld a,(iy+000h)		;9698   ; en una fila exacta?
	and 00fh		;969b
	cp 008h		;969d
	jp nz,laberinto_paso		;969f
	ld a,(iy+001h)		;96a2   ; y en una columna?
	and 00fh		;96a5
	cp 008h		;96a7
	jp nz,laberinto_paso		;96a9
	call sitio_vram		;96ac   ; su sitio
	call pantalla_a_mapa		;96af   ; en el mapa
	ld c,000h		;96b2   ; los bordes, en C
	ld a,(iy+000h)		;96b4   ; arriba del todo?
	cp 009h		;96b7
	jr nc,laberinto_borde2		;96b9
	set 0,c		;96bb
laberinto_borde2:
	cp 0b8h		;96bd
	jr c,laberinto_borde3		;96bf
	set 1,c		;96c1
laberinto_borde3:
	ld a,(iy+001h)		;96c3   ; a la izquierda del todo?
	cp 009h		;96c6
	jr nc,laberinto_borde4		;96c8
	set 2,c		;96ca
laberinto_borde4:
	cp 0b8h		;96cc
	jr c,laberinto_mira		;96ce
	set 3,c		;96d0
laberinto_mira:
	call casilla_bit		;96d2   ; la casilla de encima...
	ld de,00020h		;96d5
	add hl,de			;96d8
	call casilla_bit		;96d9   ; ...la de debajo...
	ld de,0ffefh		;96dc
	add hl,de			;96df
	call casilla_bit		;96e0   ; ...la de la izquierda...
	inc hl			;96e3
	inc hl			;96e4
	call casilla_bit		;96e5   ; ...y la de la derecha
	rrc c		;96e8
	rrc c		;96ea
	rrc c		;96ec
	rrc c		;96ee
	ld a,(iy+00eh)		;96f0   ; hacia donde va
	rrca			;96f3
	jr c,laberinto_der		;96f4
	rrca			;96f6
	jr c,laberinto_izq		;96f7
	rrca			;96f9
	jr c,laberinto_arriba		;96fa
	rrca			;96fc
	jr c,laberinto_abajo		;96fd
	ld a,001h		;96ff   ; quieto: a la derecha
	ld (iy+00eh),a		;9701
	ret			;9704
laberinto_der:
	bit 1,c		;9705   ; a la derecha: la de abajo libre?
	jr z,laberinto_a_abajo		;9707
	bit 3,c		;9709
	jr z,laberinto_paso		;970b
	bit 0,c		;970d
	jr z,laberinto_a_arriba		;970f
	bit 2,c		;9711
	jr z,laberinto_a_izq		;9713
	jp objeto_fuera		;9715
laberinto_izq:
	bit 0,c		;9718   ; a la izquierda: la de arriba libre?
	jr z,laberinto_a_arriba		;971a
	bit 2,c		;971c
	jr z,laberinto_paso		;971e
	bit 1,c		;9720
	jr z,laberinto_a_abajo		;9722
	bit 3,c		;9724
	jr z,laberinto_a_der		;9726
	jp objeto_fuera		;9728
laberinto_arriba:
	bit 3,c		;972b   ; a la derecha libre?
	jr z,laberinto_a_der		;972d
	bit 0,c		;972f   ; arriba libre?
	jr z,laberinto_paso		;9731
	bit 2,c		;9733   ; a la izquierda libre?
	jr z,laberinto_a_izq		;9735
	bit 1,c		;9737   ; abajo libre?
	jr z,laberinto_a_abajo		;9739
	jp objeto_fuera		;973b   ; encerrado: fuera
laberinto_abajo:
	bit 2,c		;973e   ; a la izquierda libre?
	jr z,laberinto_a_izq		;9740
	bit 1,c		;9742   ; abajo libre?
	jr z,laberinto_paso		;9744
	bit 3,c		;9746   ; a la derecha libre?
	jr z,laberinto_a_der		;9748
	bit 0,c		;974a   ; arriba libre?
	jr z,laberinto_a_arriba		;974c
	jp objeto_fuera		;974e   ; encerrado: fuera
laberinto_a_der:
	ld a,001h		;9751   ; a la derecha
	jr laberinto_pon		;9753
laberinto_a_izq:
	ld a,002h		;9755   ; a la izquierda
	jr laberinto_pon		;9757
laberinto_a_arriba:
	ld a,004h		;9759   ; arriba
	jr laberinto_pon		;975b
laberinto_a_abajo:
	ld a,008h		;975d   ; abajo
laberinto_pon:
	ld (iy+00eh),a		;975f
laberinto_paso:
	ld a,(iy+00eh)		;9762
	bit 0,a		;9765   ; a la derecha?
	jp nz,objeto_der		;9767
	bit 1,a		;976a   ; a la izquierda?
	jp nz,objeto_izq		;976c
	bit 2,a		;976f   ; arriba?
	jp nz,objeto_arriba		;9771
	bit 3,a		;9774   ; abajo?
	jp nz,objeto_abajo		;9776
	set 0,a		;9779
	ld (iy+00eh),a		;977b
laberinto_fin:
	call toca_prota		;977e
	call objeto_dentro		;9781
	ret			;9784
casilla_bit:		; Un bit mas en C: 1 si la casilla (HL) no esta vacia
	ld a,(hl)			;9785
	and a			;9786
	jr z,casilla_bit_fin		;9787
	set 0,c		;9789
casilla_bit_fin:
	rrc c		;978b
	ret			;978d
rodante:		; El tipo 6: dibujo 0xEC, color 15; cada 12 cuadros un paso hacia donde va (derecha, izquierda, arriba o abajo; al chocar, al reves)
	bit 7,(iy+004h)		;978e   ; ya empezado?
	jr nz,rodante_va		;9792
	ld (iy+005h),0ech		;9794   ; el primer dibujo 0xEC
	ld (iy+003h),00fh		;9798   ; el color 15
	ld (iy+002h),0ech		;979c   ; el dibujo 0xEC
	set 7,(iy+004h)		;97a0   ; empezado
rodante_va:
	call aplastado_objeto		;97a4   ; aplastado?
	call dibujo_anima		;97a7   ; cambia de dibujo
	inc (iy+00fh)		;97aa
	ld a,(iy+00fh)		;97ad
	cp 00ch		;97b0   ; 12?
	jr c,rodante_fin		;97b2
	ld (iy+00fh),000h		;97b4
	ld a,(iy+00eh)		;97b8
	bit 0,a		;97bb   ; a la derecha?
	jp nz,objeto_der		;97bd
	bit 1,a		;97c0   ; a la izquierda?
	jp nz,objeto_izq		;97c2
	bit 2,a		;97c5   ; arriba?
	jp nz,objeto_arriba		;97c7
	bit 3,a		;97ca   ; abajo?
	jp nz,objeto_abajo		;97cc
	set 0,a		;97cf
	ld (iy+00eh),a		;97d1
rodante_fin:
	call toca_prota		;97d4
	call objeto_dentro		;97d7
	ret			;97da
parpadea:		; El tipo 8: dibujo 0xA8, color 15 / 5 parpadeando; cada 16 cuadros cambia de dibujo; a las 0x80 veces, la explosion (el tipo 7)
	inc (iy+00fh)		;97db   ; la cuenta
	ld a,(iy+00fh)		;97de
	cp 010h		;97e1   ; 16?
	jr c,parpadea_fin		;97e3
	ld (iy+00fh),000h		;97e5
	bit 7,(iy+004h)		;97e9
	jr nz,parpadea_va		;97ed
	ld (iy+005h),0a8h		;97ef
	ld (iy+002h),0a8h		;97f3
	ld (iy+003h),00fh		;97f7
	set 7,(iy+004h)		;97fb
parpadea_va:
	call color_parpadea		;97ff   ; el color
	call dibujo_anima_rapido		;9802   ; el dibujo
	inc (iy+00ah)		;9805   ; una vez mas
	ld a,(iy+00ah)		;9808
	cp 080h		;980b   ; 0x80?
	jp c,toca_prota		;980d
	ld (iy+004h),007h		;9810   ; la explosion
parpadea_fin:
	call toca_prota		;9814
	jp objeto_dentro		;9817
recto:		; El tipo 9: dibujo 0xEC; cada 12 cuadros un paso en su direccion (+8, la tabla de 0x98F2) hasta acabar sus pasos (+9); despues, la explosion
	inc (iy+00fh)		;981a   ; la cuenta
	ld a,(iy+00fh)		;981d
	cp 00ch		;9820   ; 12?
	jr c,recto_fin		;9822
	ld (iy+00fh),000h		;9824
	bit 7,(iy+004h)		;9828
	jr nz,recto_va		;982c
	ld (iy+005h),0ech		;982e
	ld (iy+002h),0ech		;9832
	ld (iy+003h),00fh		;9836
	set 7,(iy+004h)		;983a
recto_va:
	call color_parpadea		;983e   ; el color
	call dibujo_anima_rapido		;9841   ; el dibujo
	call paso_dir		;9844   ; un paso
	ld a,(iy+009h)		;9847   ; quedan?
	and a			;984a
	jr nz,recto_fin		;984b
	ld (iy+004h),007h		;984d   ; la explosion
recto_fin:
	call toca_prota		;9851
	jp objeto_dentro		;9854
giros:		; El tipo 10: dibujo 0xE0; cada 8 cuadros un paso; al acabar los pasos, la direccion siguiente (de ocho) y los pasos de su recorrido (0x991F); con 0xFF, la explosion
	inc (iy+00fh)		;9857   ; la cuenta
	ld a,(iy+00fh)		;985a
	cp 008h		;985d   ; 8?
	jr c,giros_fin		;985f
	ld (iy+00fh),000h		;9861
	bit 7,(iy+004h)		;9865
	jr nz,giros_va		;9869
	ld (iy+005h),0e0h		;986b
	ld (iy+002h),0e0h		;986f
	ld (iy+003h),00fh		;9873
	ld (iy+009h),008h		;9877   ; 8 pasos
	set 7,(iy+004h)		;987b
giros_va:
	call color_parpadea		;987f   ; el color
	call dibujo_anima_rapido		;9882   ; el dibujo
	call paso_dir		;9885   ; un paso
	ld a,(iy+009h)		;9888   ; quedan?
	and a			;988b
	jr nz,giros_fin		;988c
	call giros_tramo		;988e   ; los pasos del tramo siguiente
	ld a,(iy+008h)		;9891   ; la direccion siguiente
	inc a			;9894
	and 007h		;9895
	ld (iy+008h),a		;9897
	ld a,(iy+009h)		;989a   ; 0xFF: acabado
	cp 0ffh		;989d
	jr nz,giros_fin		;989f
	ld (iy+004h),007h		;98a1   ; la explosion
giros_fin:
	call toca_prota		;98a5
	jp objeto_dentro		;98a8
explosion:		; El tipo 7: dibujo 0xF8 y cada 16 cuadros el siguiente (+4) hasta 0: fuera
	bit 7,(iy+004h)		;98ab
	jr nz,explosion_va		;98af
	ld (iy+002h),0f8h		;98b1   ; dibujo 0xF8
	ld (iy+00fh),000h		;98b5
	ld (iy+004h),087h		;98b9   ; en marcha
explosion_va:
	ld a,(iy+00fh)		;98bd   ; la cuenta
	inc (iy+00fh)		;98c0
	cp 010h		;98c3   ; 16?
	ret c			;98c5
	ld a,(iy+002h)		;98c6   ; el dibujo siguiente
	add a,004h		;98c9
	ld (iy+002h),a		;98cb
	cp 000h		;98ce   ; 0: fuera
	ret nz			;98d0
	jp objeto_fuera		;98d1
paso_dir:		; Un paso en la direccion +8 (0-7; la tabla de 0x98F2: Y y X) y un paso menos (+9)
	ld a,(iy+008h)		;98d4   ; la direccion x 2
	rlca			;98d7
	ld e,a			;98d8
	ld d,000h		;98d9
	ld hl,098f2h		;98db   ; la tabla
	add hl,de			;98de
	ld a,(hl)			;98df   ; la Y...
	add a,(iy+000h)		;98e0
	ld (iy+000h),a		;98e3
	inc hl			;98e6
	ld a,(hl)			;98e7   ; ...y la X
	add a,(iy+001h)		;98e8
	ld (iy+001h),a		;98eb
	dec (iy+009h)		;98ee   ; un paso menos
	ret			;98f1

; ----------------------------------------------------------------------
; DATOS direcciones: Las ocho direcciones (Y, X)
;   0x98f2..0x9902  (16 bytes)
DATA_direcciones:
	defb 0ffh,000h,0ffh,001h,000h,001h,001h,001h,001h,000h,001h,0ffh,000h,0ffh,0ffh,0ffh	; 98f2  ................

; ======================================================================
; CODIGO 0x9902..0x991f  (29 bytes)
; ======================================================================


giros_tramo:		; Los pasos del tramo siguiente (+0xA) del recorrido +0xB (0x991F)
	inc (iy+00ah)		;9902   ; el tramo siguiente
	ld a,(iy+00bh)		;9905   ; el recorrido
	rlca			;9908
	ld e,a			;9909
	ld d,000h		;990a
	ld hl,0991fh		;990c   ; la tabla
	add hl,de			;990f
	ld e,(hl)			;9910   ; el puntero
	inc hl			;9911
	ld d,(hl)			;9912
	ex de,hl			;9913   ; HL: el recorrido
	ld e,(iy+00ah)		;9914   ; el paso...
	ld d,000h		;9917
	add hl,de			;9919   ; ...+ el recorrido
	ld a,(hl)			;991a   ; los pasos
	ld (iy+009h),a		;991b   ; en la cuenta de pasos
	ret			;991e

; ----------------------------------------------------------------------
; DATOS recorridos: Los recorridos del tipo 10: punteros a listas de pasos
;   (0xFF al final)
;   0x991f..0x9972  (83 bytes)
DATA_recorridos:
	defb 03fh,099h,047h,099h,04fh,099h,04fh,099h,051h,099h,051h,099h,051h,099h,051h,099h	; 991f  ?.G.O.O.Q.Q.Q.Q.
	defb 051h,099h,051h,099h,051h,099h,051h,099h,051h,099h,051h,099h,051h,099h,051h,099h	; 992f  Q.Q.Q.Q.Q.Q.Q.Q.
	defb 010h,012h,014h,018h,01ch,01eh,020h,024h,024h,026h,028h,02ch,02eh,030h,032h,034h	; 993f  ...... $$&(,.024
	defb 0ffh,0ffh,010h,010h,010h,008h,008h,008h,010h,010h,010h,008h,008h,008h,010h,010h	; 994f  ................
	defb 010h,008h,008h,008h,010h,010h,010h,008h,008h,008h,010h,010h,010h,008h,008h,008h	; 995f  ................
	defb 000h,000h,0ffh	; 996f

; ======================================================================
; CODIGO 0x9972..0x99f3  (129 bytes)
; ======================================================================


color_parpadea:		; El color: 5 o 15 cada 4 cuadros (0xE017)
	ld a,(0e017h)		;9972   ; la cuenta de cuadros
	bit 2,a		;9975   ; el bit 2?
	jr z,color_parpadea_15		;9977
	ld a,005h		;9979   ; 5
	jr color_parpadea_pon		;997b
color_parpadea_15:
	ld a,00fh		;997d   ; 15
color_parpadea_pon:
	ld (iy+003h),a		;997f   ; el color
	ret			;9982
dibujo_lado:		; El dibujo (+5, +8 a la izquierda) y el paso (cada 16 cuadros, +4)
	ld a,(iy+005h)		;9983   ; el dibujo
	bit 0,(iy+00eh)		;9986   ; a la derecha?
	jr nz,dibujo_lado_paso		;998a
	add a,008h		;998c   ; a la izquierda, +8
dibujo_lado_paso:
	ld c,a			;998e
	ld a,(0e017h)		;998f   ; la cuenta de cuadros...
	and 010h		;9992   ; ...el bit 4...
	rrca			;9994   ; ...+4
	rrca			;9995
	add a,c			;9996
	ld (iy+002h),a		;9997   ; el dibujo
	ret			;999a
dibujo_anima_rapido:		; El dibujo siguiente cada 4 veces...
	ld b,004h		;999b   ; cada 4
	jr dibujo_anima_va		;999d
dibujo_anima:		; ...o cada 0x28: de +5 a +5 + 12 de cuatro en cuatro
	ld b,028h		;999f   ; cada 0x28
dibujo_anima_va:
	inc (iy+00dh)		;99a1   ; la cuenta
	ld a,(iy+00dh)		;99a4
	cp b			;99a7   ; llego?
	ret c			;99a8
	ld (iy+00dh),000h		;99a9   ; a cero
	ld a,(iy+002h)		;99ad   ; el dibujo...
	cp (iy+005h)		;99b0   ; ...menos que el primero?
	jr nc,dibujo_anima_sigue		;99b3
dibujo_anima_vuelta:
	ld a,(iy+005h)		;99b5   ; el primero
	ld (iy+002h),a		;99b8
	ret			;99bb
dibujo_anima_sigue:
	ld a,(iy+002h)		;99bc   ; el dibujo
	add a,004h		;99bf   ; +4
	ld b,a			;99c1
	ld a,(iy+005h)		;99c2   ; el primero...
	add a,00ch		;99c5   ; ...+12: el ultimo
	cp b			;99c7   ; pasado?
	jr z,dibujo_anima_vuelta		;99c8
	ld (iy+002h),b		;99ca   ; el siguiente
	ret			;99cd
aplastado_objeto:		; Si al objeto le cae una roca encima (las casillas 0x30-0x37 en su cabeza; sin estar mirando), explota (el tipo 7) y da los puntos de su tipo (0x99F3)
	ld a,(0e326h)		;99ce   ; mirando?
	and a			;99d1
	ret nz			;99d2
	call aplastado		;99d3   ; aplastado?
	and a			;99d6
	ret z			;99d7
	pop hl			;99d8   ; sale de la rutina del tipo
	ld a,(iy+004h)		;99d9
	ld (iy+004h),007h		;99dc   ; la explosion
	ld (iy+002h),0f8h		;99e0
	ld e,a			;99e4
	ld d,000h		;99e5
	ld hl,099f3h		;99e7   ; los puntos de su tipo (con el bit 7: 0x9A74 y siguientes)
	add hl,de			;99ea
	ld a,(hl)			;99eb
	ld (0e322h),a		;99ec   ; en los puntos que se suman
	call puntos_suma		;99ef   ; a los puntos
	ret			;99f2

; ----------------------------------------------------------------------
; DATOS objetos_puntos: Los puntos (centenas, BCD) de los tipos 0-5 aplastados
;   por una roca: 500, 300, 300, 100, 100 y 100; pero se leen con el tipo con
;   el bit 7 (0x81-0x8A): salen de 0x9A74-0x9A7D, que es codigo
;   0x99f3..0x99f9  (6 bytes)
DATA_objetos_puntos:
	defb 005h,003h,003h,001h,001h,001h	; 99f3

; ======================================================================
; CODIGO 0x99f9..0x9d42  (841 bytes)
; ======================================================================


toca_prota:		; ¿Toca al protagonista (menos de 8 en Y y en X)? Los tipos 1, 2 y 5: con 0xE30F, uno menos y el objeto fuera (a 0, se borra su dibujo del marcador); los 3 y 6: con 0xE30C, nada; los demas, el protagonista tocado (0xE183 = 0xFF)
	ld ix,0e100h		;99f9   ; el protagonista
	ld a,(ix+000h)		;99fd   ; la distancia en Y
	sub (iy+000h)		;9a00
	jr nc,toca_prota_x		;9a03
	ld a,(iy+000h)		;9a05
	sub (ix+000h)		;9a08
toca_prota_x:
	cp 008h		;9a0b   ; 8?
	ret nc			;9a0d
	ld a,(ix+001h)		;9a0e   ; la distancia en X
	sub (iy+001h)		;9a11
	jr nc,toca_prota_tipo		;9a14
	ld a,(iy+001h)		;9a16
	sub (ix+001h)		;9a19
toca_prota_tipo:
	cp 008h		;9a1c   ; 8?
	ret nc			;9a1e
	ld a,(iy+004h)		;9a1f   ; el tipo
	and 07fh		;9a22
	cp 001h		;9a24
	jr z,toca_prota_escudo		;9a26
	cp 002h		;9a28
	jr z,toca_prota_escudo		;9a2a
	cp 003h		;9a2c
	jr z,toca_prota_otro		;9a2e
	cp 004h		;9a30
	jr z,toca_prota_4		;9a32
	cp 005h		;9a34
	jr z,toca_prota_escudo		;9a36
	cp 006h		;9a38
	jr z,toca_prota_otro		;9a3a
	jr toca_prota_muere		;9a3c
toca_prota_escudo:
	ld a,(0e30fh)		;9a3e   ; 0xE30F?
	and a			;9a41
	jr z,toca_prota_muere		;9a42
	dec a			;9a44   ; uno menos
	ld (0e30fh),a		;9a45   ; en 0xE30F (lo que protege)
	jr nz,toca_prota_fuera		;9a48
	ld hl,0197ah		;9a4a   ; se acabo: su dibujo en el marcador...
	ld a,016h		;9a4d   ; ...se borra (el bloque 0x16)
	call bloque_pinta		;9a4f
	jr toca_prota_fuera		;9a52
toca_prota_otro:
	ld a,(0e30ch)		;9a54   ; 0xE30C?
	and a			;9a57
	ret nz			;9a58
	jr toca_prota_muere		;9a59
toca_prota_4:
	jr toca_prota_muere		;9a5b
toca_prota_fuera:
	ld (iy+004h),007h		;9a5d   ; el objeto explota
	ret			;9a61
toca_prota_muere:
	ld a,0ffh		;9a62   ; tocado
	ld (0e183h),a		;9a64   ; en tocado
	ret			;9a67
objeto_dentro:		; Si el objeto sale de la zona de juego (Y 7-0xA8, X 7-0xB8), fuera
	ld a,(iy+000h)		;9a68   ; la Y...
	cp 0a9h		;9a6b   ; ...desde 0xA9: fuera
	jr nc,objeto_fuera_va		;9a6d
	cp 007h		;9a6f   ; ...antes de 7: fuera
	jr c,objeto_fuera_va		;9a71
	ld a,(iy+001h)		;9a73   ; la X...
	cp 0b9h		;9a76   ; ...desde 0xB9: fuera
	jr nc,objeto_fuera_va		;9a78
	cp 007h		;9a7a   ; ...antes de 7: fuera
	jr c,objeto_fuera_va		;9a7c
	ret			;9a7e   ; dentro
objeto_fuera_va:
	call objeto_fuera		;9a7f   ; fuera: borrado
	ret			;9a82
objeto_fuera:		; Los 16 bytes del objeto IY a cero
	push iy		;9a83
	pop hl			;9a85
	ld b,010h		;9a86
objeto_fuera_byte:
	ld (hl),000h		;9a88
	inc hl			;9a8a
	djnz objeto_fuera_byte		;9a8b   ; B veces
	ret			;9a8d
objeto_der:		; Un paso a la derecha; si choca, ahora a la izquierda
	call der_paso		;9a8e   ; un paso a la derecha
	cp 010h		;9a91   ; sin chocar?
	jp z,toca_prota		;9a93
	res 0,(iy+00eh)		;9a96   ; chocado: a la izquierda
	set 1,(iy+00eh)		;9a9a
	jp toca_prota		;9a9e
objeto_izq:		; Un paso a la izquierda; si choca, ahora a la derecha
	call izq_paso		;9aa1   ; un paso a la izquierda
	cp 010h		;9aa4
	jp z,toca_prota		;9aa6
	res 1,(iy+00eh)		;9aa9   ; chocado: a la derecha
	set 0,(iy+00eh)		;9aad
	jp toca_prota		;9ab1
objeto_arriba:		; Dos puntos arriba; si choca, ahora abajo
	call arriba_paso		;9ab4   ; dos puntos arriba
	call arriba_paso		;9ab7
	cp 010h		;9aba
	jp z,toca_prota		;9abc
	res 2,(iy+00eh)		;9abf   ; chocado: abajo
	set 3,(iy+00eh)		;9ac3
	jp toca_prota		;9ac7
objeto_abajo:		; Dos puntos abajo; si choca, de pie
	call abajo_paso		;9aca   ; dos puntos abajo
	call abajo_paso		;9acd
	cp 010h		;9ad0
	jp z,toca_prota		;9ad2
	res 3,(iy+00eh)		;9ad5   ; en el suelo
	jp toca_prota		;9ad9
prota_mueve_va:		; El protagonista (el boton en 0xE021)
	ld a,(0e021h)		;9adc   ; el boton
	or a			;9adf
	jp prota		;9ae0
vista_baja5:		; La vista baja una fila (16 puntos en 5 pasos con el protagonista) y 0xE308 - 1
	ld b,005h		;9ae3
vista_baja5_paso:
	push bc			;9ae5
	call pantalla_baja_va		;9ae6
	call vista_baja		;9ae9
	call sprites_vram		;9aec
	pop bc			;9aef
	djnz vista_baja5_paso		;9af0   ; B veces
	jr vista_baja5_fin		;9af2
vista_baja5_sin:		; Lo mismo sin el protagonista
	ld b,005h		;9af4
vista_baja5_sin_paso:
	push bc			;9af6
	call pantalla_baja		;9af7
	call sprites_vram		;9afa
	call objetos_baja		;9afd
	pop bc			;9b00
	djnz vista_baja5_sin_paso		;9b01   ; B veces
vista_baja5_fin:
	ld a,(0e308h)		;9b03   ; la vista
	dec a			;9b06
	ld (0e308h),a		;9b07   ; en la vista
	call nada_911f		;9b0a
	ret			;9b0d
vista_sube5:		; La vista sube una fila y 0xE308 + 1
	ld b,005h		;9b0e
vista_sube5_paso:
	push bc			;9b10
	call pantalla_sube_va		;9b11
	call vista_sube		;9b14
	call sprites_vram		;9b17
	pop bc			;9b1a
	djnz vista_sube5_paso		;9b1b   ; B veces
	jr vista_sube5_fin		;9b1d
vista_sube5_sin:
	ld b,005h		;9b1f
vista_sube5_sin_paso:
	push bc			;9b21
	call pantalla_sube		;9b22
	call sprites_vram		;9b25
	call objetos_sube		;9b28
	pop bc			;9b2b
	djnz vista_sube5_sin_paso		;9b2c   ; B veces
vista_sube5_fin:
	ld a,(0e308h)		;9b2e   ; la vista
	inc a			;9b31
	ld (0e308h),a		;9b32   ; en la vista
	call nada_911f		;9b35
	ret			;9b38
objetos_sube:		; Los objetos 0x40 (-0x40) hacia arriba...
	ld de,0ffc0h		;9b39
	call objetos_corre		;9b3c
	ret			;9b3f
objetos_baja:		; Los objetos 0x40 hacia abajo
	ld de,00040h		;9b40   ; +0x40
	call objetos_corre		;9b43
	ret			;9b46
objetos_corre:		; Los 14 objetos de 0xE600 (8 bytes; +0 y +1 su sitio en la RAM) + DE
	ld ix,0e600h		;9b47   ; los objetos de 0xE600
	ld b,00eh		;9b4b   ; 14
objetos_corre_uno:
	ld l,(ix+000h)		;9b4d   ; su sitio...
	ld h,(ix+001h)		;9b50
	add hl,de			;9b53   ; ...+ DE
	ld (ix+000h),l		;9b54   ; apuntado
	ld (ix+001h),h		;9b57
	push de			;9b5a
	ld de,00008h		;9b5b   ; el siguiente (8 bytes)
	add ix,de		;9b5e
	pop de			;9b60
	djnz objetos_corre_uno		;9b61   ; B veces
	ret			;9b63
sprites_bajan:		; Los 7 sprites de 0xE100 que estan (+1, la X) 16 puntos abajo
	ld ix,0e100h		;9b64   ; los sprites
	ld de,00010h		;9b68
	ld b,007h		;9b6b   ; siete
sprites_bajan_uno:
	ld a,(ix+001h)		;9b6d   ; esta?
	and a			;9b70
	jr z,sprites_bajan_sigue		;9b71
	ld a,(ix+000h)		;9b73   ; 16 abajo
	add a,010h		;9b76
	ld (ix+000h),a		;9b78
sprites_bajan_sigue:
	add ix,de		;9b7b   ; el siguiente
	djnz sprites_bajan_uno		;9b7d   ; B veces
	ret			;9b7f
sprites_suben:		; Los 7 sprites que estan 16 puntos arriba
	ld ix,0e100h		;9b80
	ld de,00010h		;9b84
	ld b,007h		;9b87
sprites_suben_uno:
	ld a,(ix+001h)		;9b89   ; esta?
	and a			;9b8c
	jr z,sprites_suben_sigue		;9b8d
	ld a,(ix+000h)		;9b8f   ; 16 arriba
	sub 010h		;9b92
	ld (ix+000h),a		;9b94
sprites_suben_sigue:
	add ix,de		;9b97
	djnz sprites_suben_uno		;9b99   ; B veces
	ret			;9b9b
cosas_mueve:		; Las 16 cosas de 0xE620 (8 bytes) que estan (+6) y se mueven (+5 bit 0): a 0xA4EE
	ld ix,0e620h		;9b9c   ; desde 0xE620
	ld b,010h		;9ba0   ; 16
	ld de,00008h		;9ba2
cosas_mueve_una:
	push ix		;9ba5   ; guardados
	push iy		;9ba7
	push bc			;9ba9
	push de			;9baa
	call cosa_mueve		;9bab   ; una
	pop de			;9bae   ; recuperados
	pop bc			;9baf
	pop iy		;9bb0
	pop ix		;9bb2
	add ix,de		;9bb4   ; la siguiente
	djnz cosas_mueve_una		;9bb6   ; B veces
	ret			;9bb8
cosa_mueve:
	ld a,(ix+006h)		;9bb9   ; esta?
	and a			;9bbc
	ret z			;9bbd
	bit 0,(ix+005h)		;9bbe   ; se mueve?
	ret z			;9bc2
	jp cae_paso		;9bc3
pantalla_baja:		; La zona de juego una fila de bloques abajo: las cosas, los sprites 16 abajo, la pantalla copiada de abajo arriba (RDVRM / WRTVRM) y la fila nueva de arriba desde el mapa (0xE369 - 16)
	call cosas_mueve		;9bc6   ; las cosas
	ld a,008h		;9bc9   ; la fila de los nuevos: arriba
	ex af,af'			;9bcb
	call sprites_bajan		;9bcc   ; los sprites, abajo
pantalla_baja_va:
	ld de,01a81h		;9bcf   ; de la fila 20...
	ld hl,01ac1h		;9bd2   ; ...a la 22
	ld bc,01418h		;9bd5   ; 20 filas de 24
pantalla_baja_casilla:
	ex de,hl			;9bd8
	call 0004ah		;9bd9   ; RDVRM
	ex de,hl			;9bdc
	call 0004dh		;9bdd   ; WRTVRM
	inc hl			;9be0   ; la siguiente
	inc de			;9be1
	dec c			;9be2   ; una menos
	jr nz,pantalla_baja_casilla		;9be3
	ld c,018h		;9be5   ; 24
	push de			;9be7
	ld de,0ffc8h		;9be8   ; una fila arriba (-0x38)
	add hl,de			;9beb
	pop de			;9bec
	push hl			;9bed
	ld hl,0ffc8h		;9bee
	add hl,de			;9bf1
	ex de,hl			;9bf2
	pop hl			;9bf3
	djnz pantalla_baja_casilla		;9bf4   ; B veces
	ld hl,01821h		;9bf6   ; la fila 1...
	call filas_blanco		;9bf9   ; ...en blanco
	ld hl,01821h		;9bfc
	push hl			;9bff
	ld hl,(0e369h)		;9c00   ; el mapa...
	ld de,0fff0h		;9c03   ; ...una fila arriba
	add hl,de			;9c06
	ex de,hl			;9c07
	pop hl			;9c08
	call fila_bloques		;9c09   ; la fila nueva
	ld hl,(0e369h)		;9c0c   ; apuntado
