	ld (0e19dh),a		;9f70   ; el boton sostenido, a 0
	ret			;9f73
prota_golpe:		; El golpe: cada 2 cuadros un dibujo de la tabla de 0xA5F2 (+8 a la izquierda); al acabar, el efecto 3 y lo que haya delante, a la altura de los pies o de la cabeza: si es un bloque (por debajo de 0x38 / 0x3C, leido de la VRAM), se rompe con los que esten unidos a el (0xA040)
	call objeto_quieto		;9f74   ; quieto
	inc (iy+00fh)		;9f77   ; la cuenta
	ld a,(iy+00fh)		;9f7a
	cp 002h		;9f7d   ; 2?
	ret c			;9f7f
	ld (iy+00fh),000h		;9f80   ; a cero
	ld e,(iy+005h)		;9f84   ; el paso...
	inc (iy+005h)		;9f87   ; ...el siguiente
	ld d,000h		;9f8a
	ld hl,0a5f2h		;9f8c   ; la tabla
	add hl,de			;9f8f
	ld a,(hl)			;9f90
	cp 0ffh		;9f91   ; 0xFF: acabado
	jr z,prota_golpe_fin		;9f93
	bit 4,(iy+004h)		;9f95   ; a la izquierda?
	jr z,prota_golpe_dibujo		;9f99
	add a,008h		;9f9b   ; 8 mas
prota_golpe_dibujo:
	ld (iy+002h),a		;9f9d   ; el dibujo
	add a,004h		;9fa0   ; el segundo sprite, 4 mas
	ld (iy+012h),a		;9fa2
	ret			;9fa5
prota_golpe_fin:
	ld a,003h		;9fa6   ; el efecto 3
	call pide_efecto_a		;9fa8
	res 3,(iy+004h)		;9fab   ; ya no golpea
	bit 4,(iy+004h)		;9faf   ; a la izquierda?
	jr z,prota_golpe_der		;9fb3
	ld (iy+002h),010h		;9fb5   ; los dibujos 0x10 y 0x14
	ld (iy+012h),014h		;9fb9
	jr prota_golpe_alcanza		;9fbd
prota_golpe_der:
	ld (iy+002h),000h		;9fbf   ; los dibujos 0 y 4
	ld (iy+012h),004h		;9fc3
prota_golpe_alcanza:
	bit 4,(iy+004h)		;9fc7   ; a la izquierda?
	jr z,prota_golpe_alcanza_der		;9fcb
	ld a,(iy+001h)		;9fcd   ; cerca del borde de la casilla?
	and 00fh		;9fd0
	cp 006h		;9fd2
	jr c,prota_golpe_mira		;9fd4
	ret			;9fd6
prota_golpe_alcanza_der:
	ld a,(iy+001h)		;9fd7
	and 00fh		;9fda
	cp 00bh		;9fdc
	jr nc,prota_golpe_mira		;9fde
	ret			;9fe0
prota_golpe_mira:
	call sitio_vram		;9fe1   ; su sitio en la pantalla
	ld a,(iy+001h)		;9fe4   ; la mitad de la casilla?
	and 00fh		;9fe7
	cp 006h		;9fe9
	jr nc,prota_golpe_lado		;9feb
	inc hl			;9fed
prota_golpe_lado:
	bit 4,(iy+004h)		;9fee   ; a la izquierda?
	jr nz,prota_golpe_izq		;9ff2
	ld a,(iy+000h)		;9ff4   ; la altura en la casilla
	and 007h		;9ff7
	cp 005h		;9ff9
	jr c,prota_golpe_arriba		;9ffb
	ld de,00042h		;9ffd   ; la casilla de delante, abajo
	add hl,de			;a000
	call 0004ah		;a001   ; RDVRM
	cp 038h		;a004   ; un bloque?
	ret nc			;a006
	call rompe		;a007   ; se rompe
	ret			;a00a
prota_golpe_arriba:
	ld de,00022h		;a00b   ; la de delante, arriba
	add hl,de			;a00e
	call 0004ah		;a00f   ; RDVRM
	cp 03ch		;a012   ; un bloque?
	ret nc			;a014
	call rompe		;a015
	ret			;a018
prota_golpe_izq:
	ld a,(iy+000h)		;a019
	and 007h		;a01c
	cp 005h		;a01e
	jr c,prota_golpe_izq_arriba		;a020
	ld de,0003fh		;a022   ; la de delante, abajo
	add hl,de			;a025
	call 0004ah		;a026   ; RDVRM
	cp 03ch		;a029   ; un bloque?
	ret nc			;a02b
	dec hl			;a02c
	call rompe		;a02d
	ret			;a030
prota_golpe_izq_arriba:
	ld de,0001fh		;a031   ; la de delante, arriba
	add hl,de			;a034
	call 0004ah		;a035   ; RDVRM
	cp 03ch		;a038   ; un bloque?
	ret nc			;a03a
	dec hl			;a03b
	call rompe		;a03c
	ret			;a03f
rompe:		; Rompe el bloque de HL y los que esten unidos a el (siguiendo sus uniones: arriba, abajo, izquierda y derecha, segun su forma) y los quita del mapa (0xA22D)
	call pantalla_a_mapa		;a040   ; en el mapa
	call rompe_arriba		;a043   ; sigue las uniones
	push af			;a046
	pop af			;a047
	jp rompe_quita		;a048   ; los quita
rompe_arriba:		; Sigue hacia arriba mientras la forma lo una
	ld a,(hl)			;a04b   ; el bloque
	bit 7,a		;a04c   ; con el bit 7: el final
	jp nz,rompe_fin		;a04e
	call unido_arriba		;a051   ; unido arriba?
	jr z,rompe_sube		;a054
	call unido_izq		;a056   ; unido a la izquierda?
	jr z,rompe_izq		;a059
	call unido_der		;a05b   ; unido a la derecha?
	jr z,rompe_der		;a05e
	call unido_abajo		;a060   ; unido abajo?
	jr z,rompe_abajo		;a063
	jp rompe_fin		;a065
rompe_sube:
	ld de,0fff0h		;a068   ; una fila arriba
	add hl,de			;a06b
	jr rompe_arriba		;a06c
rompe_abajo:
	ld a,(hl)			;a06e   ; el bloque
	bit 7,a		;a06f   ; una cosa?
	jp nz,rompe_fin		;a071   ; acabado
	call unido_abajo		;a074   ; unido por abajo?
	jr z,rompe_baja		;a077
	call unido_izq		;a079   ; por la izquierda?
	jr z,rompe_izq		;a07c
	call unido_der		;a07e   ; por la derecha?
	jr z,rompe_der		;a081
	call unido_arriba		;a083   ; por arriba?
	jr z,rompe_arriba		;a086
	jp rompe_fin		;a088   ; acabado
rompe_baja:
	ld de,00010h		;a08b   ; una fila abajo
	add hl,de			;a08e
	jr rompe_abajo		;a08f
rompe_izq:
	ld a,(hl)			;a091   ; el bloque
	bit 7,a		;a092   ; una cosa?
	jr nz,rompe_fin		;a094   ; acabado
	call unido_izq		;a096   ; unido por la izquierda?
	jr z,rompe_izq_paso		;a099
	call unido_arriba		;a09b   ; por arriba?
	jr z,rompe_arriba		;a09e
	call unido_abajo		;a0a0   ; por abajo?
	jr z,rompe_abajo		;a0a3
	call unido_der		;a0a5   ; por la derecha?
	jr z,rompe_der		;a0a8
	jp rompe_fin		;a0aa   ; acabado
rompe_izq_paso:
	dec hl			;a0ad   ; a la izquierda
	jr rompe_izq		;a0ae
rompe_der:
	ld a,(hl)			;a0b0
	bit 7,a		;a0b1
	jr nz,rompe_fin		;a0b3
	call unido_der		;a0b5
	jr z,rompe_der_paso		;a0b8
	call unido_arriba		;a0ba
	jr z,rompe_arriba		;a0bd
	call unido_abajo		;a0bf
	jr z,rompe_abajo		;a0c2   ; abajo
	call unido_izq		;a0c4   ; a la izquierda?
	jr z,rompe_izq		;a0c7   ; tambien
	jp rompe_fin		;a0c9   ; ya no
rompe_der_paso:
	inc hl			;a0cc   ; a la derecha
	jr rompe_der		;a0cd
unido_arriba:		; Z si la forma (1, 4, 5 u 11) se une por arriba
	cp 004h		;a0cf   ; 4?
	ret z			;a0d1
	cp 005h		;a0d2   ; 5?
	ret z			;a0d4
	cp 001h		;a0d5   ; 1?
	ret z			;a0d7
	cp 00bh		;a0d8   ; 11?
	ret			;a0da
unido_abajo:		; Z si la forma (2, 8, 10 u 11) se une por abajo
	cp 002h		;a0db   ; 2?
	ret z			;a0dd
	cp 008h		;a0de   ; 8?
	ret z			;a0e0
	cp 00ah		;a0e1   ; 10?
	ret z			;a0e3
	cp 00bh		;a0e4   ; 11?
	ret			;a0e6
unido_izq:		; Z si la forma (1, 2, 3 o 6) se une por la izquierda
	cp 001h		;a0e7   ; 1?
	ret z			;a0e9
	cp 002h		;a0ea   ; 2?
	ret z			;a0ec
	cp 003h		;a0ed   ; 3?
	ret z			;a0ef
	cp 006h		;a0f0   ; 6?
	ret			;a0f2
unido_der:		; Z si la forma (4, 8, 12 o 6) se une por la derecha
	cp 004h		;a0f3   ; 4?
	ret z			;a0f5
	cp 008h		;a0f6   ; 8?
	ret z			;a0f8
	cp 00ch		;a0f9   ; 12?
	ret z			;a0fb
	cp 006h		;a0fc   ; 6?
	ret			;a0fe
rompe_fin:
	call mapa_a_pantalla		;a0ff   ; su sitio en la pantalla
	ld (0e300h),hl		;a102   ; en 0xE300
	ret			;a105
mapa_a_pantalla:		; El sitio en la tabla de nombres del bloque HL del mapa, segun la vista
	push de			;a106   ; guardados
	push bc			;a107
	push af			;a108
	ld (0e30ah),hl		;a109   ; el bloque, guardado
	ld a,(0e308h)		;a10c   ; la vista
	rlca			;a10f   ; la vista x 2
	ld e,a			;a110
	ld d,000h		;a111   ; D = 0
	ld hl,0a14bh		;a113   ; la tabla de 0xA14B
	add hl,de			;a116   ; + la vista x 2
	ld e,(hl)			;a117   ; su puntero
	inc hl			;a118
	ld d,(hl)			;a119
	ex de,hl			;a11a   ; HL: la entrada
	ld e,(hl)			;a11b   ; el sitio de la pantalla...
	inc hl			;a11c
	ld d,(hl)			;a11d
	push de			;a11e   ; (la pantalla)
	inc hl			;a11f
	ld e,(hl)			;a120   ; ...y el del mapa
	inc hl			;a121
	ld d,(hl)			;a122
	ld hl,(0e30ah)		;a123   ; el bloque...
	xor a			;a126
	sbc hl,de		;a127   ; ...menos el principio del mapa
	rlc h		;a129   ; la fila alta x 4...
	rlc h		;a12b
	ld a,l			;a12d   ; la fila (x 64)...
	and 0c0h		;a12e
	rlc a		;a130   ; ...la fila de 64 en 64...
	rlc a		;a132
	add a,h			;a134   ; ...en H
	ld h,a			;a135
	ld a,l			;a136
	and 030h		;a137   ; ...la columna (x 2)
	rlc a		;a139
	rlc a		;a13b
	ld b,a			;a13d   ; (x 4)
	ld a,l			;a13e   ; la columna baja...
	and 00fh		;a13f
	rlc a		;a141   ; ...x 2
	add a,b			;a143   ; sumadas: L
	ld l,a			;a144
	pop de			;a145
	add hl,de			;a146   ; + la pantalla
	pop af			;a147   ; recuperados
	pop bc			;a148
	pop de			;a149
	ret			;a14a   ; HL: el sitio en la VRAM

; ----------------------------------------------------------------------
; DATOS vistas: Para cada vista (0xE308): un puntero a dos direcciones, la de
;   la pantalla y la del mapa
;   0xa14b..0xa1db  (144 bytes)
DATA_vistas:
	defb 07bh,0a1h,07fh,0a1h,083h,0a1h,087h,0a1h,08bh,0a1h,08fh,0a1h,093h,0a1h,097h,0a1h	; a14b  {...............
	defb 09bh,0a1h,09fh,0a1h,0a3h,0a1h,0a7h,0a1h,0abh,0a1h,0afh,0a1h,0b3h,0a1h,0b7h,0a1h	; a15b  ................
	defb 0bbh,0a1h,0bfh,0a1h,0c3h,0a1h,0c7h,0a1h,0cbh,0a1h,0cfh,0a1h,0d3h,0a1h,0d7h,0a1h	; a16b  ................
	defb 021h,018h,000h,0e8h,0e1h,016h,000h,0e8h,0a1h,015h,000h,0e8h,061h,014h,000h,0e8h	; a17b  !...........a...
	defb 021h,013h,000h,0e8h,0e1h,011h,000h,0e8h,0a1h,010h,000h,0e8h,061h,00fh,000h,0e8h	; a18b  !...........a...
	defb 021h,00eh,000h,0e8h,0e1h,00ch,000h,0e8h,0a1h,00bh,000h,0e8h,061h,00ah,000h,0e8h	; a19b  !...........a...
	defb 021h,009h,000h,0e8h,0e1h,007h,000h,0e8h,0a1h,006h,000h,0e8h,061h,005h,000h,0e8h	; a1ab  !...........a...
	defb 021h,004h,000h,0e8h,0e1h,002h,000h,0e8h,0a1h,001h,000h,0e8h,061h,000h,000h,0e8h	; a1bb  !...........a...
	defb 061h,000h,050h,0e8h,061h,000h,0a0h,0e8h,061h,000h,0f0h,0e8h,061h,000h,040h,0e9h	; a1cb  a.P.a...a...a.@.

