; CODIGO 0xa1db..0xa347  (364 bytes)
; ======================================================================


pantalla_a_mapa:		; Al reves: el bloque del mapa (0xE800...) que hay en el sitio HL de la tabla de nombres, segun la vista
	push de			;a1db   ; guardados
	push bc			;a1dc
	push af			;a1dd
	ld (0e30ah),hl		;a1de   ; el sitio, guardado
	ld a,(0e308h)		;a1e1   ; la vista
	rlca			;a1e4   ; la vista x 2
	ld e,a			;a1e5
	ld d,000h		;a1e6   ; D = 0
	ld hl,0a14bh		;a1e8   ; la tabla de 0xA14B
	add hl,de			;a1eb   ; + la vista x 2
	ld e,(hl)			;a1ec   ; su puntero
	inc hl			;a1ed
	ld d,(hl)			;a1ee
	ex de,hl			;a1ef   ; HL: la entrada
	ld e,(hl)			;a1f0   ; el sitio de la pantalla
	inc hl			;a1f1
	ld d,(hl)			;a1f2
	push de			;a1f3
	inc hl			;a1f4
	ld e,(hl)			;a1f5   ; el del mapa
	inc hl			;a1f6
	ld d,(hl)			;a1f7
	ld hl,(0e30ah)		;a1f8   ; el sitio
	ld (0e30ah),de		;a1fb   ; el principio del mapa
	pop de			;a1ff
	xor a			;a200
	sbc hl,de		;a201   ; menos el de la pantalla
	ld a,l			;a203   ; la columna (/ 2)
	and 01eh		;a204
	rrc a		;a206   ; (/ 2)
	ld c,a			;a208
	ld b,000h		;a209   ; BC: la columna
	ld a,l			;a20b   ; la fila (/ 64, x 16)
	and 0c0h		;a20c
	rrc a		;a20e   ; (/ 4)
	rrc a		;a210
	ld e,a			;a212
	ld a,h			;a213   ; la parte alta...
	and 003h		;a214   ; ...de la fila
	rrc a		;a216
	rrc a		;a218
	add a,e			;a21a
	ld e,a			;a21b   ; E: la fila baja
	ld a,h			;a21c   ; la fila alta
	and 0fch		;a21d
	rrc a		;a21f
	rrc a		;a221
	ld d,a			;a223   ; D
	ld hl,(0e30ah)		;a224   ; + el mapa
	add hl,de			;a227
	add hl,bc			;a228   ; + la columna
	pop af			;a229   ; recuperados
	pop bc			;a22a
	pop de			;a22b
	ret			;a22c   ; HL: el bloque del mapa
rompe_quita:		; Quita del mapa el bloque roto (salvo 0xDC): si ya esta en la lista de los que se rompen (0xE600, 4), nada; si no, en un hueco libre: el efecto 2, su forma (+6), su sitio en el mapa (+0, +1) y en la pantalla (+2, +3) y los pasos a 0
	cp 0dch		;a22d   ; 0xDC: no se rompe
	ret z			;a22f
	push af			;a230   ; guardado
	ld ix,0e600h		;a231   ; la lista de 0xE600
	ld de,00008h		;a235   ; de 8 en 8
	ld b,004h		;a238   ; cuatro
rompe_quita_mira:
	ld a,(ix+006h)		;a23a   ; en uso?
	and a			;a23d
	jr z,rompe_quita_sigue		;a23e
	ld a,l			;a240   ; el mismo sitio?
	cp (ix+000h)		;a241
	jr nz,rompe_quita_sigue		;a244
	ld a,h			;a246
	cp (ix+001h)		;a247
	jr nz,rompe_quita_sigue		;a24a
	jr rompe_quita_ya		;a24c   ; ya esta
rompe_quita_sigue:
	add ix,de		;a24e
	djnz rompe_quita_mira		;a250   ; B veces
	jr rompe_quita_nuevo		;a252
rompe_quita_ya:
	pop af			;a254
	ret			;a255
rompe_quita_nuevo:
	call hueco_e600		;a256   ; un hueco libre
	pop af			;a259
	push af			;a25a
	and a			;a25b   ; con forma?
	jr z,rompe_quita_pon		;a25c
	ld a,002h		;a25e   ; el efecto 2
	call pide_efecto_a		;a260
rompe_quita_pon:
	pop af			;a263
	ld (ix+006h),a		;a264   ; su forma
	ld (ix+000h),l		;a267   ; su sitio en el mapa
	ld (ix+001h),h		;a26a
	call pantalla_a_mapa		;a26d   ; en la pantalla
	ld (ix+002h),l		;a270
	ld (ix+003h),h		;a273
	ld (ix+004h),000h		;a276   ; los pasos a 0
	ld (ix+005h),000h		;a27a
	ret			;a27e
rompe_quita2:		; Lo mismo con la otra lista (0xE620, 10)
	push ix		;a27f
	ld ix,0e620h		;a281
	ld b,00ah		;a285
rompe_quita2_mira:
	ld a,(ix+000h)		;a287   ; el mismo sitio?
	cp l			;a28a
	jr nz,rompe_quita2_sigue		;a28b
	ld a,(ix+001h)		;a28d   ; (el byte alto)
	cp h			;a290
	jr nz,rompe_quita2_sigue		;a291
	pop ix		;a293   ; ya esta: recuperados
	pop af			;a295
	ret			;a296
rompe_quita2_sigue:
	push de			;a297
	ld de,00008h		;a298   ; de 8 en 8
	add ix,de		;a29b
	pop de			;a29d
	djnz rompe_quita2_mira		;a29e   ; B veces
	pop ix		;a2a0
	jr rompe_quita_pon		;a2a2
rompe_quita2_va:
	cp 0dch		;a2a4
	ret z			;a2a6
	push af			;a2a7
	call hueco_e620		;a2a8
	jr rompe_quita2		;a2ab
hueco_e600:		; Un hueco libre en la lista de 0xE600 (6)
	ld ix,0e600h		;a2ad
	ld b,006h		;a2b1
hueco_busca:
	ld de,00008h		;a2b3
hueco_mira:
	ld a,(ix+006h)		;a2b6   ; libre?
	or a			;a2b9
	ret z			;a2ba
	add ix,de		;a2bb   ; el siguiente
	djnz hueco_mira		;a2bd   ; B veces
	ret			;a2bf
hueco_e620:		; Un hueco libre en la lista de 0xE620 (10)
	ld ix,0e620h		;a2c0
	ld b,00ah		;a2c4
	jr hueco_busca		;a2c6
rotos:		; Los cuatro bloques que se estan rompiendo (0xE600, 8 bytes): cada 16 cuadros un paso
	ld ix,0e600h		;a2c8   ; la lista
	ld b,004h		;a2cc   ; cuatro
	ld de,00008h		;a2ce
rotos_uno:
	push bc			;a2d1
	push de			;a2d2
	call roto		;a2d3
	pop de			;a2d6
	pop bc			;a2d7
	add ix,de		;a2d8
	djnz rotos_uno		;a2da   ; B veces
	ret			;a2dc
roto:		; Un bloque rompiendose: cada 16 cuadros el dibujo siguiente (la tabla de 0xA347) en todas sus casillas; al acabar (0xFF), sus puntos, y si era una de las formas 0xE0-0xEC se convierte en la siguiente; si no, se borra y lo de encima cae
	ld a,(ix+006h)		;a2dd   ; en uso?
	cp 000h		;a2e0
	ret z			;a2e2
	inc (ix+004h)		;a2e3   ; la cuenta
	ld a,(ix+004h)		;a2e6
	cp 010h		;a2e9   ; 16?
	ret c			;a2eb
	ld (ix+004h),000h		;a2ec   ; a cero
	ld e,(ix+005h)		;a2f0   ; el paso...
	inc (ix+005h)		;a2f3   ; ...el siguiente
	ld d,000h		;a2f6
	ld hl,0a347h		;a2f8   ; la tabla
	add hl,de			;a2fb
	ld a,(hl)			;a2fc   ; el dibujo
	ld (0e302h),a		;a2fd
	cp 0ffh		;a300   ; 0xFF: acabado
	jr z,$+74		;a302
	ld l,(ix+000h)		;a304   ; su sitio
	ld h,(ix+001h)		;a307
roto_pinta:		; El dibujo (0xE302) en el bloque y en las demas casillas de su pieza (0x8F02)
	ld (0e302h),a		;a30a   ; el dibujo
	call bloque_pinta		;a30d   ; en el bloque
	ld a,(ix+006h)		;a310   ; su pieza
	and 07ch		;a313
	rrc a		;a315
	ld e,a			;a317
	ld d,000h		;a318
	ld hl,08f02h		;a31a   ; la tabla de 0x8F02
	add hl,de			;a31d
	ld e,(hl)			;a31e
	inc hl			;a31f
	ld d,(hl)			;a320
	inc de			;a321
	ld l,(ix+002h)		;a322   ; su sitio en el mapa
	ld h,(ix+003h)		;a325
roto_pinta_uno:
	ld a,(de)			;a328   ; 0x7F: el final
	cp 07fh		;a329
	jr z,roto_pinta_fin		;a32b
	ld c,a			;a32d   ; el salto
	ld b,000h		;a32e
	bit 7,a		;a330
	jr z,roto_pinta_salto		;a332
	ld b,0ffh		;a334
roto_pinta_salto:
	add hl,bc			;a336   ; la casilla siguiente
	push hl			;a337
	call mapa_a_pantalla		;a338   ; en la pantalla
	ld a,(0e302h)		;a33b
	call bloque_pinta		;a33e   ; pintada
	pop hl			;a341
	inc de			;a342
	inc de			;a343
	jr roto_pinta_uno		;a344
roto_pinta_fin:
	ret			;a346

; ----------------------------------------------------------------------
; DATOS roto_dibujos: Los dibujos de un bloque rompiendose (0xFF al final)
;   0xa347..0xa34c  (5 bytes)
DATA_roto_dibujos:
	defb 012h,013h,014h,015h,0ffh	; a347

; ======================================================================
; CODIGO 0xa34c..0xa5f2  (678 bytes)
; ======================================================================


roto_fin:		; El bloque roto: 20 puntos (0x20 en BCD); las formas 0xE0-0xEC pasan a la siguiente (+0x10); las demas se borran (el bloque 0x16) y caen las que tenia encima (0x8F42)
	ld a,020h		;a34c   ; 20 puntos
	ld (0e321h),a		;a34e
	call puntos_suma		;a351   ; a los puntos
	ld a,(ix+006h)		;a354   ; su forma
	cp 0e0h		;a357
	jr z,roto_cambia		;a359
	cp 0e4h		;a35b
	jr z,roto_cambia		;a35d
	cp 0e8h		;a35f
	jr z,roto_cambia		;a361
	cp 0ech		;a363
	jr z,roto_cambia		;a365
	jr roto_borra		;a367
roto_cambia:
	ld l,(ix+002h)		;a369   ; su sitio en el mapa
	ld h,(ix+003h)		;a36c
	add a,010h		;a36f   ; la forma siguiente
	ld (hl),a			;a371
	ld l,(ix+000h)		;a372
	ld h,(ix+001h)		;a375
	set 7,a		;a378   ; pintada
	call bloque_pinta		;a37a
	push ix		;a37d
	call rompe_quita2_va		;a37f   ; a la otra lista
	pop ix		;a382
	ld l,(ix+002h)		;a384
	ld h,(ix+003h)		;a387
	ld (0e304h),hl		;a38a
	jr roto_encima		;a38d
roto_borra:
	ld l,(ix+002h)		;a38f
	ld h,(ix+003h)		;a392
	ld (0e304h),hl		;a395
	ld a,016h		;a398   ; el bloque 0x16 (vacio)
	ld (0e302h),a		;a39a
	ld l,(ix+000h)		;a39d
	ld h,(ix+001h)		;a3a0
	call roto_pinta		;a3a3   ; pintado
	call pieza_quita		;a3a6   ; fuera del mapa
roto_encima:
	ld iy,0e100h		;a3a9
	call prota_suelo		;a3ad   ; el protagonista
	ld a,(ix+006h)		;a3b0
	push af			;a3b3
	ld (ix+006h),000h		;a3b4   ; libre
	call hueco_e620		;a3b8   ; un hueco
	pop af			;a3bb
roto_encima_lista:
	and 07ch		;a3bc   ; su forma
	rrca			;a3be
	ld e,a			;a3bf
	ld d,000h		;a3c0
	ld hl,08f42h		;a3c2   ; la lista de lo que tiene encima (0x8F42)
	add hl,de			;a3c5
	ld e,(hl)			;a3c6
	inc hl			;a3c7
	ld d,(hl)			;a3c8
	ld (0e306h),de		;a3c9
roto_encima_uno:
	ld hl,(0e304h)		;a3cd
	ld de,(0e306h)		;a3d0
	ex de,hl			;a3d4
	ld e,(hl)			;a3d5   ; el salto
	ld d,000h		;a3d6
	inc hl			;a3d8
	ld (0e306h),hl		;a3d9
	ld a,e			;a3dc
	cp 07fh		;a3dd   ; 0x7F: el final
	ret z			;a3df
	bit 7,e		;a3e0
	jr z,roto_encima_mira		;a3e2
	ld d,0ffh		;a3e4
roto_encima_mira:
	ld hl,(0e304h)		;a3e6
	add hl,de			;a3e9
	ld (0e304h),hl		;a3ea
	ld a,(hl)			;a3ed   ; algo?
	cp 000h		;a3ee
	jr z,roto_encima_uno		;a3f0
	call rompe_arriba		;a3f2   ; se rompe tambien
	call rompe_quita2_va		;a3f5   ; a la otra lista
	jr roto_encima_uno		;a3f8
pieza_quita:		; Quita del mapa (a 0) todas las casillas de la pieza del bloque
	ld l,(ix+002h)		;a3fa
	ld h,(ix+003h)		;a3fd
	ld a,(hl)			;a400   ; sigue ahi?
	cp (ix+006h)		;a401
	ret nz			;a404
	ld a,(ix+006h)		;a405   ; su forma
	and 07ch		;a408
	rrca			;a40a
	rrca			;a40b
	push hl			;a40c
	rl a		;a40d
	ld e,a			;a40f
	ld d,000h		;a410
	ld hl,08f02h		;a412   ; la tabla de 0x8F02
	add hl,de			;a415
	ld e,(hl)			;a416
	inc hl			;a417
	ld d,(hl)			;a418
	pop hl			;a419
	ld (hl),000h		;a41a   ; a 0
pieza_quita_uno:
	inc de			;a41c
	ld a,(de)			;a41d   ; el salto
	cp 07fh		;a41e   ; 0x7F: el final
	ret z			;a420
	push de			;a421
	ld d,000h		;a422
	bit 7,a		;a424
	jr z,pieza_quita_salto		;a426
	ld d,0ffh		;a428
pieza_quita_salto:
	ld e,a			;a42a
	add hl,de			;a42b
	pop de			;a42c
	ld (hl),000h		;a42d   ; a 0
	inc de			;a42f
	jr pieza_quita_uno		;a430
caen:		; Cada 3 cuadros, las 16 piezas de 0xE620 (8 bytes) que caen
	ld a,(0e013h)		;a432   ; la cuenta de cuadros
	cp 003h		;a435   ; 3?
	ret c			;a437
	xor a			;a438
	ld (0e013h),a		;a439   ; en la cuenta de cuadros
	ld ix,0e620h		;a43c   ; la lista
	ld b,010h		;a440   ; 16
	ld de,00008h		;a442
caen_una:
	push ix		;a445
	push bc			;a447
	push de			;a448
	call cae		;a449
	pop de			;a44c
	pop bc			;a44d
	pop ix		;a44e
	add ix,de		;a450
	djnz caen_una		;a452   ; B veces
	ret			;a454
cae:		; Una pieza: si ya cae (+5 bit 0), sigue (0xA4EE); si no, mira lo de debajo (0x8F82): si hay algo (menos de 0x70) que la sostiene, se queda; si no, empieza a caer
	ld a,(ix+006h)		;a455   ; en uso?
	and a			;a458
	ret z			;a459
	bit 0,(ix+005h)		;a45a   ; cayendo?
	jr z,cae_mira		;a45e
	jp cae_paso		;a460
cae_mira:
	push iy		;a463
	ld iy,0e100h		;a465   ; el protagonista
	call prota_suelo		;a469
	pop iy		;a46c
	inc (ix+005h)		;a46e   ; un paso mas
	ld a,(ix+006h)		;a471   ; su forma
	and 07ch		;a474
	rrca			;a476
	rrca			;a477
	ld hl,08f82h		;a478   ; lo de debajo (0x8F82)
	rlca			;a47b
	ld e,a			;a47c
	ld d,000h		;a47d
	add hl,de			;a47f
	ld e,(hl)			;a480
	inc hl			;a481
	ld d,(hl)			;a482
	push de			;a483
	pop iy		;a484
	ld l,(ix+002h)		;a486
	ld h,(ix+003h)		;a489
cae_mira_uno:
	ld a,(iy+000h)		;a48c   ; 0x7F: el final
	cp 07fh		;a48f
	jr z,cae_empieza		;a491
	ld e,a			;a493
	ld d,000h		;a494
	bit 7,(iy+000h)		;a496
	jr z,cae_mira_casilla		;a49a
	ld d,0ffh		;a49c
cae_mira_casilla:
	add hl,de			;a49e
	ld a,(hl)			;a49f   ; algo?
	cp 000h		;a4a0
	jr nz,cae_sostiene		;a4a2
cae_mira_sigue:
	inc iy		;a4a4
	jr cae_mira_uno		;a4a6
cae_sostiene:
	and 07ch		;a4a8
	cp 070h		;a4aa   ; desde 0x70: no sostiene
	jr nc,cae_mira_sigue		;a4ac
	push ix		;a4ae   ; la pieza se queda: fuera de la lista
	pop hl			;a4b0
	ld b,008h		;a4b1
	xor a			;a4b3
cae_sostiene_borra:
	ld (hl),a			;a4b4
	inc hl			;a4b5
	djnz cae_sostiene_borra		;a4b6   ; B veces
	ret			;a4b8
cae_empieza:
	push iy		;a4b9
	ld iy,0e100h		;a4bb
	call prota_suelo		;a4bf
	pop iy		;a4c2
	ld l,(ix+000h)		;a4c4   ; su sitio
	ld h,(ix+001h)		;a4c7
	ld a,(ix+006h)		;a4ca   ; su forma
	and 07ch		;a4cd
	cp 070h		;a4cf   ; 0x70 o mas?
	jr c,cae_empieza_borra		;a4d1
	call bloque_borra		;a4d3   ; otra
	jr cae_empieza_va		;a4d6
cae_empieza_borra:
	ld a,016h		;a4d8   ; el bloque vacio
	call roto_pinta		;a4da
cae_empieza_va:
	ld l,(ix+000h)		;a4dd
	ld h,(ix+001h)		;a4e0
	ld de,00020h		;a4e3   ; una fila abajo
	add hl,de			;a4e6
	call pieza_forma		;a4e7
	call pieza_pinta		;a4ea
	ret			;a4ed
cae_paso:		; Un paso de la pieza que cae: se borra donde estaba, baja una fila en el mapa (+16) y se pinta abajo; lo que tenia encima cae con ella
	inc (ix+005h)		;a4ee   ; un paso mas
	ld l,(ix+000h)		;a4f1   ; su sitio
	ld h,(ix+001h)		;a4f4
	ld de,00020h		;a4f7   ; la fila de abajo
	add hl,de			;a4fa
	ld a,(ix+006h)		;a4fb   ; su forma
	and 07ch		;a4fe
	cp 070h		;a500   ; 0x70 o mas?
	jr c,cae_paso_borra		;a502
	call bloque_borra		;a504
	jr cae_paso_va		;a507
cae_paso_borra:
	ld a,016h		;a509   ; el bloque vacio
	call roto_pinta		;a50b
cae_paso_va:
	ld l,(ix+000h)		;a50e
	ld h,(ix+001h)		;a511
	ld de,00040h		;a514   ; dos filas abajo
	add hl,de			;a517
	call pieza_forma		;a518
	call pieza_pinta		;a51b
	call pieza_quita		;a51e   ; fuera del mapa
	ld l,(ix+002h)		;a521   ; su sitio en el mapa
	ld h,(ix+003h)		;a524
	ld (0e304h),hl		;a527
	ld de,00010h		;a52a   ; una fila mas abajo
	add hl,de			;a52d
	ld (ix+002h),l		;a52e
	ld (ix+003h),h		;a531
	call mapa_a_pantalla		;a534   ; en la pantalla
	ld (ix+000h),l		;a537
	ld (ix+001h),h		;a53a
	ld a,(ix+006h)		;a53d   ; su forma
	ld l,(ix+002h)		;a540
	ld h,(ix+003h)		;a543
	and 07ch		;a546
	rrc a		;a548
	rrc a		;a54a
	call pieza_pon		;a54c   ; en el mapa
	ld a,(ix+006h)		;a54f   ; lo de encima
	jp roto_encima_lista		;a552
bloque_borra:		; Borra las cuatro casillas del bloque A en HL si siguen siendo las suyas (las pone a 0x10)
	rrca			;a555
	rrca			;a556
	push hl			;a557
	push de			;a558
	call bloque_casillas		;a559   ; sus casillas
	ld a,(de)			;a55c   ; arriba a la izquierda
	call casilla_borra		;a55d
	inc hl			;a560
	inc de			;a561
	ld a,(de)			;a562   ; arriba a la derecha
	call casilla_borra		;a563
	push de			;a566
	ld de,0001fh		;a567   ; la fila de abajo
	add hl,de			;a56a
	pop de			;a56b
	inc de			;a56c
	ld a,(de)			;a56d   ; abajo a la izquierda
	call casilla_borra		;a56e
	inc de			;a571
	inc hl			;a572
	ld a,(de)			;a573   ; abajo a la derecha
	call casilla_borra		;a574
	pop de			;a577
	pop hl			;a578
	ret			;a579
casilla_borra:		; Una casilla a 0x10 si en la VRAM sigue la de A (dentro de la zona de juego)
	push af			;a57a
	ld a,h			;a57b   ; la fila
	cp 018h		;a57c
	jr c,casilla_borra_no		;a57e
	jr z,casilla_borra_18		;a580
	cp 01ah		;a582
	jr c,casilla_borra_va		;a584
	ld a,l			;a586
	cp 0e0h		;a587
	jr nc,casilla_borra_no		;a589
casilla_borra_va:
	call 0004ah		;a58b   ; RDVRM
	ld b,a			;a58e
	pop af			;a58f
	cp b			;a590   ; la misma?
	ret nz			;a591
	ld a,010h		;a592   ; el espacio
	call 0004dh		;a594   ; WRTVRM
	ret			;a597
casilla_borra_18:
	ld a,l			;a598
	cp 021h		;a599
	jr nc,casilla_borra_va		;a59b
casilla_borra_no:
	pop af			;a59d
	ret			;a59e
pieza_forma:		; La forma de la pieza (+6) / 4
	ld a,(ix+006h)		;a59f
	and 07ch		;a5a2
	rrca			;a5a4
	rrca			;a5a5
	ret			;a5a6
pieza_pinta:		; La pieza A en la pantalla (HL): bloque a bloque, segun la tabla de 0x8F02
	ld de,00000h		;a5a7   ; la fila: par...
	bit 5,l		;a5aa
	jr nz,pieza_pinta_va		;a5ac
	ld de,00020h		;a5ae   ; ...o impar
pieza_pinta_va:
	ld (0e311h),de		;a5b1   ; guardado
	push hl			;a5b5
	ld hl,08f02h		;a5b6   ; la tabla
	rlca			;a5b9   ; la pieza x 2
	ld e,a			;a5ba
	ld d,000h		;a5bb   ; D = 0
	add hl,de			;a5bd   ; + la tabla
	ld e,(hl)			;a5be   ; su puntero
	inc hl			;a5bf
	ld d,(hl)			;a5c0
	pop hl			;a5c1
	push de			;a5c2   ; en IY
	pop iy		;a5c3
	jr pieza_pinta_bloque		;a5c5   ; al bloque
pieza_pinta_salto:
	ld de,(0e311h)		;a5c7
	add hl,de			;a5cb
pieza_pinta_bloque:
	ld a,(iy+000h)		;a5cc   ; el bloque
	call bloque_pinta		;a5cf   ; pintado
	inc iy		;a5d2
	ld a,(iy+000h)		;a5d4   ; el salto
	cp 07fh		;a5d7   ; 0x7F: el final
	ret z			;a5d9
	push af			;a5da
	call pantalla_a_mapa		;a5db   ; en el mapa
	pop af			;a5de
	ld e,a			;a5df
	ld d,000h		;a5e0
	bit 7,(iy+000h)		;a5e2
	jr z,pieza_pinta_sigue		;a5e6
	ld d,0ffh		;a5e8
pieza_pinta_sigue:
	add hl,de			;a5ea
	inc iy		;a5eb
	call mapa_a_pantalla		;a5ed
	jr pieza_pinta_salto		;a5f0

; ----------------------------------------------------------------------
; DATOS golpe_dibujos: Los dibujos del golpe (0xFF al final)
;   0xa5f2..0xa5fc  (10 bytes)
DATA_golpe_dibujos:
	defb 008h,008h,008h,008h,030h,030h,030h,030h,030h,0ffh	; a5f2  ....00000.

; ======================================================================
; CODIGO 0xa5fc..0xaa10  (1044 bytes)
; ======================================================================


prota_der:		; A la derecha: el paso de los pies, un punto si no hay pared (0xA624) y, en cada casilla, lo que pisa
	call objeto_quieto		;a5fc   ; quieto
	call prota_paso		;a5ff   ; el paso
	res 4,(iy+004h)		;a602   ; mirando a la derecha
	call der_paso		;a606   ; un punto
	ld a,(iy+001h)		;a609   ; en una casilla exacta?
	and 007h		;a60c
	ret nz			;a60e
	jp prota_pisa		;a60f
prota_paso:		; Los pies: cada 4 cuadros, el dibujo 0 u 8 (y el segundo sprite, 4 mas)
	inc (iy+008h)		;a612   ; la cuenta
	ld a,(iy+008h)		;a615
	and 004h		;a618   ; cada 4
	rlca			;a61a
	ld (iy+002h),a		;a61b
	add a,004h		;a61e
	ld (iy+012h),a		;a620
	ret			;a623
der_paso:		; Un punto a la derecha si las casillas de delante (en la VRAM, a dos alturas) estan libres (0x10 o desde 0x3C): A = 0x10 si se movio
	ld a,(iy+001h)		;a624   ; en el borde?
	cp 0b8h		;a627
	ret nc			;a629
	push iy		;a62a   ; el protagonista?
	pop hl			;a62c
	ld a,l			;a62d
	and a			;a62e
	jr z,der_paso_prota		;a62f
	ld a,(iy+001h)		;a631
	jr der_paso_mira		;a634
der_paso_prota:
	ld a,(iy+001h)		;a636   ; la X...
	and 00fh		;a639   ; ...dentro de los 16 puntos...
	cp 00ch		;a63b   ; ...desde 12?
	jr nc,der_paso_casillas		;a63d
	ld a,(iy+001h)		;a63f   ; la X - 3...
	sub 003h		;a642
der_paso_mira:
	and 007h		;a644   ; ...en una columna exacta?
	cp 000h		;a646
	jr z,der_paso_casillas		;a648
	jr der_paso_va		;a64a
der_paso_casillas:
	call sitio_vram		;a64c   ; su sitio
