	call pide_efecto_a		;a6fa
	ld a,025h		;a6fd   ; 25 puntos
	ld (0e321h),a		;a6ff
	call puntos_suma		;a702
	push hl			;a705
	ld hl,0197ah		;a706   ; su dibujo en el marcador
	ld a,0fch		;a709
	call bloque_pinta		;a70b
	ld a,(0e30fh)		;a70e   ; dos mas
	add a,002h		;a711
	ld (0e30fh),a		;a713   ; en 0xE30F (lo que protege)
