	ld (0e322h),a		;a75c   ; en los puntos que se suman
	call puntos_suma		;a75f
	push hl			;a762
	xor a			;a763
	ld a,(0e30dh)		;a764   ; uno mas...
	add a,001h		;a767
	daa			;a769   ; ...en BCD
	ld (0e30dh),a		;a76a
pisa_borra:
