	jr z,prota_cae		;a78e
	cp 03ch		;a790
	ret c			;a792
prota_cae:		; Cae: en el aire (+4 bit 2), dos puntos abajo, +5 = 0x10
	set 2,(iy+004h)		;a793   ; en el aire
	inc (iy+000h)		;a797   ; dos puntos abajo
	inc (iy+000h)		;a79a
	inc (iy+010h)		;a79d   ; el segundo sprite
	inc (iy+010h)		;a7a0
