salto:		; El salto, cada 2 cuadros un paso: al empezar, el efecto 4; el dibujo 0x20 (0x28 a la izquierda); sube y baja segun la tabla (0xAA10, o 0xAA23 con 0xE30F de 6 o mas: mas alto); si choca arriba deja de subir; al tocar el suelo, de pie
	inc (iy+00fh)		;a860   ; la cuenta
	ld a,(iy+00fh)		;a863
	cp 002h		;a866   ; 2?
	ret c			;a868
	ld (iy+00fh),000h		;a869   ; a cero
	ld a,(iy+005h)		;a86d   ; el paso 2?
