prota_salto_mira:
	call salto_tabla_paso		;a89a   ; cuanto
	and a			;a89d   ; 0: nada
	ret z			;a89e
	cp 080h		;a89f   ; 0x80: cae
	jr z,salto_cae		;a8a1
	jr c,salto_baja		;a8a3   ; positivo: baja
	ld b,a			;a8a5
	ld a,000h		;a8a6   ; negativo: sube tanto
	sub b			;a8a8
	ld b,a			;a8a9
salto_sube:
	push bc			;a8aa
	call arriba_paso		;a8ab   ; un punto arriba
	pop bc			;a8ae
	cp 010h		;a8af   ; libre?
	jr z,salto_sube_sigue		;a8b1
	cp 03ch		;a8b3
	jr c,salto_techo		;a8b5
salto_sube_sigue:
