	jr nc,casillas_fila_sigue		;a9ba
	set 0,c		;a9bc   ; ocupada
casillas_fila_sigue:
	rrc c		;a9be
	djnz casillas_fila_una		;a9c0   ; B veces
	rrc c		;a9c2
	rrc c		;a9c4
	rrc c		;a9c6
	rrc c		;a9c8
	ret			;a9ca
sitio_vram:		; El sitio en la tabla de nombres de IY: 0x1800 + (Y / 8) x 32 + X / 8 - 32
	push af			;a9cb
	push de			;a9cc
	ld h,018h		;a9cd   ; la tabla de nombres
	ld a,(iy+001h)		;a9cf   ; la X...
	and 0f8h		;a9d2
	rrc a		;a9d4   ; ...entre 8
	rrc a		;a9d6
	rrc a		;a9d8
	ld l,a			;a9da
	ld de,00000h		;a9db
	ld a,(iy+000h)		;a9de   ; la Y...
	and 0c0h		;a9e1
	rlc a		;a9e3
	rlc a		;a9e5
	ld d,a			;a9e7
	ld a,(iy+000h)		;a9e8
	and 038h		;a9eb
	rlc a		;a9ed
	rlc a		;a9ef
	ld e,a			;a9f1
	add hl,de			;a9f2
	ld de,0ffe0h		;a9f3   ; una fila menos
	add hl,de			;a9f6
	pop de			;a9f7
	pop af			;a9f8
	ret			;a9f9
salto_tabla_paso:		; El paso siguiente (+5) de la tabla del salto (HL); pasado el 0x12, 0x80 (cae)
	ld e,(iy+005h)		;a9fa   ; el paso
	inc (iy+005h)		;a9fd   ; el siguiente
	ld a,e			;aa00
	cp 012h		;aa01   ; 0x12?
	jr c,salto_tabla_lee		;aa03
	dec (iy+005h)		;aa05   ; se queda
	ld a,080h		;aa08   ; 0x80: cae
	ret			;aa0a
salto_tabla_lee:
	ld d,000h		;aa0b
	add hl,de			;aa0d
	ld a,(hl)			;aa0e
	ret			;aa0f

; ----------------------------------------------------------------------
; DATOS salto_tablas: Cuanto sube (negativo) o baja el protagonista en cada
;   paso del salto: el normal (0xAA10) y el alto (0xAA23)
;   0xaa10..0xaa44  (52 bytes)
DATA_salto_tablas:
	defb 0f8h,0fbh,0fdh,0fdh,0feh,0ffh,0ffh,0ffh,000h,000h,001h,001h,001h,002h,003h,003h	; aa10  ................
	defb 005h,008h,008h,0f2h,0f2h,0f3h,0f3h,0f4h,0f4h,0f6h,0f8h,0fah,0fbh,0fch,0fdh,0feh	; aa20  ................
	defb 0ffh,0ffh,000h,000h,001h,001h,002h,003h,004h,005h,006h,008h,00ah,00ch,00ch,00dh	; aa30  ................
	defb 00dh,00eh,00eh,080h	; aa40

; ======================================================================
; CODIGO 0xaa44..0xaa68  (36 bytes)
; ======================================================================


marcador_dibujo:		; El dibujo del marcador de la derecha: 11 filas de 5 casillas de la fase (0xE315; 0xAA68 en las 32) desde la fila 13, columna 26
	ld hl,(0e315h)		;aa44   ; el dibujo de la fase
	ld de,019bah		;aa47   ; la fila 13, columna 26
	ld b,00bh		;aa4a   ; 11 filas
marcador_fila:
	push bc			;aa4c
	push de			;aa4d
	push hl			;aa4e
	ld bc,00005h		;aa4f   ; 5 casillas
	call 0005ch		;aa52   ; LDIRVM
	pop hl			;aa55
	push de			;aa56
	ld de,00005h		;aa57   ; las 5 siguientes
	add hl,de			;aa5a
	pop de			;aa5b
	pop de			;aa5c
	push hl			;aa5d
	ld hl,00020h		;aa5e   ; una fila abajo
	add hl,de			;aa61
	ex de,hl			;aa62
	pop hl			;aa63
	pop bc			;aa64
	djnz marcador_fila		;aa65   ; B veces
	ret			;aa67

; ----------------------------------------------------------------------
; DATOS marcador_marco: El dibujo del marcador: un marco de 5 casillas de
;   ancho (0xA0-0xC2); de sus 12 filas se copian 11
;   0xaa68..0xaaa4  (60 bytes)
DATA_marcador_marco:
	defb 0a0h,0a1h,0a1h,0a1h,0a2h,0a7h,0a8h,0a9h,0aah,0a3h,0a7h,0abh,0ach,0adh,0a3h,0a7h	; aa68  ................
	defb 0aeh,0afh,0b0h,0a3h,0a7h,0b1h,0b2h,0b3h,0a3h,0a7h,0b4h,0b5h,0b6h,0a3h,0a7h,0b7h	; aa78  ................
	defb 0b8h,0b9h,0a3h,0a7h,0bah,0bbh,0bch,0a3h,0a7h,0bdh,0beh,0bfh,0a3h,0a7h,0c0h,0c1h	; aa88  ................
	defb 0c2h,0a3h,0a6h,0a5h,0a5h,0a5h,0a4h,0a6h,0a5h,0a5h,0a5h,0a4h	; aa98  ............

; ======================================================================
; CODIGO 0xaaa4..0xad1e  (634 bytes)
; ======================================================================


puntos_suma:		; Con la partida en marcha, suma los puntos pedidos (0xE321 y 0xE322) y los pinta en la fila 3, columna 26
	ld a,(0e000h)		;aaa4   ; jugando?
	and a			;aaa7
	ret z			;aaa8
	push hl			;aaa9
	push iy		;aaaa
	ld iy,0e036h		;aaac   ; los puntos
	ld hl,0187ah		;aab0   ; la fila 3, columna 26
	call puntos_suma_pinta		;aab3   ; sumados y pintados
	pop iy		;aab6
	pop hl			;aab8
	ret			;aab9
puntos_suma_pinta:		; Suma 0xE321 (decenas y unidades) y 0xE322 (millares y centenas), en BCD, a los puntos (0xE034-0xE036) y los pinta en HL
	push hl			;aaba
	ld a,(0e321h)		;aabb   ; las unidades
	ld b,a			;aabe
	xor a			;aabf
	ld (0e321h),a		;aac0   ; gastadas
	ld a,(0e036h)		;aac3   ; la cifra baja
	add a,b			;aac6
	daa			;aac7   ; en BCD
	ld (0e036h),a		;aac8
	jr nc,puntos_suma_cientos		;aacb   ; acarreo?
	ld a,(0e035h)		;aacd   ; la de en medio, +1
	add a,001h		;aad0
	daa			;aad2
	ld (0e035h),a		;aad3
	jr nc,puntos_suma_cientos		;aad6   ; acarreo?
	ld a,(0e034h)		;aad8
	add a,001h		;aadb   ; la alta, +1
	daa			;aadd
	ld (0e034h),a		;aade
puntos_suma_cientos:
	ld a,(0e322h)		;aae1   ; los puntos que se suman
	ld b,a			;aae4
	xor a			;aae5
	ld (0e322h),a		;aae6   ; en los puntos que se suman
	ld a,(0e035h)		;aae9   ; la de en medio
	add a,b			;aaec
	daa			;aaed   ; en BCD
	ld (0e035h),a		;aaee
	jr nc,puntos_suma_fin		;aaf1   ; acarreo?
	ld a,(0e034h)		;aaf3
	add a,001h		;aaf6   ; la alta, +1
	daa			;aaf8
	ld (0e034h),a		;aaf9
	ld iy,0e036h		;aafc
puntos_suma_fin:
	pop hl			;ab00
cifras_pinta:		; Seis cifras (los tres bytes BCD que acaban en IY) en la VRAM HL: los ceros de la izquierda en blanco (0x10), el ultimo siempre
	ld a,010h		;ab01   ; los ceros, en blanco
	ld (0e324h),a		;ab03
	push hl			;ab06
	push iy		;ab07
	ld a,(iy-002h)		;ab09   ; el primer byte
	push af			;ab0c
	and 0f0h		;ab0d   ; la cifra alta
	jr z,cifras_pinta_1b		;ab0f   ; cero?
	cp 0a0h		;ab11   ; mas de 9?
	jr c,cifras_pinta_1		;ab13
	xor a			;ab15   ; 0
	jr cifras_pinta_1		;ab16
cifras_pinta_1b:
	ld a,(0e324h)		;ab18   ; en blanco
	jr cifras_pinta_1v		;ab1b
cifras_pinta_1:
	ld b,a			;ab1d
	xor a			;ab1e
	ld (0e324h),a		;ab1f   ; ya no hay blancos
	ld a,b			;ab22
	rrca			;ab23
	rrca			;ab24
	rrca			;ab25
	rrca			;ab26
cifras_pinta_1v:
	call 0004dh		;ab27   ; WRTVRM
	inc hl			;ab2a
	pop af			;ab2b
	and 00fh		;ab2c   ; la cifra baja
	jr z,cifras_pinta_2b		;ab2e   ; cero?
	cp 00ah		;ab30   ; mas de 9?
	jr c,cifras_pinta_2		;ab32
	xor a			;ab34
	jr cifras_pinta_2		;ab35
cifras_pinta_2b:
	ld a,(0e324h)		;ab37
	jr cifras_pinta_2v		;ab3a
cifras_pinta_2:
	ld b,a			;ab3c
	xor a			;ab3d
	ld (0e324h),a		;ab3e
	ld a,b			;ab41
cifras_pinta_2v:
	call 0004dh		;ab42   ; WRTVRM
	ld a,(iy-001h)		;ab45   ; el segundo byte
	push af			;ab48
	and 0f0h		;ab49   ; la cifra alta
	rrca			;ab4b
	rrca			;ab4c
	rrca			;ab4d
	rrca			;ab4e
	inc hl			;ab4f
	and 00fh		;ab50
	jr z,cifras_pinta_3b		;ab52   ; cero?
	cp 00ah		;ab54
	jr c,cifras_pinta_3		;ab56
	xor a			;ab58
	jr cifras_pinta_3		;ab59
cifras_pinta_3b:
	ld a,(0e324h)		;ab5b
	jr cifras_pinta_3v		;ab5e
cifras_pinta_3:
	ld b,a			;ab60
	xor a			;ab61
	ld (0e324h),a		;ab62
	ld a,b			;ab65
cifras_pinta_3v:
	call 0004dh		;ab66   ; WRTVRM
	inc hl			;ab69
	pop af			;ab6a
	and 00fh		;ab6b   ; la cifra baja
	jr z,cifras_pinta_4b		;ab6d
	cp 00ah		;ab6f
	jr c,cifras_pinta_4		;ab71
	xor a			;ab73
	jr cifras_pinta_4		;ab74
cifras_pinta_4b:
	ld a,(0e324h)		;ab76
	jr cifras_pinta_4v		;ab79
cifras_pinta_4:
	ld b,a			;ab7b
	xor a			;ab7c
	ld (0e324h),a		;ab7d
	ld a,b			;ab80
cifras_pinta_4v:
	call 0004dh		;ab81   ; WRTVRM
	ld a,000h		;ab84   ; las dos ultimas, siempre
	ld (0e324h),a		;ab86
	ld a,(iy+000h)		;ab89   ; el tercer byte
	push af			;ab8c
	and 0f0h		;ab8d
	rrca			;ab8f
	rrca			;ab90
	rrca			;ab91
	rrca			;ab92
	inc hl			;ab93
	cp 00ah		;ab94   ; mas de 9?
	jr c,cifras_pinta_5		;ab96
	xor a			;ab98
cifras_pinta_5:
	call 0004dh		;ab99   ; WRTVRM
	pop af			;ab9c
	and 00fh		;ab9d   ; la ultima
	inc hl			;ab9f
	cp 00ah		;aba0
	jr c,cifras_pinta_6		;aba2
	xor a			;aba4
cifras_pinta_6:
	call 0004dh		;aba5   ; WRTVRM
	pop iy		;aba8
	pop hl			;abaa
	ret			;abab
pantalla_prepara:		; La pantalla apagada y en blanco, los botones a cero y los dibujos de las casillas 0x30-0xFF y sus colores en los tres tercios; los sprites
	call 00041h		;abac   ; DISSCR
	call pantalla_blanco		;abaf   ; la pantalla en blanco
	call espera_256		;abb2   ; una espera
	xor a			;abb5   ; los botones a 0
	ld (0e026h),a		;abb6   ; los botones a 0
	ld (0e020h),a		;abb9   ; el boton 2
	ld (0e022h),a		;abbc   ; el boton 1
	ld (0e024h),a		;abbf   ; 0xE024
	ld (0e180h),a		;abc2   ; la palanca
	ld de,00180h		;abc5   ; los dibujos, en los tres tercios...
	call casillas_pon		;abc8   ; en el primer tercio
	ld de,00980h		;abcb
	call casillas_pon		;abce
	ld de,01180h		;abd1
	call casillas_pon		;abd4
	ld de,02180h		;abd7   ; los colores...
	call colores_pon		;abda
	ld de,02980h		;abdd
	call colores_pon		;abe0
	ld de,03180h		;abe3
	call colores_pon		;abe6
	jp sprites_dibujos		;abe9   ; los dibujos de los sprites
presentacion:		; La presentacion de CASIO: cada 3 cuadros, dos CASIO entran por los lados (filas 11 y 12) y, desde el paso 9, otros dos bajan y suben hacia el centro; con el paso 21, la musica 4 y SOFTWARE (0x8B14) debajo; 128 cuadros o el boton y la pantalla en blanco
	ld a,001h		;abec   ; el paso 1
	ld (0e187h),a		;abee
	ld hl,0180ch		;abf1   ; el que baja: la fila 0, columna 12
	ld (0e189h),hl		;abf4
	ld hl,01aech		;abf7   ; el que sube: la fila 23
	ld (0e18bh),hl		;abfa
presentacion_cuadro:
	ld a,(0e014h)		;abfd   ; 3 cuadros
	cp 003h		;ac00
	jr c,presentacion_cuadro		;ac02
	xor a			;ac04
	ld (0e014h),a		;ac05   ; en la cuenta de cuadros
	call presentacion_centro		;ac08
	call presentacion_lados		;ac0b
	ld hl,0e187h		;ac0e   ; un paso mas
	inc (hl)			;ac11
	ld a,(hl)			;ac12
	cp 015h		;ac13   ; 21?
	jr nc,presentacion_junta		;ac15
	cp 009h		;ac17   ; desde el 9...
	jr c,presentacion_sigue		;ac19
	ld hl,(0e189h)		;ac1b   ; ...el de arriba baja una fila...
	ld bc,00020h		;ac1e
	add hl,bc			;ac21
	ld (0e189h),hl		;ac22
	ld hl,(0e18bh)		;ac25   ; ...y el de abajo sube
	sbc hl,bc		;ac28
	ld (0e18bh),hl		;ac2a
presentacion_sigue:
	jr presentacion_cuadro		;ac2d
presentacion_junta:
	ld a,004h		;ac2f   ; la musica 4
	call pide_musica		;ac31   ; pide la musica
	ld hl,0ad3ah		;ac34
	ld de,019cch		;ac37   ; ...en la fila 14, columna 12
	ld bc,00007h		;ac3a
	call 0005ch		;ac3d   ; LDIRVM
presentacion_espera:
	ld a,(0e026h)		;ac40   ; el boton?
	and a			;ac43
	jr nz,presentacion_fin		;ac44
	ld a,(0e014h)		;ac46   ; 128 cuadros?
	cp 080h		;ac49
	jr c,presentacion_espera		;ac4b
presentacion_fin:
	xor a			;ac4d
	ld (0e026h),a		;ac4e   ; en el boton de empezar
	call silencio		;ac51
	call pantalla_blanco		;ac54
	ret			;ac57
presentacion_centro:		; Desde el paso 9: los dos CASIO que van al centro, uno bajando (0xE189) y otro subiendo (0xE18B), con una fila en blanco detras
	ld a,(0e187h)		;ac58   ; el paso
	cp 009h		;ac5b   ; antes del 9, nada
	ret c			;ac5d
	ld bc,00008h		;ac5e   ; 8 casillas
	ld hl,0ad28h		;ac61   ; la fila de abajo de CASIO
	ld de,(0e189h)		;ac64   ; el que baja
	call 0005ch		;ac68   ; LDIRVM
	ld de,00020h		;ac6b   ; una fila arriba
	and a			;ac6e
	sbc hl,de		;ac6f
	ex de,hl			;ac71
	ld hl,0ad1fh		;ac72   ; la fila de arriba de CASIO
	ld bc,00008h		;ac75
	call 0005ch		;ac78   ; LDIRVM
	ld de,00020h		;ac7b
	and a			;ac7e
	sbc hl,de		;ac7f
	ex de,hl			;ac81
	ld hl,0ad31h		;ac82   ; la fila en blanco, encima
	ld bc,00008h		;ac85
	call 0005ch		;ac88   ; LDIRVM
	ld bc,00008h		;ac8b
	ld hl,0ad1fh		;ac8e   ; la fila de arriba de CASIO
	ld de,(0e18bh)		;ac91   ; el que sube
	call 0005ch		;ac95   ; LDIRVM
	ld de,00020h		;ac98   ; una fila abajo
	add hl,de			;ac9b
	ex de,hl			;ac9c
	ld hl,0ad28h		;ac9d   ; la fila de abajo
	ld bc,00008h		;aca0
	call 0005ch		;aca3   ; LDIRVM
	ld de,00020h		;aca6   ; una fila abajo
	add hl,de			;aca9
	ex de,hl			;acaa
	ld hl,0ad31h		;acab   ; en blanco, debajo
	ld bc,00008h		;acae
	call 0005ch		;acb1   ; LDIRVM
	ret			;acb4
presentacion_lados:		; Los dos CASIO de los lados en las filas 11 y 12: uno entra por la derecha casilla a casilla y el otro por la izquierda, leido desde el final
	ld a,(0e187h)		;acb5   ; el paso
	ld c,a			;acb8
	cp 009h		;acb9   ; ...no mas de 9
	jr c,presentacion_arriba		;acbb
	ld c,009h		;acbd   ; 9 como mucho
presentacion_arriba:
	ld hl,01980h		;acbf   ; en la fila 12, columna 0, menos el paso
	ld b,a			;acc2   ; la columna, hacia la izquierda
	ld a,l			;acc3
	sub b			;acc4
	ld l,a			;acc5
	ex de,hl			;acc6
	ld hl,0ad1fh		;acc7   ; la fila de arriba de CASIO...
	ld b,000h		;acca
	call 0005ch		;accc   ; LDIRVM
	ld de,00020h		;accf
	add hl,de			;acd2
	ex de,hl			;acd3
	ld hl,0ad28h		;acd4
	ld a,(0e187h)		;acd7
	cp 009h		;acda
	jr c,presentacion_arriba_pon		;acdc
	ld a,009h		;acde
presentacion_arriba_pon:
	ld c,a			;ace0   ; C casillas
	call 0005ch		;ace1   ; LDIRVM
	ld hl,01960h		;ace4   ; el otro: la fila 11
	ld a,(0e187h)		;ace7
	ld c,a			;acea
	cp 009h		;aceb   ; 9 o mas?
	jr c,presentacion_izq		;aced
	sub 009h		;acef   ; pasado el 9, se mueve
	add a,l			;acf1
	ld l,a			;acf2
	ld c,009h		;acf3   ; 9
presentacion_izq:
	ex de,hl			;acf5   ; DE: la VRAM
	ld hl,0ad27h		;acf6   ; la fila de arriba, desde el final
	ld a,l			;acf9
	sub c			;acfa   ; - C
	jr nc,presentacion_izq_pon		;acfb
	dec h			;acfd
presentacion_izq_pon:
	ld l,a			;acfe
	call 0005ch		;acff   ; LDIRVM
	ld de,00020h		;ad02   ; una fila abajo
	add hl,de			;ad05
	ex de,hl			;ad06
	ld a,(0e187h)		;ad07   ; el paso
	ld c,a			;ad0a
	cp 009h		;ad0b
	jr c,presentacion_izq_abajo		;ad0d
	ld c,009h		;ad0f
presentacion_izq_abajo:
	ld hl,0ad30h		;ad11
	ld a,l			;ad14
	sub c			;ad15
	jr nc,presentacion_izq_abajo_pon		;ad16
	dec h			;ad18
presentacion_izq_abajo_pon:
	ld l,a			;ad19
	call 0005ch		;ad1a   ; LDIRVM
	ret			;ad1d

; ----------------------------------------------------------------------
; DATOS presentacion_datos: CASIO en dos filas (0xAD1F y 0xAD28, con un blanco
;   0x10 a cada lado), una fila en blanco (0xAD31), SOFTWARE (0xAD3A) y, sin
;   nadie que los lea, dos dibujos de casillas con su tamano (0xAD41: 6 x 2, 4
;   x 2) y una cadena (0xAD59)
;   0xad1e..0xad85  (103 bytes)
DATA_presentacion_datos:
	defb 010h,030h,032h,034h,036h,038h,03ah,03ch,03eh,010h,031h,033h,035h,037h,039h,03bh	; ad1e  .02468:<>.13579;
	defb 03dh,03fh,010h,010h,010h,010h,010h,010h,010h,010h,010h,010h,080h,081h,082h,083h	; ad2e  =?..............
	defb 084h,085h,086h,006h,002h,0c0h,0c1h,0c4h,0c5h,0c8h,0c9h,0c2h,0c3h,0c6h,0c7h,0cah	; ad3e  ................
	defb 0cbh,004h,002h,0cch,0cdh,0d0h,0d1h,0ceh,0cfh,0d2h,0d3h,0b3h,093h,0b4h,0b7h,0bah	; ad4e  ................
	defb 0a3h,09ch,0afh,08fh,0a0h,0a9h,096h,09fh,0a1h,0a9h,09ch,08eh,093h,09ah,0beh,093h	; ad5e  ................
	defb 0aah,00ch,010h,010h,010h,00eh,0a0h,0beh,0afh,0a0h,098h,0b9h,096h,0beh,092h,092h	; ad6e  ................
	defb 010h,09bh,0b7h,0aah,0beh,000h,000h	; ad7e

; ======================================================================
; CODIGO 0xad85..0xadcb  (70 bytes)
; ======================================================================


pantalla_casillas:		; Los dibujos de las casillas 0x30-0x5F (0x6000) y 0x60-0x8F (0x6800) y sus colores (0x7000, 0x7800) en los tres tercios
	ld b,003h		;ad85   ; tres tercios
	ld de,00180h		;ad87   ; la casilla 0x30
pantalla_casillas_1:
	ld hl,06000h		;ad8a   ; sus dibujos
	call tercio_pon		;ad8d
	djnz pantalla_casillas_1		;ad90   ; B veces
	ld b,003h		;ad92   ; tres tercios
	ld de,00300h		;ad94   ; la casilla 0x60
pantalla_casillas_2:
	ld hl,06800h		;ad97   ; sus dibujos
	call tercio_pon		;ad9a
	djnz pantalla_casillas_2		;ad9d   ; B veces
	ld b,003h		;ad9f   ; tres tercios
	ld de,02180h		;ada1   ; los colores de la 0x30
pantalla_colores_1:
	ld hl,07000h		;ada4
	call tercio_pon		;ada7
	djnz pantalla_colores_1		;adaa   ; B veces
	ld b,003h		;adac   ; tres tercios
	ld de,02300h		;adae   ; los colores de la 0x60
pantalla_colores_2:
	ld hl,07800h		;adb1
	call tercio_pon		;adb4
	djnz pantalla_colores_2		;adb7   ; B veces
	ret			;adb9
letras_pon:		; Las letras (0x6680, 0x180 bytes: las casillas 0x00-0x2F) en DE; DE pasa al tercio siguiente
	ld hl,06680h		;adba   ; las letras
tercio_pon:		; 0x180 bytes de HL en la VRAM DE; DE pasa al tercio siguiente (+0x800)
	push bc			;adbd
	ld bc,00180h		;adbe   ; 0x180 bytes
tercio_pon_bc:		; BC bytes de HL en la VRAM DE; DE pasa al tercio siguiente
	call 0005ch		;adc1   ; LDIRVM
	ld bc,00800h		;adc4   ; el tercio siguiente
	add hl,bc			;adc7
	ex de,hl			;adc8
	pop bc			;adc9
	ret			;adca

; ----------------------------------------------------------------------
; DATOS sin_uso_adcb: Codigo al que nadie salta: 0x80 bytes de 0x1CBF a la
;   VRAM (LDIRVM)
;   0xadcb..0xadd4  (9 bytes)
DATA_sin_uso_adcb:
	defb 021h,0bfh,01ch,001h,080h,000h,0c3h,05ch,000h	; adcb  !......\.

; ======================================================================
; CODIGO 0xadd4..0xadfe  (42 bytes)
; ======================================================================


casillas_pon:		; Los dibujos de las casillas 0x30-0xFF (0x6180; con 0xE04A de 4 o mas, 0x6980: solo la pantalla del premio, que lo pone a 0xFF; 0x680 bytes) en DE
	push bc			;add4
	ld a,(0e04ah)		;add5   ; 0xE04A (0xFF: el premio)
	cp 004h		;add8   ; 4 o mas?
	jr c,casillas_pon_1		;adda
	ld hl,06980h		;addc   ; 0x6980
	jr casillas_pon_va		;addf
casillas_pon_1:
	ld hl,06180h		;ade1   ; 0x6180
casillas_pon_va:
	ld bc,00680h		;ade4   ; 0x680 bytes
	jr $-38		;ade7
colores_pon:		; Sus colores (0x7180; con 0xE04A de 4 o mas, 0x7980) en DE
	push bc			;ade9
	ld a,(0e04ah)		;adea   ; 0xE04A
	cp 004h		;aded   ; 4 o mas?
	jr c,colores_pon_1		;adef
	ld hl,07980h		;adf1   ; 0x7980
	jr casillas_pon_va		;adf4
colores_pon_1:
	ld hl,07180h		;adf6   ; 0x7180
	ld bc,00680h		;adf9   ; 0x680 bytes
	jr $-59		;adfc

; ----------------------------------------------------------------------
; DATOS sin_uso_adfe: Codigo al que nadie salta: 0x16 bytes a la VRAM y un
;   salto a tercio_pon
;   0xadfe..0xae0a  (12 bytes)
DATA_sin_uso_adfe:
	defb 0c5h,001h,016h,000h,0cdh,05ch,000h,001h,020h,000h,018h,0bdh	; adfe  .....\.. ...

; ======================================================================
; CODIGO 0xae0a..0xae3a  (48 bytes)
; ======================================================================


colores_tercio:		; 8 bytes de color A en la VRAM HL (FILVRM) y HL al tercio siguiente
	push bc			;ae0a
	ld bc,00008h		;ae0b   ; 8 bytes
	call 00056h		;ae0e   ; FILVRM
	ld de,00800h		;ae11   ; el tercio siguiente
	add hl,de			;ae14
	pop bc			;ae15
	ret			;ae16
sprites_dibujos:		; Los dibujos de los sprites: 0x800 bytes de 0x5800 en 0x3800
	ld de,03800h		;ae17   ; la tabla de los sprites
	ld hl,05800h		;ae1a   ; los dibujos
	ld bc,00800h		;ae1d   ; 0x800 bytes
	jp 0005ch		;ae20   ; LDIRVM
pantalla_blanco:		; La tabla de nombres en blanco (0x10) y los sprites fuera
	ld a,010h		;ae23   ; el blanco
	ld hl,01800h		;ae25   ; la tabla de nombres
	ld bc,00300h		;ae28   ; 0x300 casillas
	call 00056h		;ae2b   ; FILVRM
	jp sprites_borra_todo		;ae2e   ; los sprites
espera_256:		; Una espera: HL y BC con 0xE000 y 0xF00 (como para borrar la RAM), pero el bucle solo cuenta C 256 veces
	ld hl,0e000h		;ae31   ; (0xE000)
	ld bc,00f00h		;ae34   ; (0xF00)
	jp espera_bucle		;ae37

; ----------------------------------------------------------------------
; DATOS sin_uso_ae3a: Codigo al que nadie salta: HL = 0xE100, BC = 0xE00
;   0xae3a..0xae40  (6 bytes)
DATA_sin_uso_ae3a:
	defb 021h,000h,0e1h,001h,000h,00eh	; ae3a

; ======================================================================
; CODIGO 0xae40..0xafa7  (359 bytes)
; ======================================================================


espera_bucle:
	ld hl,00000h		;ae40   ; HL: nada
	inc hl			;ae43
	dec c			;ae44   ; 256 vueltas
	jp nz,espera_bucle		;ae45
	jr nz,espera_bucle		;ae48
	ret			;ae4a
silencio:		; Todo callado: 0xE007 = 0xFF (la interrupcion borra el motor) y el registro 7 del PSG a 0xFF
	ld a,0ffh		;ae4b   ; 0xFF...
	ld (0e007h),a		;ae4d   ; ...para la interrupcion
	jp pide_mezcla		;ae50   ; el registro 7: nada suena
sprites_borra_todo:		; Los atributos 0xE100-0xE12E a cero y los sprites a la VRAM
	ld hl,0e100h		;ae53   ; los atributos
	ld b,02fh		;ae56   ; 0x2F bytes
sprites_borra_uno:
	ld (hl),000h		;ae58
	inc hl			;ae5a
	djnz sprites_borra_uno		;ae5b   ; B veces
sprites_vram:		; Los sprites a la tabla de atributos (0x1B00): sin marco, 8 de 0xE100 (de 16 en 16 bytes); con el marco, 7 de 0xE331 (de 6 en 6)
	ld a,(0e35bh)		;ae5d   ; el marco?
	and a			;ae60
	jp nz,sprites_vram_marco		;ae61
	ld hl,00010h		;ae64   ; de 16 en 16
	ld (0e35ch),hl		;ae67
	ld b,008h		;ae6a   ; 8 sprites
	ld hl,0e100h		;ae6c   ; desde 0xE100
	jr sprites_vram_va		;ae6f
sprites_vram_marco:
	ld hl,00006h		;ae71   ; de 6 en 6
	ld (0e35ch),hl		;ae74
	ld hl,0e331h		;ae77   ; desde 0xE331
	ld b,007h		;ae7a   ; 7 sprites
sprites_vram_va:
	ld de,01b00h		;ae7c   ; la tabla de atributos
sprites_vram_uno:
	push bc			;ae7f
	push hl			;ae80
	push de			;ae81
	ld bc,00004h		;ae82   ; 4 bytes
	call 0005ch		;ae85   ; LDIRVM
	pop de			;ae88
	ld hl,00004h		;ae89   ; el siguiente en la VRAM
	add hl,de			;ae8c
	ex de,hl			;ae8d
	pop hl			;ae8e
	push de			;ae8f
	ld de,(0e35ch)		;ae90   ; el siguiente en la RAM
	add hl,de			;ae94
	pop de			;ae95
	pop bc			;ae96
	djnz sprites_vram_uno		;ae97   ; B veces
	ret			;ae99
interrupcion:		; La interrupcion (H.TIMI): el silencio pedido (0xE007), las 16 cuentas de cuadros (0xE010), el sonido; en partida, F1 (0xE1B3), STOP (0xE1B5), los botones, la barra, GRAPH y la palanca; fuera de partida, la demostracion (su lista, cada 16 cuadros) o el boton de empezar
	ld a,(0e007h)		;ae9a   ; el silencio pedido?
	cp 0ffh		;ae9d
	jr nz,interrupcion_cuentas		;ae9f
	call pide_silencio		;aea1   ; todo callado
	xor a			;aea4   ; ya esta
	ld (0e007h),a		;aea5
interrupcion_cuentas:
	ld hl,0e010h		;aea8   ; las cuentas de cuadros
	ld b,010h		;aeab   ; dieciseis
interrupcion_cuenta:
	inc (hl)			;aead   ; +1
	inc hl			;aeae
	djnz interrupcion_cuenta		;aeaf   ; B veces
	call sonido_cuadro		;aeb1   ; el sonido
	ld a,(0e000h)		;aeb4   ; jugando
	and a			;aeb7
	jp z,interrupcion_demo		;aeb8   ; no: la demostracion o el titulo
	ld a,006h		;aebb   ; la fila 6: F1 (bit 5)?
	call 00141h		;aebd   ; SNSMAT
	bit 5,a		;aec0   ; F1?
	jr z,tecla_f1		;aec2
	xor a			;aec4   ; suelta
	ld (0e1b4h),a		;aec5   ; suelta
	jr tecla_stop		;aec8
tecla_f1:
	ld a,(0e1b4h)		;aeca   ; ya sostenida?
	and a			;aecd
	jr nz,tecla_stop		;aece
	inc a			;aed0   ; recien pulsada: se pierde una vida (0xE1B3)
	ld (0e1b3h),a		;aed1   ; 0xE1B3 = 1
	ld (0e1b4h),a		;aed4
tecla_stop:
	ld a,007h		;aed7   ; la fila 7: STOP (bit 4)?
	call 00141h		;aed9   ; SNSMAT
	bit 4,a		;aedc   ; STOP?
	jr z,tecla_stop_si		;aede
	xor a			;aee0   ; suelta
	ld (0e1b5h),a		;aee1   ; suelta
	jr interrupcion_botones		;aee4
tecla_stop_si:
	ld a,0ffh		;aee6   ; sostenida
	ld (0e1b5h),a		;aee8   ; en STOP
interrupcion_botones:
	ld de,0e020h		;aeeb   ; el boton 1 del mando 1...
	ld hl,0e021h		;aeee   ; ...recien pulsado y sostenido
	ld a,001h		;aef1
	call boton_mando		;aef3   ; leido
	ld de,0e022h		;aef6   ; el boton 1 del mando 2 (GTTRIG 3)
	ld hl,0e02dh		;aef9
	ld a,003h		;aefc
	call boton_mando		;aefe   ; leido
	ld de,0e024h		;af01   ; la barra (GTTRIG 0)
	ld hl,0e025h		;af04
	ld a,000h		;af07
	call boton_mando		;af09   ; leida
	ld a,001h		;af0c   ; GTTRIG 1...
	call 000d8h		;af0e   ; ...sin guardar
	ld de,0e020h		;af11   ; GRAPH y la barra
	ld hl,0e02bh		;af14
	call botones_teclado		;af17   ; leidas
palanca:		; La palanca: los cursores o el mando 1 (GTSTCK 0 y 1), en 0xE180
	xor a			;af1a
	call 000d5h		;af1b   ; GTSTCK 0: los cursores
	ld (0e181h),a		;af1e
	ld a,001h		;af21
	call 000d5h		;af23   ; GTSTCK 1: el mando 1
	ld c,a			;af26
	ld a,(0e181h)		;af27
	add a,c			;af2a
	ld (0e180h),a		;af2b
	ret			;af2e
boton_mando:		; GTTRIG A: lo recien pulsado en (DE) y lo sostenido en (HL)
	call 000d8h		;af2f   ; GTTRIG
	and a			;af32
boton_mira:
	jr nz,boton_pulsado		;af33   ; pulsado?
boton_suelto:
	ld (hl),000h		;af35   ; suelto
	ret			;af37
boton_pulsado:
	ld a,(hl)			;af38   ; ya sostenido?
	and a			;af39
	ret nz			;af3a
	inc a			;af3b   ; recien pulsado
	ld (hl),a			;af3c   ; sostenido
	ld (de),a			;af3d   ; recien pulsado
	ret			;af3e
barra_lee:		; La barra (fila 8, bit 0): lo mismo
	ld a,008h		;af3f   ; la fila 8...
	call 00141h		;af41   ; SNSMAT
	rrca			;af44   ; el bit 0: pulsada = 0
	jr nc,boton_pulsado		;af45
	jr boton_suelto		;af47
botones_teclado:		; La barra como boton 1 y GRAPH (fila 6, bit 2) como boton 2
	ld a,006h		;af49   ; la fila 6
	call 00141h		;af4b   ; SNSMAT
	cpl			;af4e   ; pulsada = 1
	bit 2,a		;af4f   ; GRAPH (bit 2)
	call boton_mira		;af51
	inc hl			;af54   ; 0xE02C...
	inc de			;af55   ; ...0xE022
	inc de			;af56
	ld a,008h		;af57   ; la fila 8
	call 00141h		;af59   ; SNSMAT
	cpl			;af5c   ; pulsada = 1
	push af			;af5d   ; guardada
	rrc a		;af5e   ; la barra?
	jr nc,barra_suelta		;af60
	ld a,0ffh		;af62   ; sostenida: 0xFF
	jr barra_sostenida		;af64
barra_suelta:
	xor a			;af66   ; suelta: 0
barra_sostenida:
	ld b,a			;af67
	ld a,(0e19dh)		;af68   ; con el boton 1 del mando, sostenido
	or b			;af6b
	ld (0e19dh),a		;af6c
	pop af			;af6f   ; la fila 8
	bit 0,a		;af70   ; la barra
	jr boton_mira		;af72   ; recien pulsada?
interrupcion_demo:		; Fuera de partida: en la demostracion, cada 16 cuadros (0xE016), el byte siguiente de su lista (0xE037): la palanca (bits 0-3), el golpe (bit 5, 0xE323), el boton 1 (bit 4) y el 2 (bit 7); si no, el boton de empezar
	ld a,(0e027h)		;af74   ; la demostracion
	and a			;af77
	jr z,$+64		;af78   ; no: el titulo
	ld a,(0e016h)		;af7a   ; 16 cuadros?
	cp 010h		;af7d
	jr c,$+63		;af7f   ; aun no
	xor a			;af81   ; a cero
	ld (0e016h),a		;af82
	ld hl,(0e037h)		;af85   ; la lista
	ld a,(hl)			;af88   ; un byte
	inc hl			;af89   ; el siguiente
	ld (0e037h),hl		;af8a
	ld b,a			;af8d   ; guardado
	and 00fh		;af8e   ; la palanca
	ld (0e180h),a		;af90
	ld a,b			;af93
	and 020h		;af94   ; los botones
	ld (0e323h),a		;af96
	ld a,b			;af99   ; el bit 4
	and 010h		;af9a
	ld (0e022h),a		;af9c   ; el boton 1
	ld a,b			;af9f   ; el bit 7
	and 080h		;afa0
	ld (0e02bh),a		;afa2   ; el boton 2
	jr $+25		;afa5   ; al boton de empezar

; ----------------------------------------------------------------------
; DATOS sin_uso_afa7: Codigo al que nadie salta (lo salta el "jr" de 0xAFA5):
;   el bit 5 al boton 1 (0xE022) o a los dos (0xE020 y 0xE022), como en otros
;   Casio
;   0xafa7..0xafb8  (17 bytes)
DATA_sin_uso_afa7:
	defb 0feh,020h,028h,005h,032h,022h,0e0h,018h,00eh,032h,020h,0e0h,032h,022h,0e0h,018h	; afa7  . (.2"...2 .2"..
	defb 006h	; afb7

; ======================================================================
; CODIGO 0xafb8..0xb016  (94 bytes)
; ======================================================================


interrupcion_titulo:		; Fuera de partida y sin demostracion: el boton de empezar y la palanca
	call boton_empezar		;afb8   ; el boton
	jp palanca		;afbb   ; la palanca
boton_empezar:		; El boton de empezar (0xE026): la barra o el boton 1 del mando; con el boton, tambien 0xE325
	ld de,0e026h		;afbe   ; la barra, recien pulsada...
	ld hl,0e025h		;afc1   ; ...y sostenida
	call barra_lee		;afc4   ; leida
	ld a,(de)			;afc7   ; recien pulsada?
	ld (0e181h),a		;afc8   ; guardada
	ld hl,0e021h		;afcb   ; el boton 1 del mando
	ld a,001h		;afce
	call boton_mando		;afd0   ; leido
	ld a,(de)			;afd3   ; recien pulsado?
	ld b,a			;afd4
	ld a,(0e181h)		;afd5   ; o la barra
	or b			;afd8
	ld (de),a			;afd9   ; el boton de empezar
	ld a,(0e021h)		;afda   ; el boton
	and a			;afdd
	ret z			;afde
	ld (0e325h),a		;afdf   ; 0xE325
	ret			;afe2
espera_musica:		; Espera 8 cuadros; despues, con los sprites puestos cada vez, a que acabe la musica (sin partida, el boton la corta); el silencio y otros 16 cuadros
	xor a			;afe3
	ld a,(0e011h)		;afe4   ; la cuenta de cuadros
espera_musica_8:
	ld a,(0e011h)		;afe7   ; 8 cuadros?
	cp 008h		;afea
	jr c,espera_musica_8		;afec
espera_musica_bucle:
	call sprites_vram		;afee   ; los sprites
	ld a,(0e000h)		;aff1   ; jugando?
	and a			;aff4
	jr nz,espera_musica_mira		;aff5
	ld a,(0e026h)		;aff7   ; el boton?
	and a			;affa
	ret nz			;affb
espera_musica_mira:
	ld a,(0e2bdh)		;affc   ; sonando?
	and a			;afff
	jr nz,espera_musica_bucle		;b000
	ld a,(0e2beh)		;b002   ; pedida?
	and a			;b005
	jr nz,espera_musica_bucle		;b006
	ld (0e011h),a		;b008   ; la cuenta a 0
	call silencio		;b00b   ; el sonido a cero
espera_musica_16:
	ld a,(0e011h)		;b00e   ; 16 cuadros?
	cp 010h		;b011
	jr c,espera_musica_16		;b013
	ret			;b015

; ----------------------------------------------------------------------
; DATOS mapas_b: Los mapas de cuatro fases (24, 17, 16 y 29), al final de la
;   ROM
;   0xb016..0xb2ca  (692 bytes)
DATA_mapas_b:
	defb 0f5h,017h,0ebh,017h,0f8h,017h,0e8h,017h,0d0h,017h,045h,001h,001h,018h,00fh,007h	; b016  ..........E.....
	defb 001h,005h,011h,017h,00ch,007h,002h,017h,01bh,017h,003h,017h,00eh,00bh,020h,017h	; b026  .............. .
	defb 002h,004h,011h,017h,001h,00ch,001h,019h,013h,017h,00eh,017h,004h,007h,01bh,005h	; b036  ................
	defb 004h,019h,001h,01bh,00ah,007h,003h,006h,010h,017h,00bh,007h,001h,017h,01ch,017h	; b046  ................
	defb 003h,017h,00eh,017h,001h,019h,004h,019h,001h,019h,00ah,006h,005h,005h,00eh,017h	; b056  ................
	defb 004h,017h,001h,017h,00ch,017h,006h,017h,00ah,017h,001h,004h,004h,017h,009h,017h	; b066  ................
	defb 004h,017h,001h,00bh,009h,017h,017h,017h,003h,017h,005h,016h,00ah,007h,006h,006h	; b076  ................
	defb 018h,007h,002h,017h,007h,017h,014h,007h,003h,017h,01bh,007h,002h,017h,01bh,00bh	; b086  ................
	defb 003h,017h,01dh,005h,010h,017h,004h,007h,01eh,005h,00eh,017h,004h,017h,00eh,018h	; b096  ................
	defb 004h,019h,001h,019h,001h,019h,008h,006h,004h,006h,004h,006h,0ffh,0f5h,017h,0ebh	; b0a6  ................
	defb 017h,0f8h,017h,0e8h,017h,0c0h,017h,070h,017h,0a3h,017h,013h,017h,00ch,017h,017h	; b0b6  .......p........
	defb 005h,008h,006h,006h,005h,00ch,001h,002h,005h,00bh,006h,005h,017h,012h,004h,00dh	; b0c6  ................
	defb 006h,00fh,017h,003h,017h,003h,019h,008h,00bh,007h,005h,012h,012h,008h,017h,001h	; b0d6  ................
	defb 017h,003h,019h,001h,019h,00eh,006h,006h,001h,008h,017h,001h,017h,001h,017h,005h	; b0e6  ................
	defb 004h,007h,00bh,00ah,017h,00ch,006h,00bh,017h,001h,017h,007h,017h,00bh,007h,006h	; b0f6  ................
	defb 007h,018h,005h,006h,005h,009h,017h,004h,008h,005h,016h,005h,00bh,00ah,004h,00ah	; b106  ................
	defb 001h,007h,017h,005h,005h,003h,005h,00fh,017h,003h,005h,012h,017h,001h,017h,003h	; b116  ................
	defb 007h,00bh,019h,010h,006h,005h,017h,009h,017h,003h,017h,019h,006h,004h,006h,004h	; b126  ................
	defb 006h,0ffh,0f5h,017h,0ebh,017h,0f8h,017h,0e8h,017h,0c0h,017h,070h,017h,0a0h,017h	; b136  ............p...
	defb 036h,006h,00fh,004h,006h,017h,005h,00ch,005h,017h,005h,019h,009h,007h,006h,004h	; b146  6...............
	defb 007h,017h,005h,00ah,001h,019h,002h,019h,001h,017h,009h,00ah,003h,006h,00bh,00ch	; b156  ................
	defb 004h,017h,003h,005h,010h,017h,009h,017h,004h,017h,002h,017h,005h,019h,007h,017h	; b166  ................
	defb 001h,017h,006h,005h,007h,00ch,007h,005h,004h,017h,00ah,005h,00bh,017h,004h,017h	; b176  ................
	defb 002h,002h,003h,005h,009h,017h,001h,017h,008h,002h,005h,00ch,005h,005h,010h,002h	; b186  ................
	defb 004h,005h,007h,017h,004h,017h,007h,002h,007h,017h,001h,017h,002h,005h,00bh,00ch	; b196  ................
	defb 005h,00eh,004h,005h,010h,00ah,007h,017h,009h,017h,009h,017h,001h,017h,002h,017h	; b1a6  ................
	defb 002h,017h,002h,005h,007h,00bh,009h,017h,002h,017h,00ch,017h,002h,017h,002h,002h	; b1b6  ................
	defb 006h,017h,001h,00bh,005h,00bh,001h,017h,001h,017h,00bh,00bh,005h,016h,001h,003h	; b1c6  ................
	defb 001h,003h,008h,017h,003h,001h,002h,017h,001h,017h,009h,019h,003h,001h,001h,001h	; b1d6  ................
	defb 00ah,006h,004h,006h,004h,006h,0ffh,0f5h,017h,0ebh,017h,0c0h,017h,070h,017h,0b1h	; b1e6  .............p..
	defb 019h,010h,002h,017h,019h,008h,004h,006h,006h,00ah,017h,002h,017h,003h,007h,001h	; b1f6  ................
	defb 017h,014h,003h,008h,017h,002h,019h,001h,001h,00bh,00bh,004h,004h,011h,004h,004h	; b206  ................
	defb 004h,007h,017h,003h,00ch,002h,019h,001h,006h,00ch,017h,004h,017h,00ah,00bh,003h	; b216  ................
	defb 017h,004h,019h,00dh,019h,002h,005h,00ah,017h,003h,017h,001h,005h,004h,017h,001h	; b226  ................
	defb 017h,002h,007h,007h,017h,004h,017h,00ah,00bh,005h,012h,002h,017h,001h,005h,010h	; b236  ................
	defb 017h,008h,017h,003h,017h,003h,017h,002h,017h,00ah,017h,004h,001h,002h,001h,008h	; b246  ................
	defb 00bh,006h,00fh,001h,017h,001h,010h,00eh,017h,002h,017h,008h,017h,003h,017h,003h	; b256  ................
	defb 017h,001h,016h,001h,017h,00ah,017h,004h,012h,002h,017h,008h,00ch,006h,017h,002h	; b266  ................
	defb 017h,003h,017h,00dh,00ah,008h,017h,004h,017h,004h,017h,003h,017h,007h,017h,001h	; b276  ................
	defb 017h,006h,017h,007h,00bh,005h,005h,004h,019h,002h,008h,00ch,017h,009h,017h,003h	; b286  ................
	defb 017h,008h,017h,007h,004h,002h,017h,003h,005h,00ch,017h,002h,017h,003h,017h,00ch	; b296  ................
	defb 016h,005h,003h,002h,002h,009h,004h,00fh,017h,001h,017h,007h,017h,00eh,003h,002h	; b2a6  ................
	defb 016h,00ch,017h,004h,003h,006h,017h,003h,017h,015h,017h,012h,017h,005h,006h,004h	; b2b6  ................
	defb 006h,004h,006h,0ffh	; b2c6

; ----------------------------------------------------------------------
; DATOS mapas_sobra: Una copia del final del ultimo mapa (0xB294): nadie la
;   lee
;   0xb2ca..0xb300  (54 bytes)
DATA_mapas_sobra:
	defb 017h,003h,017h,008h,017h,007h,004h,002h,017h,003h,005h,00ch,017h,002h,017h,003h	; b2ca  ................
	defb 017h,00ch,016h,005h,003h,002h,002h,009h,004h,00fh,017h,001h,017h,007h,017h,00eh	; b2da  ................
	defb 003h,002h,016h,00ch,017h,004h,003h,006h,017h,003h,017h,015h,017h,012h,017h,005h	; b2ea  ................
	defb 006h,004h,006h,004h,006h,0ffh	; b2fa

; ======================================================================
; CODIGO 0xb300..0xb312  (18 bytes)
; ======================================================================


salto_efecto_a:		; La tabla de saltos del motor de sonido (0xB300-0xB311): pedir un efecto de A...
	jp sonido_a_pide		;b300
salto_efecto_bc:		; ...uno de B y C...
	jp sonido_bc_pide		;b303
salto_musica:		; ...una musica...
	jp musica_pide		;b306
salto_sonido:		; ...el sonido de un cuadro...
	jp sonido		;b309
salto_mezcla:		; ...el registro 7...
	jp psg_mezcla		;b30c
salto_silencio:		; ...y todo callado
	jp silencio_motor		;b30f

; ----------------------------------------------------------------------
; DATOS musicas: Las musicas: los tres canales (A, B y C) de cada una, 6
;   bytes; la 0, las tres en 0xB75B (nada)
;   0xb312..0xb336  (36 bytes)
DATA_musicas:
	defb 05bh,0b7h,05bh,0b7h,05bh,0b7h,0aeh,0b8h,009h,0b9h,05bh,0b9h,06dh,0b7h,0c8h,0b7h	; b312  [.[.[.....[.m...
	defb 029h,0b8h,0a1h,0bbh,0eah,0bbh,069h,0bch,05fh,0b7h,063h,0b7h,067h,0b7h,012h,0bdh	; b322  ).....i._.c.g...
	defb 0a3h,0bdh,013h,0beh	; b332

; ----------------------------------------------------------------------
; DATOS efectos_a: Los efectos del canal A: una pieza cada uno (2 bytes)
;   0xb336..0xb342  (12 bytes)
DATA_efectos_a:
	defb 030h,0b7h,0ech,0beh,0e3h,0beh,0dfh,0beh,034h,0b7h,048h,0b7h	; b336  0.......4.H.

; ----------------------------------------------------------------------
; DATOS efectos_bc: Los efectos de los canales B y C: dos piezas cada uno (4
;   bytes)
;   0xb342..0xb352  (16 bytes)
DATA_efectos_bc:
	defb 05bh,0b7h,05bh,0b7h,086h,0beh,0b1h,0beh,0f9h,0beh,061h,0bfh,0a4h,0b9h,032h,0bah	; b342  [.[.......a...2.

; ======================================================================
; CODIGO 0xb352..0xb627  (725 bytes)
; ======================================================================


sonido_a_pide:		; Pide el efecto A del canal A (0xE2C0); gana el de numero menor. Donde otros Casio llevan "ret z" (sin partida, nada), aqui hay un "nop": suena tambien en la demostracion
	ld b,a			;b352
	ld a,(0e000h)		;b353   ; jugando...
	and a			;b356   ; ninguno?
	nop			;b357   ; ..."nop" (no "ret z")
sonido_a_pon:
	ld a,b			;b358   ; el efecto
	ld hl,0e2c0h		;b359   ; el pedido del canal A
	jr pide_va		;b35c
sonido_bc_pide:		; Pide el efecto A de los canales B y C (0xE2C2); lo mismo
	ld b,a			;b35e
	ld a,(0e000h)		;b35f   ; jugando...
	and a			;b362
	nop			;b363   ; ..."nop"
	ld a,b			;b364   ; el efecto
	ld hl,0e2c2h		;b365   ; el efecto pedido
pide_va:
	ld b,a			;b368
	ld a,(hl)			;b369   ; ya hay uno?
	and a			;b36a
	jr z,pide_pon		;b36b
	cp b			;b36d   ; el de antes es menor: se queda
	ret c			;b36e
pide_pon:
	ld (hl),b			;b36f   ; guardado
	ret			;b370
musica_pide:		; Pide la musica A (0xE2BE), con la misma regla
	ld hl,0e2beh		;b371   ; la musica pedida
	jr pide_va		;b374
sonido:		; El sonido de cada cuadro (desde la interrupcion): una musica nueva o un efecto nuevo empiezan; los tres canales (0xE280, 0xE292, 0xE2A4, 18 bytes) siguen
	ld hl,0e2bdh		;b376   ; una musica sonando?
	xor a			;b379
	cp (hl)			;b37a   ; sonando?
	jr nz,sonido_musica_otra		;b37b
	inc hl			;b37d   ; una pedida?
	cp (hl)			;b37e
	jp nz,musica_empieza		;b37f   ; empieza
	inc hl			;b382   ; un efecto de A sonando?
	cp (hl)			;b383
	jr nz,sonido_efecto_a_otro		;b384   ; si: mirar si hay otro pedido
	inc hl			;b386   ; uno pedido?
	cp (hl)			;b387
	jp nz,efecto_a_empieza		;b388   ; empieza
sonido_mira_bc:
	xor a			;b38b   ; un efecto de B y C sonando?
	inc hl			;b38c
	cp (hl)			;b38d
	jr nz,sonido_efecto_bc_otro		;b38e
	inc hl			;b390   ; uno pedido?
	cp (hl)			;b391
	jp nz,efecto_bc_empieza		;b392   ; empieza
sonido_musica_otra:
	call pedido_mira		;b395   ; otra musica pedida, de numero menor?
	jp c,musica_empieza		;b398   ; empieza
	jr sonido_canal_a		;b39b
sonido_efecto_a_otro:
	call pedido_mira		;b39d   ; otro efecto de A pedido, de numero menor?
	jp c,efecto_a_empieza		;b3a0   ; empieza
	jr sonido_mira_bc		;b3a3
sonido_efecto_bc_otro:
	call pedido_mira		;b3a5   ; otro efecto de B y C pedido, de numero menor?
	jp c,efecto_bc_empieza		;b3a8   ; empieza
sonido_canal_a:		; El canal A: su bloque a 0xE2C3, un paso y de vuelta
	ld a,(0e2bdh)		;b3ab   ; la musica?
	and a			;b3ae
	jr nz,sonido_canal_a_va		;b3af
	ld a,(0e2bfh)		;b3b1   ; o un efecto que use el canal A?
	and a			;b3b4
	jr z,sonido_canal_b		;b3b5
sonido_canal_a_va:
	ld hl,0e280h		;b3b7   ; el canal A
	call canal_a_trabajo		;b3ba   ; al canal de trabajo
	ld bc,00008h		;b3bd   ; el registro 8 (el volumen de A)
	xor a			;b3c0   ; el canal 0
	call canal_un_paso		;b3c1   ; un paso
	push af			;b3c4
	ld de,0e280h		;b3c5   ; de vuelta al canal A
	call canal_de_trabajo		;b3c8
	pop af			;b3cb   ; 0: nada
	and a			;b3cc
	jr z,sonido_canal_b		;b3cd
	cp 001h		;b3cf   ; 1: la pieza acabo
	jp z,musica_acaba		;b3d1
	cp 002h		;b3d4   ; 2: callar
	jp z,sonido_a_acaba		;b3d6
sonido_canal_b:		; Los canales B y C: con la musica o el efecto de B y C, un paso de cada uno (los registros 2-3 y 9, 4-5 y 10); al acabar, 0xB6EB
	ld a,(0e2bdh)		;b3d9   ; la musica?
	and a			;b3dc
	jr nz,sonido_canal_b_va		;b3dd
	ld a,(0e2c1h)		;b3df   ; o el efecto de B y C?
	and a			;b3e2
	ret z			;b3e3
sonido_canal_b_va:
	ld hl,0e292h		;b3e4   ; el canal B
	call canal_a_trabajo		;b3e7   ; al canal de trabajo
	ld bc,00209h		;b3ea   ; los registros 2 y 9
	ld a,(0e008h)		;b3ed   ; el mezclador, corrido un bit
	rrca			;b3f0
	ld (0e008h),a		;b3f1
	ld a,001h		;b3f4   ; el canal 1
	call canal_un_paso		;b3f6   ; un paso
	push af			;b3f9
	ld de,0e292h		;b3fa   ; de vuelta al canal B
	call canal_de_trabajo		;b3fd
	pop af			;b400
	cp 003h		;b401   ; 3: sigue
	jr z,sonido_canal_c		;b403
	ld b,a			;b405
	ld a,(0e008h)		;b406   ; los bits de vuelta
	rlca			;b409
	ld (0e008h),a		;b40a
	ld a,b			;b40d
	and a			;b40e
	jp nz,efecto_bc_acaba		;b40f   ; acabado
sonido_canal_c:		; El canal C: lo mismo con los registros 4 y 10; despues, el barrido del ruido
	ld hl,0e2a4h		;b412   ; el canal C
	call canal_a_trabajo		;b415   ; al canal de trabajo
	ld bc,0040ah		;b418   ; los registros 4 y 10
	ld a,(0e008h)		;b41b   ; el mezclador, corrido dos bits
	rrca			;b41e
	rrca			;b41f
	ld (0e008h),a		;b420
	ld a,002h		;b423   ; el canal 2
	call canal_un_paso		;b425   ; un paso
	push af			;b428
	ld de,0e2a4h		;b429   ; de vuelta al canal C
	call canal_de_trabajo		;b42c
	pop af			;b42f
	cp 003h		;b430   ; 3: sigue
	jp z,ruido_barrido		;b432   ; el ruido
	ld b,a			;b435
	ld a,(0e008h)		;b436   ; los bits de vuelta
	rlca			;b439
	rlca			;b43a
	ld (0e008h),a		;b43b
	ld a,b			;b43e   ; acabado?
	and a			;b43f
	jp nz,efecto_bc_acaba		;b440   ; los canales B y C, acabados
	jp ruido_barrido		;b443   ; el ruido
canal_a_trabajo:		; Copia el bloque del canal (HL, 18 bytes) a 0xE2C3
	ld de,0e2c3h		;b446   ; al canal de trabajo
copia18:
	ld bc,00012h		;b449   ; 18 bytes
	ldir		;b44c   ; copiados
	ret			;b44e
canal_de_trabajo:		; Y de vuelta a DE
	ld hl,0e2c3h		;b44f
	jr copia18		;b452
canal_paso:		; Un paso del canal de trabajo: si la nota sigue, nada; si no, el byte siguiente de la pieza: una nota (menos de 0xF0) o una orden
	ld hl,0e2cdh		;b454   ; la nota sigue?
	ld a,(hl)			;b457
	and a			;b458
	jr z,canal_byte		;b459
	call canal_cuenta		;b45b   ; la cuenta de la nota
	and a			;b45e   ; aun suena
	ret z			;b45f
canal_byte:		; El byte siguiente de la pieza (0xE2C3): menos de 0xF0, una nota (duracion y volumen, el tono) y 3; si no, una orden
	ld iy,0e2cdh		;b460
	ld hl,(0e2c3h)		;b464
	ld a,(hl)			;b467   ; el byte
	cp 0f0h		;b468   ; 0xF0 o mas: una orden
	jr nc,canal_orden		;b46a
	call nota_pon		;b46c   ; la duracion y el volumen
	call tono_pon		;b46f   ; el tono
	ld (0e2c3h),hl		;b472   ; apuntado
	ld a,(0e008h)		;b475   ; el canal con tono, sin ruido
	res 0,a		;b478
	set 3,a		;b47a
canal_mezcla:
	ld c,a			;b47c   ; guardado
	ld a,(0e2d5h)		;b47d   ; corrido al canal
	and a			;b480
	ld b,a			;b481
	ld a,c			;b482
	jr z,canal_mezcla_pon		;b483
canal_mezcla_corre:
	rlca			;b485
	djnz canal_mezcla_corre		;b486   ; B veces
canal_mezcla_pon:
	ld (0e008h),a		;b488   ; el registro 7
	call salto_mezcla		;b48b   ; al PSG
	ld a,003h		;b48e   ; 3: sigue
	ret			;b490
canal_orden:
	jp z,canal_ruido		;b491   ; 0xF0: ruido
	cp 0ffh		;b494   ; 0xFF: el final
	jr nz,canal_orden_f7		;b496
	ld a,001h		;b498   ; 1
	ret			;b49a
canal_orden_f7:
	cp 0f7h		;b49b   ; 0xF7: callar
	jr nz,canal_orden_fe		;b49d
	ld a,002h		;b49f   ; 2
	ret			;b4a1
canal_orden_fe:
	cp 0feh		;b4a2   ; 0xFE: al principio
	jr nz,canal_orden_fd		;b4a4
	ld hl,(0e2c5h)		;b4a6   ; la pieza otra vez desde su principio
	jr canal_orden_sigue		;b4a9
canal_orden_fd:		; 0xFD n: la marca 1 y cuantas veces
	cp 0fdh		;b4ab   ; 0xFD n: el primer bucle, n veces
	jr nz,canal_orden_fc		;b4ad
	inc hl			;b4af   ; cuantas veces...
	ld a,(hl)			;b4b0
	ld (iy+005h),a		;b4b1   ; ...en +5
	inc hl			;b4b4
	ld (0e2c7h),hl		;b4b5   ; la marca 1
	jr canal_orden_sigue		;b4b8
canal_orden_fc:		; 0xFC: vuelve a la marca 1 si quedan
	cp 0fch		;b4ba   ; 0xFC: el final del primer bucle
	jr nz,canal_orden_fb		;b4bc
	dec (iy+005h)		;b4be   ; una vez menos
	jr nz,canal_orden_fc_vuelve		;b4c1
	inc hl			;b4c3   ; ya: sigue
	jr canal_orden_sigue		;b4c4
canal_orden_fc_vuelve:
	ld hl,(0e2c7h)		;b4c6   ; a la marca 1
	jr canal_orden_sigue		;b4c9
canal_orden_fb:		; 0xFB n: la marca 2
	cp 0fbh		;b4cb   ; 0xFB n: el segundo bucle
	jr nz,canal_orden_fa		;b4cd
	inc hl			;b4cf   ; cuantas veces...
	ld a,(hl)			;b4d0
	ld (iy+006h),a		;b4d1   ; ...en +6
	inc hl			;b4d4
	ld (0e2c9h),hl		;b4d5   ; la marca 2
canal_orden_sigue:		; Sigue leyendo
	ld (0e2c3h),hl		;b4d8   ; por donde va
	jr canal_byte		;b4db
canal_orden_fa:		; 0xFA: vuelve a la marca 2
	cp 0fah		;b4dd   ; 0xFA: su final
	jr nz,canal_orden_f9		;b4df
	dec (iy+006h)		;b4e1   ; una vez menos
	jr nz,canal_orden_fa_vuelve		;b4e4
	inc hl			;b4e6   ; ya: sigue
	jr canal_orden_sigue		;b4e7
canal_orden_fa_vuelve:
	ld hl,(0e2c9h)		;b4e9   ; a la marca 2
	jr canal_orden_sigue		;b4ec
canal_orden_f9:		; 0xF9 n: la marca 3
	cp 0f9h		;b4ee   ; 0xF9 n: el tercer bucle
	jr nz,canal_orden_f8		;b4f0
	inc hl			;b4f2   ; cuantas veces...
	ld a,(hl)			;b4f3
	ld (iy+007h),a		;b4f4   ; ...en +7
	inc hl			;b4f7
	ld (0e2cbh),hl		;b4f8   ; la marca 3
	jr canal_orden_sigue		;b4fb
canal_orden_f8:		; 0xF8 (o mas): vuelve a la marca 3
	dec (iy+007h)		;b4fd   ; una vez menos
	jr nz,canal_orden_f8_vuelve		;b500
	inc hl			;b502   ; ya: sigue
	jr canal_orden_sigue		;b503
canal_orden_f8_vuelve:
	ld hl,(0e2cbh)		;b505   ; a la marca 3
	jr canal_orden_sigue		;b508
canal_ruido:		; 0xF0: una nota de ruido (el periodo y su barrido) y su duracion; el canal, a ruido en el registro 7
	call ruido_pon		;b50a   ; el ruido
	inc hl			;b50d   ; la duracion
	call nota_pon		;b50e
	inc hl			;b511   ; el siguiente
	ld (0e2c3h),hl		;b512   ; apuntado
	ld a,(0e008h)		;b515   ; el canal con ruido, sin tono
	res 3,a		;b518
	set 0,a		;b51a
	jp canal_mezcla		;b51c
ruido_barrido:		; El barrido del ruido: cada tantos cuadros, el periodo + el paso, unas cuantas veces
	ld a,(0e2b6h)		;b51f   ; hay ruido?
	and a			;b522
	ret z			;b523
	ld a,(0e2b7h)		;b524   ; con barrido?
	and a			;b527
	ret z			;b528
	ld a,(0e2b9h)		;b529   ; quedan pasos?
	and a			;b52c
	ret z			;b52d
	ld a,(0e2bbh)		;b52e   ; la espera...
	dec a			;b531   ; ...un cuadro menos
	ld (0e2bbh),a		;b532
	ret nz			;b535
	ld a,(0e2b9h)		;b536   ; un paso menos
	dec a			;b539
	ld (0e2b9h),a		;b53a
	ld a,(0e2bah)		;b53d   ; otra vez la espera
	ld (0e2bbh),a		;b540
	ld a,(0e2b8h)		;b543   ; el periodo...
	ld b,a			;b546
	ld a,(0e2bch)		;b547   ; ...mas el paso
	add a,b			;b54a
	ld (0e2b8h),a		;b54b
	jp psg_ruido		;b54e   ; al registro 6
canal_un_paso:		; Un paso del canal de trabajo (A, el canal 0-2, en 0xE2D5)
	ld (0e2d5h),a		;b551   ; el canal
	call canal_paso		;b554   ; un paso
	ret			;b557
pedido_mira:		; (HL) suena, (HL+1) pedido: acarreo si hay pedido y su numero es menor
	ld b,(hl)			;b558   ; el que suena
	inc hl			;b559
	ld a,(hl)			;b55a   ; el pedido
	and a			;b55b   ; ninguno?
	ret z			;b55c
	cp b			;b55d   ; menor?
	ret			;b55e
canal_cuenta:		; La cuenta de la nota (+1) y la envolvente: 1 si acabo; si no, 0
	inc hl			;b55f   ; la cuenta
	dec (hl)			;b560   ; un cuadro menos
	jp z,canal_cuenta_fin		;b561
	inc hl			;b564   ; la envolvente?
	ld a,(hl)			;b565
	and a			;b566   ; sin envolvente
	jp z,canal_cuenta_sigue		;b567
	cp 00fh		;b56a   ; 15: la envolvente corta
	jr z,canal_cuenta_15		;b56c
	inc hl			;b56e
	dec (hl)			;b56f   ; la cuenta de la envolvente
	jr nz,canal_cuenta_sigue		;b570
	dec hl			;b572
	ld a,(hl)			;b573   ; la espera...
	inc hl			;b574
	ld (hl),a			;b575   ; ...otra vez
	inc hl			;b576
	dec (hl)			;b577   ; el volumen, uno menos
	ld a,(hl)			;b578
	call psg_c		;b579   ; al PSG
	and a			;b57c
	jr nz,canal_cuenta_sigue		;b57d
	dec hl			;b57f   ; volumen 0: sin envolvente
	dec hl			;b580
	ld (hl),a			;b581
canal_cuenta_sigue:
	xor a			;b582
	ret			;b583
canal_cuenta_15:
	inc hl			;b584
	dec (hl)			;b585   ; la cuenta
	jr nz,canal_cuenta_sigue		;b586
	xor a			;b588
	dec hl			;b589
	ld (hl),a			;b58a   ; el volumen a 0
	call psg_c		;b58b
	ret			;b58e
canal_cuenta_fin:
	dec hl			;b58f   ; acabada
	xor a			;b590
	ld (hl),a			;b591   ; acabada: A = 1
	ld a,001h		;b592   ; 1
	ret			;b594
ruido_pon:		; El ruido: su periodo fijo o con barrido (periodo, cuantas veces, cada cuanto, el paso)
	ld (iy+000h),a		;b595   ; la nota
	inc hl			;b598
	ld a,(hl)			;b599   ; con barrido?
	ld (0e2b7h),a		;b59a   ; con barrido (cuantas veces)?
	and a			;b59d
	jr nz,ruido_barre		;b59e
	inc hl			;b5a0   ; sin barrido
	ld a,(hl)			;b5a1   ; el periodo...
	ld (0e2b8h),a		;b5a2
	call psg_ruido		;b5a5   ; ...registro 6
	xor a			;b5a8   ; sin barrido
	ld (0e2b9h),a		;b5a9
	ld (0e2bah),a		;b5ac
	ld (0e2bbh),a		;b5af
	ld (0e2bch),a		;b5b2
	inc a			;b5b5   ; hay ruido
	ld (0e2b6h),a		;b5b6
	ret			;b5b9
ruido_barre:
	ld (0e2b6h),a		;b5ba   ; el paso
	ld (0e2bch),a		;b5bd
	inc hl			;b5c0
	ld a,(hl)			;b5c1   ; el periodo...
	ld (0e2b8h),a		;b5c2
	call psg_ruido		;b5c5   ; ...registro 6
	inc hl			;b5c8
	ld a,(hl)			;b5c9   ; cuantas veces...
	ld (0e2b9h),a		;b5ca
	inc hl			;b5cd
	ld a,(hl)			;b5ce   ; ...cada cuanto
	ld (0e2bah),a		;b5cf
	ld (0e2bbh),a		;b5d2
	ret			;b5d5
nota_pon:		; Una nota: el byte de arriba es la duracion (la tabla 0xB627, o el byte siguiente con 0xE), el de abajo el volumen (15: la mitad)
	ld a,(hl)			;b5d6   ; la nota...
	ld (iy+000h),a		;b5d7
	and 00fh		;b5da   ; ...el volumen (la mitad baja)
	ld (iy+002h),a		;b5dc
	ld a,(hl)			;b5df   ; la duracion (la mitad alta)...
	and 0f0h		;b5e0
	rrca			;b5e2
	rrca			;b5e3
	rrca			;b5e4
	rrca			;b5e5
	cp 00eh		;b5e6   ; ...0xE: en el byte siguiente
	jr z,nota_duracion_byte		;b5e8
	ld de,0b627h		;b5ea   ; la tabla de duraciones
	add a,e			;b5ed   ; + la mitad alta
	jr nc,nota_duracion		;b5ee
	inc d			;b5f0   ; acarreo
nota_duracion:
	ld e,a			;b5f1
	ld a,(de)			;b5f2   ; la duracion
	jr nota_volumen		;b5f3
nota_duracion_byte:
	inc hl			;b5f5
	ld a,(hl)			;b5f6
nota_volumen:
	ld (iy+001h),a		;b5f7   ; la duracion
	ld a,(iy+002h)		;b5fa   ; volumen 15?
	cp 00fh		;b5fd
	jr nz,nota_cuenta		;b5ff
	ld a,(iy+001h)		;b601   ; la duracion...
	push bc			;b604   ; (guardado)
	ld c,a			;b605
	srl a		;b606   ; ...menos la mitad: la espera
	ld b,a			;b608
	ld a,c			;b609
	sub b			;b60a
	pop bc			;b60b   ; (recuperado)
nota_cuenta:
	ld (iy+003h),a		;b60c   ; la cuenta de la envolvente
	ld a,00fh		;b60f   ; el volumen 15
	ld (iy+004h),a		;b611
	jp psg_c		;b614   ; al PSG
tono_pon:		; El tono: si el primer byte es menor que 0x10, es el registro alto (B + 1) y le sigue el bajo; si no, solo el bajo (B)
	inc hl			;b617   ; el byte siguiente
	ld a,(hl)			;b618
	cp 010h		;b619   ; menos de 0x10?
	jr nc,tono_bajo		;b61b
	call psg_b1		;b61d   ; el registro alto
	inc hl			;b620   ; y el bajo
	ld a,(hl)			;b621
tono_bajo:
	call psg_b		;b622   ; el registro bajo
	inc hl			;b625   ; el siguiente
	ret			;b626

; ----------------------------------------------------------------------
; DATOS duraciones: Las duraciones de las notas (la mitad alta del byte, 0-13)
;   0xb627..0xb635  (14 bytes)
DATA_duraciones:
	defb 080h,060h,040h,030h,020h,018h,010h,00ch,008h,006h,004h,003h,002h,001h	; b627  .`@0 .........

; ======================================================================
; CODIGO 0xb635..0xb730  (251 bytes)
; ======================================================================


psg_c:		; WRTPSG: el registro C
	ld e,a			;b635   ; el valor...
	ld a,c			;b636   ; ...el registro C
psg:
	jp 00093h		;b637   ; WRTPSG
psg_b:		; El registro B
	ld e,a			;b63a   ; el registro B
	ld a,b			;b63b
	jr psg		;b63c
psg_b1:		; El registro B + 1
	ld e,a			;b63e   ; el registro B + 1
	ld a,b			;b63f
	inc a			;b640
	jr psg		;b641
psg_mezcla:		; El registro 7
	ld e,a			;b643   ; el registro 7
	ld a,007h		;b644
	jr psg		;b646
psg_ruido:		; El registro 6
	ld e,a			;b648   ; el registro 6
	ld a,006h		;b649
	jr psg		;b64b
musica_empieza:		; Una musica: los tres canales de la tabla 0xB312 (6 bytes por musica: la musica N en 0xB312 + 6N)
	ld hl,0b312h		;b64d   ; la tabla de musicas
	ld a,(0e2beh)		;b650   ; la pedida...
	ld (0e2bdh),a		;b653   ; ...suena
	ld b,a			;b656   ; x 6
	add a,b			;b657
	add a,b			;b658
	add a,b			;b659
	add a,b			;b65a
	add a,b			;b65b
	call canal_a_tabla		;b65c   ; el canal A
	inc hl			;b65f   ; los otros dos
	call canales_bc		;b660   ; B y C
	ld (0e28ah),a		;b663   ; sin nota en marcha (A = 0)
	ld (0e2beh),a		;b666   ; el pedido, gastado
	ld a,0f8h		;b669   ; el mezclador: los tres con tono
mezcla_y_canal_a:
	ld (0e008h),a		;b66b   ; el registro 7
	call salto_mezcla		;b66e   ; al PSG
	jp sonido_canal_a		;b671   ; al canal A
musica_acaba:		; La musica acabada: otra pedida, o todo callado
	ld a,(0e2beh)		;b674   ; otra pedida?
	and a			;b677
	jr nz,musica_empieza		;b678   ; empieza
	ld (0e2bdh),a		;b67a   ; ya no suena
	dec a			;b67d   ; 0xFF
silencio_motor:		; Todo callado: el registro 7 a A (0xFF) y el estado del motor (0xE280-0xE2C2) a cero
	ld (0e008h),a		;b67e   ; el registro 7
	call salto_mezcla		;b681   ; al PSG
	ld hl,0e280h		;b684   ; el motor...
	ld b,043h		;b687   ; ...0x43 bytes...
ceros_pon:		; B bytes a cero desde HL
	ld (hl),000h		;b689   ; ...a cero
	inc hl			;b68b
	djnz ceros_pon		;b68c   ; B veces
	ret			;b68e
efecto_a_empieza:		; Un efecto del canal A (0xB336 + el numero x 2): el canal A con tono
	ld hl,0b336h		;b68f   ; la tabla de efectos de A
	ld a,(0e2c0h)		;b692   ; el pedido...
	ld (0e2bfh),a		;b695   ; ...suena
	add a,a			;b698   ; x 2
	call canal_a_tabla		;b699   ; el canal A
	xor a			;b69c   ; sin nota en marcha
	ld (0e28ah),a		;b69d
	ld (0e2c0h),a		;b6a0   ; el pedido, gastado
	ld a,(0e008h)		;b6a3   ; el canal A con tono
	res 0,a		;b6a6
	ld (0e008h),a		;b6a8
	call salto_mezcla		;b6ab   ; al PSG
	ld hl,0e2c0h		;b6ae   ; y los demas
	jp sonido_mira_bc		;b6b1
sonido_a_acaba:		; El efecto del canal A acabado (0xF7): otro pedido, o el canal A callado
	ld a,(0e2c0h)		;b6b4   ; otro pedido?
	and a			;b6b7
	jr nz,efecto_a_empieza		;b6b8
	ld (0e2bfh),a		;b6ba   ; ninguno suena
	ld hl,0e280h		;b6bd   ; el canal A...
	ld b,012h		;b6c0   ; ...18 bytes...
	call ceros_pon		;b6c2   ; ...a cero
	ld a,(0e008h)		;b6c5   ; el mezclador: A callado
	or 009h		;b6c8
mezcla_pon:
	ld (0e008h),a		;b6ca   ; el registro 7
	jp salto_mezcla		;b6cd   ; al PSG
efecto_bc_empieza:		; Un efecto de los canales B y C (0xB342 + el numero x 4): B y C con tono
	ld hl,0b342h		;b6d0   ; la tabla de efectos de B y C
	ld a,(0e2c2h)		;b6d3   ; el pedido...
	ld (0e2c1h),a		;b6d6   ; ...suena
	add a,a			;b6d9   ; x 4
	add a,a			;b6da
	add a,l			;b6db   ; + la tabla
	ld l,a			;b6dc
	call canales_bc		;b6dd   ; los canales B y C
	ld (0e2c2h),a		;b6e0   ; el pedido, gastado (A = 0)
	ld a,(0e008h)		;b6e3   ; el mezclador: B y C con tono
	and 0f9h		;b6e6
	jp mezcla_y_canal_a		;b6e8   ; al PSG y al canal A
efecto_bc_acaba:		; El efecto de B y C acabado: otro pedido, o B y C callados
	ld a,(0e2c2h)		;b6eb   ; otro pedido?
	and a			;b6ee
	jr nz,efecto_bc_empieza		;b6ef
	ld (0e2c1h),a		;b6f1   ; ya no suena
	ld hl,0e292h		;b6f4   ; los canales B y C...
	ld b,024h		;b6f7   ; ...a cero
	call ceros_pon		;b6f9   ; a cero
	ld a,(0e008h)		;b6fc   ; el mezclador: B y C callados
	or 036h		;b6ff
	jr mezcla_pon		;b701
canales_bc:		; Los canales B y C desde la tabla HL
	ld e,(hl)			;b703   ; la pieza del canal B
	inc hl			;b704
	ld d,(hl)			;b705
	ld (0e292h),de		;b706   ; ...y su principio
	ld (0e294h),de		;b70a
	inc hl			;b70e
	ld e,(hl)			;b70f   ; la del canal C
	inc hl			;b710
	ld d,(hl)			;b711
	ld (0e2a4h),de		;b712
	ld (0e2a6h),de		;b716
	xor a			;b71a   ; sin nota en marcha
	ld (0e29ch),a		;b71b
	ld (0e2aeh),a		;b71e
	ret			;b721
canal_a_tabla:		; El canal A desde la tabla
	add a,l			;b722   ; + la musica x 6
	ld l,a			;b723
	ld e,(hl)			;b724   ; el canal A: su pieza...
	inc hl			;b725
	ld d,(hl)			;b726
	ld (0e280h),de		;b727   ; ...y su principio
	ld (0e282h),de		;b72b
	ret			;b72f

; ----------------------------------------------------------------------
; DATOS piezas: Las piezas de las musicas y los efectos (los punteros de
;   0xB312-0xB351): notas, ruidos y ordenes 0xF0-0xFF
;   0xb730..0xc000  (2256 bytes)
DATA_piezas:
	defb 01ch,000h,000h,0f7h,0c1h,000h,0d0h,0c1h,0c0h,0c1h,0b0h,0c1h,0a0h,0c1h,0b0h,0c1h	; b730  ................
	defb 0a0h,0c1h,090h,0c1h,080h,0c1h,090h,0f7h,0c1h,000h,080h,0c1h,002h,080h,0c1h,000h	; b740  ................
	defb 070h,0c1h,002h,070h,0c1h,000h,060h,0c1h,002h,060h,0f7h,01ch,000h,000h,0ffh,026h	; b750  p..p..`..`.....&
	defb 000h,050h,0ffh,026h,000h,040h,0ffh,081h,000h,000h,026h,020h,0ffh,065h,002h,0fah	; b760  .P.&.@....& .e..
	defb 083h,001h,07dh,061h,000h,000h,083h,001h,0fch,065h,001h,0ach,083h,001h,0c5h,065h	; b770  ..}a.....e.....e
	defb 001h,0fch,083h,002h,03bh,083h,002h,0fah,081h,000h,000h,083h,002h,0fah,083h,002h	; b780  ....;...........
	defb 05dh,083h,002h,03bh,083h,001h,0fch,083h,002h,05dh,081h,000h,000h,083h,002h,0fah	; b790  ]..;.....]......
	defb 065h,003h,057h,081h,003h,08ah,0fdh,002h,083h,003h,0f9h,081h,000h,000h,083h,003h	; b7a0  e.W.............
	defb 0f9h,083h,003h,0f9h,083h,003h,0f9h,083h,003h,0f9h,0fch,083h,003h,0f9h,083h,003h	; b7b0  ................
	defb 0f9h,083h,003h,0f9h,031h,000h,000h,0ffh,065h,000h,0a0h,083h,000h,097h,061h,000h	; b7c0  ....1...e.....a.
	defb 000h,083h,000h,0beh,083h,000h,0feh,083h,000h,0feh,083h,000h,0feh,083h,000h,0feh	; b7d0  ................
	defb 081h,000h,000h,083h,000h,0feh,065h,000h,0a0h,083h,000h,097h,065h,000h,0a0h,083h	; b7e0  ......e.....e...
	defb 000h,097h,083h,000h,0beh,081h,000h,000h,083h,000h,0feh,065h,001h,01dh,083h,001h	; b7f0  ...........e....
	defb 02eh,0fdh,002h,083h,001h,094h,083h,001h,053h,083h,001h,01dh,065h,000h,0e2h,083h	; b800  ........S...e...
	defb 000h,0f0h,0fch,083h,001h,094h,083h,001h,094h,083h,001h,094h,083h,001h,094h,083h	; b810  ................
	defb 001h,07dh,083h,001h,068h,056h,001h,053h,0ffh,0f0h,000h,004h,081h,081h,000h,000h	; b820  .}..hV.S........
	defb 0f0h,000h,004h,081h,061h,000h,000h,0f0h,000h,004h,081h,0f0h,000h,004h,081h,0f0h	; b830  ....a...........
	defb 000h,004h,081h,0f0h,000h,004h,081h,0f0h,000h,004h,081h,081h,000h,000h,0f0h,000h	; b840  ................
	defb 004h,081h,0f0h,000h,004h,081h,081h,000h,000h,0f0h,000h,004h,081h,061h,000h,000h	; b850  .............a..
	defb 0f0h,000h,004h,081h,0f0h,000h,004h,081h,0f0h,000h,004h,081h,0f0h,000h,004h,081h	; b860  ................
	defb 0f0h,000h,004h,081h,081h,000h,000h,0f0h,000h,004h,081h,0fdh,002h,0f0h,000h,004h	; b870  ................
	defb 081h,0f0h,000h,004h,081h,0f0h,000h,004h,081h,0f0h,000h,004h,081h,081h,000h,000h	; b880  ................
	defb 0f0h,000h,004h,081h,0fch,0f0h,000h,004h,081h,0f0h,000h,004h,081h,0f0h,000h,004h	; b890  ................
	defb 081h,083h,000h,0feh,083h,000h,0e2h,083h,000h,0d6h,056h,000h,0cah,0ffh,031h,000h	; b8a0  ..........V...1.
